(function () {
/* ===== 1_core.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 1/4 Core
 * Host / Storage / Chuẩn hóa model / Vùng bảo vệ / Chọn vùng tĩnh
 * Thiết kế đúc kết từ thực chiến của v5/v6/v7
 * ========================================================================== */

var VERSION = '0.5';
var TAG = '[AR6]';
var CFG_KEY = 'ar6.cfg';
var LOG_KEY = 'ar6.log';
var MAX_LOG = 40;

/* ---------------- Host ---------------- */

function resolveHostWindow() {
  var cands = [];
  try { if (window.top) cands.push(window.top); } catch (e) {}
  try { if (window.parent) cands.push(window.parent); } catch (e) {}
  cands.push(window);
  for (var i = 0; i < cands.length; i++) {
    var w = cands[i];
    try {
      if (w && w.document && w.document.body && w.document.documentElement) return w;
    } catch (e) {}
  }
  return window;
}

/* Window nơi script đang chạy — eventOn/getButtonEvent của SillyTavern helper thường được inject ở tầng này */
var SELF_WIN = null;
try {
  SELF_WIN = (typeof window !== 'undefined' && window) ? window
    : ((typeof globalThis !== 'undefined') ? globalThis : null);
} catch (e) { SELF_WIN = null; }

var HOST = resolveHostWindow();
var DOC = null;
try { DOC = HOST.document; } catch (e) {}
if (!DOC) { try { DOC = document; } catch (e) {} }

/* ---------------- Storage ---------------- */

var CFG_DEFAULT = {
  enabled: true,          // Công tắc tổng
  pin: true,              // Khóa cứng tham số route (xóa models[] / allow_fallbacks=false)
  think: 'off',           // off | high (chỉ bù vào khi thiếu trường)
  refract: 'off',         // off | light | mid (mức vi nhiễu 3 luồng)
  observe: true,          // Bộ quan sát zero-lock
  dualBase: '',           // Fingerprint kênh đôi: base url
  dualKey: '',            // Fingerprint kênh đôi: key
  min: false,             // Thu gọn panel thành bong bóng nhỏ
  xhr: false,             // Có hook XMLHttpRequest không (mặc định tắt; chỉ dùng fetch sẽ ổn định hơn)
  safe: false,            // Chế độ an toàn: hoàn toàn không hook, chỉ giữ panel và banner (dùng để debug)
  mx: null,               // Tọa độ left của cửa sổ nổi mobile (px, null = mặc định góc dưới bên phải)
  my: null,               // Tọa độ top của cửa sổ nổi mobile
  keep: 30,
  alias: '',              /* Khóa cứng alias: khi không rỗng, ghi đè model của request thành giá trị này */
  refractMode: 'stable',  /* stable = biến dạng cố định theo session (giữ prefix cache) | random = ngẫu nhiên mỗi lượt (thử nghiệm) */
  refractSeed: '',        /* User salt: thay đổi giá trị này sẽ đổi toàn bộ kết quả biến dạng */
  saltWin: 30,            /* Window salt: cùng một chat giữ nguyên một bộ biến dạng trong N phút (0 = tắt) */
  floatMode: 'dock',      /* dock = hít mép ẩn một nửa | float = luôn hiển thị | tuck = tay cầm sát mép */
  floatSize: 44, floatShape: 'circle', floatOpacity: 45, floatDock: 40,
  floatIcon: '', floatBg: '#ffffff', floatBorder: true, floatShadow: true,
  floatX: null, floatY: null, fxN: 1, fyN: 0.82, fEdge: '',
  /* v7.1 Phá giáp: off | safe (chỉ cứu vãn sau khi xảy ra, không sửa request) | strong (sửa request + cứu vãn sau khi xảy ra) */
  jail: 'off',
  jailConfirm: true,      /* Hỏi trước khi khắc phục (tắt = tự động khắc phục) */
  jailMax: 2,             /* Số lần tự động viết tiếp tối đa trong cùng một lượt */
  jailTok: true,          /* Mức mạnh: bảo đảm max_tokens sàn 2048 (chỉ tăng không giảm) */
  jailSafe: true,         /* Mức mạnh: safetySettings của hệ Gemini đều là BLOCK_NONE */
  jailPre: false,         /* Mức mạnh: khung tiền kiểm duyệt (system + user mỗi bên một câu) */
  jailText: false,        /* Mức mạnh: khế ước output (gắn vào đuôi tin nhắn user cuối cùng) */
  peek: true,             /* Clone response body qua nhánh phụ để lấy model/modelVersion (chỉ đọc, không block) */
  cardAuto: true,         /* Tự động bật card bằng chứng khi bị phán đoán là "bị đổi/mất suy nghĩ" */
  /* v8.31 Tầng tự sự: off | lite | full (gắn vào đuôi tin nhắn user cuối cùng, chỉ sửa bản sao request) */
  know: 'off',            /* Chống toàn tri */
  charm: 'off',           /* Xóa nịnh nọt */
  /* v0.13 Phạm vi kiểm tra: chỉ những model có nguy cơ bị route mới cần phán đoán "có bị đổi hay không" */
  helpX: null,
  helpY: null,
  helpBig: false,
  scope: 'all',           /* all = kiểm tra toàn bộ | only = chỉ kiểm tra trong danh sách | skip = bỏ qua danh sách */
  scopeList: 'deepseek',  /* Từ khóa phân tách bằng dấu phẩy, khớp theo chuỗi con, không phân biệt hoa thường */
  v: 831,
  fx: 'full',
  rm: false,
  padSeen: false
};

var cfg = null;

function ar6Num(v, def, lo, hi) {
  var n = Number(v);
  if (!isFinite(n)) n = def;
  return Math.max(lo, Math.min(hi, n));
}

function ar6Pick(v, list, def) {
  var s = String(v == null ? '' : v);
  for (var i = 0; i < list.length; i++) if (list[i] === s) return s;
  return def;
}

/* Khử độc các trường của nút nổi: NaN sẽ gây lỗi left:NaNpx, hidden là đường một chiều */
function sanitizeFloat(d) {
  if (!d || typeof d !== 'object') return;
  if (String(d.floatMode) === 'hidden') d.floatMode = 'tuck';
  d.floatMode = ar6Pick(d.floatMode, ['dock', 'float', 'tuck'], 'dock');
  d.floatSize = Math.round(ar6Num(d.floatSize, 44, 28, 80));
  d.floatOpacity = Math.round(ar6Num(d.floatOpacity, 45, 10, 100));
  d.floatDock = Math.round(ar6Num(d.floatDock, 45, 20, 80));
  d.floatShape = ar6Pick(d.floatShape, ['circle', 'square'], 'circle');
  if (!/^#[0-9a-fA-F]{6}$/.test(String(d.floatBg))) d.floatBg = '#0d1117';
  var ico = String(d.floatIcon || '');
  d.floatIcon = (ico.length <= 4096 && /^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,)/i.test(ico)) ? ico : '';
  d.floatBorder = d.floatBorder !== false;
  d.floatShadow = d.floatShadow !== false;
  d.fxN = ar6Num(d.fxN, 1, 0, 1);
  d.fyN = ar6Num(d.fyN, 0.82, 0, 1);
  d.fEdge = ar6Pick(d.fEdge, ['l', 'r'], d.fxN < 0.5 ? 'l' : 'r');
  if (typeof d.mx !== 'number' || !isFinite(d.mx)) d.mx = null;
  if (typeof d.my !== 'number' || !isFinite(d.my)) d.my = null;
  d.fx = ar6Pick(d.fx, ['full', 'calm', 'off'], 'full');
  d.rm = !!d.rm;
  d.min = !!d.min;
}

function readCfg() {
  var d = {};
  for (var k in CFG_DEFAULT) d[k] = CFG_DEFAULT[k];
  try {
    var raw = HOST.localStorage.getItem(CFG_KEY);
    if (raw) {
      var s = JSON.parse(raw);
      for (var k2 in s) if (Object.prototype.hasOwnProperty.call(CFG_DEFAULT, k2)) d[k2] = s[k2];
      // Migration phiên bản: cấu hình v1 không có trường refract thì ép về off (không kế thừa công tắc noise cũ)
      if (!('refract' in s)) d.refract = 'off';
      /* 6.6 Migration: Hook XHR mặc định bật ở bản cũ sẽ kế thừa sang cấu hình cũ, ép tắt một lần */
      if (s.v !== 831) {
        d.jailConfirm = true;
        /* Chỉ cấu hình v6 trở về trước mới ép tắt XHR; từ v7.0.0 trở đi giữ nguyên lựa chọn của user */
        if (typeof s.v !== 'number' || s.v < 700) d.xhr = false;
        if (!('peek' in s) || typeof s.v !== 'number' || s.v < 730) d.peek = true;
        if (!('cardAuto' in s)) d.cardAuto = true;
        if (!('alias' in s)) d.alias = '';
        if (!('refractMode' in s)) d.refractMode = 'stable';
        if (!('floatMode' in s)) d.floatMode = 'dock';
        if (!('jail' in s)) d.jail = 'off';
        if (!('jailConfirm' in s)) d.jailConfirm = true;
        if (!('jailMax' in s)) d.jailMax = 2;
        if (!('jailTok' in s)) d.jailTok = true;
        if (!('jailSafe' in s)) d.jailSafe = true;
        if (!('jailPre' in s)) d.jailPre = false;
        if (!('jailText' in s)) d.jailText = false;
        if (!('saltWin' in s)) d.saltWin = 30;
        if (!('fxN' in s)) { d.fxN = 1; d.fyN = 0.82; d.fEdge = ''; }
        if (!('know' in s)) d.know = 'off';
        if (!('charm' in s)) d.charm = 'off';
        if (!('helpX' in s)) d.helpX = null;
        if (!('helpY' in s)) d.helpY = null;
        if (!('helpBig' in s)) d.helpBig = false;
        d.v = 831;
        try { HOST.localStorage.setItem(CFG_KEY, JSON.stringify(d)); } catch (e3) {}
      }
    }
  } catch (e) {}
  try { sanitizeFloat(d); } catch (eS) {}
  return d;
}

/* Seed ổn định: cùng một seedStr sẽ luôn ra cùng một số, dùng để tạo vi nhiễu "cố định trong session" */
function hashStr(s) {
  var h = 5381, i;
  s = String(s || '');
  for (i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return h >>> 0;
}

/* v7.4 Window salt: Giữ nguyên một bộ biến dạng trong cùng một "chat + khung thời gian" ——
   Trong khung thì prefix ổn định (hit cache), khác khung thì luân phiên đổi (fingerprint không bị cố định). */
function chatTag() {
  try {
    var c = stCtx();
    if (c) {
      var id = c.chatId || c.chat_id || '';
      if (id) return 'c' + String(id).slice(0, 20);
      var arr = c.chat;
      if (arr && arr.length) {
        var m0 = arr[0] || {};
        var s0 = String(m0.send_date || '') + '|' + String(m0.name || '') + '|' + String(arr.length);
        return 'h' + hashStr(s0);
      }
    }
  } catch (e) {}
  return 'nochat';
}

function saltWindow() {
  var n = Number(cfg.saltWin);
  if (!isFinite(n) || n <= 0) return 0;
  return Math.min(240, Math.round(n));
}

function saltKey(tag) {
  var w = saltWindow();
  var bucket = w ? String(Math.floor(Date.now() / (w * 60000))) : 'free';
  return chatTag() + '|' + bucket + '|' + String(tag || '');
}

function saveCfg() {
  try { HOST.localStorage.setItem(CFG_KEY, JSON.stringify(cfg)); } catch (e) {}
}

function readLog() {
  try {
    var raw = HOST.localStorage.getItem(LOG_KEY);
    if (!raw) return [];
    var arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

function pushLog(rec) {
  var arr = readLog();
  arr.unshift(rec);              /* Mới nhất lên đầu: bảng panel lấy trực tiếp N dòng đầu */
  var cap = MAX_LOG;
  if (typeof cfg === 'object' && cfg && cfg.keep) cap = Math.min(MAX_LOG, Math.max(10, cfg.keep));
  if (arr.length > cap) arr.length = cap;
  try { HOST.localStorage.setItem(LOG_KEY, JSON.stringify(arr)); } catch (e) {}
  return arr;
}

cfg = readCfg();

/* ---------------- Chuẩn hóa model ---------------- */

var KNOWN_PREFIX = /^(?:models\/|google\/|openrouter\/|vertex_ai\/|vertex\/|gemini\/|custom\/|litellm\/|fireworks\/|together\/|pggo-|bdgo-|aihubmix-|proxy-|pg-)/;

function normModel(s) {
  var t = String(s == null ? '' : s).trim();
  if (!t) return '';
  try { t = decodeURIComponent(t); } catch (e) {}
  t = t.toLowerCase().split('?')[0].replace(/^https?:\/\/[^/]+\//, '');
  for (var i = 0; i < 6; i++) {
    var before = t;
    t = t.replace(/^[^\x00-\x7f]+[-_\s]*/, '').replace(KNOWN_PREFIX, '');
    if (t === before) break;
  }
  t = t.replace(/:(generatecontent|streamgeneratecontent|counttokens).*$/, '');
  return t.trim();
}

function isOpaqueModel(s) {
  var m = normModel(s);
  if (!m) return true;
  return /^(?:auto|router|default|unknown|any|best|lb)$/.test(m);
}

function isNonChatModel(s) {
  var m = normModel(s);
  return /(?:embedding|embedcontent|imagen|veo|aqa|image-only|tts|audio-only)/.test(m);
}

function isGeminiLike(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return false;
  if (/(?:gemma|claude|deepseek|gpt|o1|o3|qwen|llama|glm|ernie)/.test(m)) return false;
  return /gemini/.test(m) || /argon|flash|lite|pro/.test(m) === false ? /gemini/.test(m) : /gemini/.test(m);
}

/* Tier: 1=lite/8b, 2=flash, 3=pro, 4=argon/ultra, 0=chưa rõ */
function tierOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return 0;
  if (/(?:flash[-_. ]?lite|flash[-_. ]?8b|\blite\b|\bnano\b)/.test(m)) return 1;
  if (/\b(?:argon|ultra)\b/.test(m)) return 4;
  if (/\bpro\b/.test(m)) return 3;
  if (/\bflash\b/.test(m)) return 2;
  return 0;
}

function isProLike(s) {
  var t = tierOf(s);
  return t === 3 || t === 4;
}

/* Hãng: Bảng phân cấp không thể so sánh chéo giữa các hãng, phân họ trước rồi mới so cấp */
function familyOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return '';
  if (/gemini|gemma|argon|palm\b/.test(m)) return 'google';
  if (/deepseek/.test(m)) return 'deepseek';
  if (/claude|anthropic/.test(m)) return 'anthropic';
  if (/gpt|chatgpt|^o[1-4](?:-|$)|openai/.test(m)) return 'openai';
  if (/qwen|glm|ernie|llama|mistral|kimi|moonshot|doubao|hunyuan|spark/.test(m)) return 'other';
  return '';
}

function shortName(s) {
  var m = normModel(s);
  if (!m) return '—';
  return m.length > 26 ? m.slice(0, 25) + '…' : m;
}

/* ---------------- Ước tính token (CJK 0.85 / Latin 1÷3.5 / Khác 0.9) ---------------- */

function estimateTokens(str) {
  if (typeof str !== 'string' || !str) return 0;
  var cjk = 0, latin = 0, other = 0;
  for (var i = 0; i < str.length; i++) {
    var cp = str.codePointAt ? str.codePointAt(i) : str.charCodeAt(i);
    if (cp > 0xffff) i++;
    if (cp >= 0x3400 && cp <= 0x9fff) cjk++;
    else if (cp <= 0x7f) latin++;
    else other++;
  }
  return Math.ceil(cjk * 0.85 + latin / 3.5 + other * 0.9);
}

/* ---------------- Vùng bảo vệ ----------------
 * 12 loại: YAML frontmatter / code fence / inline code / macro SillyTavern / thẻ state machine / fence giao thức
 *        / bản thân thẻ XML / chú thích và định nghĩa trích dẫn sẵn có / URL và liên kết / LaTeX / lời thoại trong ngoặc kép / thẻ chưa đóng đến cuối văn bản
 */

var HARD_TAGS = 'UpdateVariable|JSONPatch|jsonpatch|mvu|status|StatusBlock|Status_block|state|panel|options|tool_call|function_call|run_tool_replacement|worldcustomfunction|worldsystem|KonataExtraInformation|IzumiEdit|stat_data|delta_data|variables|StatusPlaceHolderImpl|thinking|think|dream_think|simple_thinking|interleav|Interleaved_thinking|interactive_input';

var SPAN_RULES = [
  /(^|\n)([ \t]{0,3})(`{3,}|~{3,})[^\n]*\n[\s\S]*?\n\2\3[ \t]*(?=\n|$)/g,
  /(`+)([^`\n]+?)\1/g,
  /\{\{[\s\S]{0,4000}?\}\}|<%[\s\S]{0,4000}?%>/g,
  new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>[\\s\\S]*?<\\/\\1\\s*>', 'gi'),
  /<<<\|catgodml\|[\s\S]*?>>>|\[\[IZUMI_CHAT_INDEX_V1\]\]/g,
  /<\/?[A-Za-z\u4e00-\u9fa5][\w:\u4e00-\u9fa5.-]*(?:\s[^<>]{0,400})?>/g,
  /<!--[\s\S]*?-->|^\[\/\/\]:\s*#\s*\([^\n]*\)/gm,
  /\bhttps?:\/\/[^\s<>()]+|!?\[[^\]]*\]\([^)]+\)/g,
  /\$\$[\s\S]*?\$\$|\$[^$\n]{1,400}\$|\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]/g,
  /“[^”\n]{1,600}”|「[^」\n]{1,600}」|『[^』\n]{1,600}』|"[^"\n]{1,600}"/g
];

function collectSpans(text) {
  var spans = [];
  if (typeof text !== 'string' || !text) return spans;

  var yaml = /^---[ \t]*\r?\n[\s\S]{1,4000}?\r?\n---[ \t]*(?:\r?\n|$)/.exec(text);
  if (yaml) spans.push([0, yaml[0].length]);

  var trimmed = text.trim();
  if ((trimmed.charAt(0) === '{' && trimmed.slice(-1) === '}') ||
      (trimmed.charAt(0) === '[' && trimmed.slice(-1) === ']')) {
    try { JSON.parse(trimmed); return [[0, text.length]]; } catch (e) {}
  }

  for (var r = 0; r < SPAN_RULES.length; r++) {
    var re = new RegExp(SPAN_RULES[r].source, SPAN_RULES[r].flags);
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 4000) {
      var s = m.index + (m[1] && m[1].length && SPAN_RULES[r] === SPAN_RULES[0] ? m[2].length : 0);
      spans.push([m.index, m.index + m[0].length]);
      if (m[0].length === 0) re.lastIndex++;
    }
  }

  // Thẻ cứng chưa đóng: bảo vệ từ thẻ mở cho đến tận cùng văn bản
  var openRe = new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>', 'gi');
  var om;
  var oguard = 0;
  while ((om = openRe.exec(text)) !== null && oguard++ < 500) {
    var name = om[1];
    var closeRe = new RegExp('<\\/' + name + '\\s*>', 'i');
    var after = text.slice(om.index + om[0].length);
    if (!closeRe.test(after)) spans.push([om.index, text.length]);
  }

  spans.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
  var merged = [];
  for (var i = 0; i < spans.length; i++) {
    var cur = spans[i];
    if (cur[1] <= cur[0]) continue;
    if (merged.length && cur[0] <= merged[merged.length - 1][1]) {
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], cur[1]);
    } else merged.push([cur[0], cur[1]]);
  }
  return merged;
}

function isProtected(spans, start, end) {
  if (!spans || !spans.length) return false;
  var lo = 0, hi = spans.length - 1;
  var qs = Math.min(start, end);
  var qe = Math.max(start + 1, end);
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (qe <= spans[mid][0]) hi = mid - 1;
    else if (qs >= spans[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/* ---------------- Đánh giá điểm vùng tĩnh ---------------- */

var INSTR_WORDS = /bắt buộc|cấm|không được|nghiêm cấm|xin đừng|nhất thiết|nghiêm ngặt|quy tắc|chuẩn mực|quy phạm|định dạng|output|thiết lập|yêu cầu|lưu ý|quan trọng|ưu tiên|ví dụ|chỉ thị|tuân thủ|nhập vai|miêu tả|văn phong|số từ|đoạn văn|\b(?:must|shall|require|format|rule|instruction|guideline|never|do not|output|response|system|character|roleplay|constraint)\b/gi;
var NARR_WORDS = /nói|hỏi|nhìn|hướng mắt|bước vào|quay người|cười khẽ|thì thầm|nhỏ giọng|im lặng|ngẩng đầu|thở dài|ánh mắt|tầm mắt|hơi thở|ngón tay|ngoài cửa sổ|khóe miệng|gật đầu|lắc đầu|nghĩ thầm|âm thanh|\b(?:said|asked|looked|smiled|whispered|sighed|walked|turned|nodded|eyes|voice|hand|felt|thought)\b/gi;
var QUOTE_RE = /“[^”\n]{2,200}”|「[^」\n]{2,200}」|"[^"\n]{2,200}"/g;
var MARKUP_RE = /^(?:[ \t]*#{1,6}[ \t]+\S|[ \t]*[-+*][ \t]+\S|[ \t]*\d+[.)][ \t]+\S|[ \t]*>[ \t]+\S)|<\/?[A-Za-z][\w:.-]*\b/gm;

function density(text, re) {
  if (!text) return 0;
  var hits = text.match(new RegExp(re.source, re.flags));
  return ((hits ? hits.length : 0) * 1000) / Math.max(80, text.length);
}

function staticScore(node, total) {
  var text = node.text || '';
  if (text.replace(/\s/g, '').length < 40) return -50;
  if (node.isLastUser) return -100;
  if (node.isPrefill) return -90;

  var score = 0;
  var role = node.role;
  if (role === 'system' || role === 'developer') score += 42;
  else if (role === 'user') score += 8;
  else if (role === 'assistant' || role === 'model') score -= 25;

  if (node.index === 0) score += 20;
  else if (node.index < 3) score += 14;

  var ins = density(text, INSTR_WORDS);
  var nar = density(text, NARR_WORDS);
  var quo = density(text, QUOTE_RE);
  var mark = density(text, MARKUP_RE);

  score += Math.min(32, ins * 3.8);
  score += Math.min(16, mark * 2.5);
  score -= Math.min(38, nar * 2.6 + quo * 3.2);
  if (ins >= 3.5 && mark >= 2.0 && nar < 2.0) score += 18;

  return Math.max(-100, Math.min(100, score));
}

function hasRuleMarkup(text) {
  if (typeof text !== 'string' || text.length < 80) return false;
  if (/^[ \t]*#{1,6}[ \t]+\S/m.test(text)) return true;
  var lists = text.match(/^[ \t]*(?:[-+*]|\d+[.)])[ \t]+\S/gm);
  if (lists && lists.length >= 2) return true;
  return /<(?:rules?|instructions?|guidelines?|system|config|writing_style|world_info)\b/i.test(text);
}

/* Dải lịch sử: assistant đầu tiên trở về sau (bao gồm cả user kích hoạt nó) đều tính là lịch sử */
function findHistoryBand(nodes) {
  var firstAssistant = -1;
  for (var i = 0; i < nodes.length; i++) {
    if (nodes[i].role === 'assistant' || nodes[i].role === 'model') { firstAssistant = i; break; }
  }
  if (firstAssistant < 0) return null;
  var start = firstAssistant;
  for (var j = firstAssistant - 1; j >= 0; j--) {
    if (nodes[j].role === 'user') { start = j; break; }
  }
  var lastUser = -1;
  for (var k = nodes.length - 1; k >= 0; k--) if (nodes[k].isLastUser) { lastUser = k; break; }
  var end = lastUser >= 0 ? lastUser - 1 : nodes.length - 1;
  if (end < start) return null;
  return { start: start, end: end, memberCount: end - start + 1 };
}

/* ---------------- Chọn vùng ---------------- */

function getMsgText(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      var p = m.content[i];
      if (p && p.type === 'text' && typeof p.text === 'string') return p.text;
    }
  }
  if (typeof m.text === 'string') return m.text;
  return '';
}

function pickZones(inner, channel, maxZones) {
  var zones = [];
  var msgs = Array.isArray(inner.messages) ? inner.messages : null;

  if (!msgs && (Array.isArray(inner.contents) || inner.systemInstruction)) {
    var si = inner.systemInstruction;
    if (si && Array.isArray(si.parts)) {
      for (var p = 0; p < si.parts.length; p++) {
        (function (part) {
          if (!part || typeof part.text !== 'string') return;
          if (part.text.replace(/\s/g, '').length < 60) return;
          zones.push({ get: function () { return part.text; }, set: function (v) { part.text = v; }, score: 100, why: 'systemInstruction.parts[' + p + ']' });
        })(si.parts[p]);
      }
    } else if (si && typeof si.text === 'string' && si.text.replace(/\s/g, '').length >= 60) {
      zones.push({ get: function () { return si.text; }, set: function (v) { si.text = v; }, score: 100, why: 'systemInstruction.text' });
    }
    return zones.slice(0, maxZones);
  }

  if (!msgs || !msgs.length) return zones;

  var lastUserIdx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var r = String(msgs[i] && msgs[i].role || '').toLowerCase();
    if (r === 'user' && getMsgText(msgs[i]).trim()) { lastUserIdx = i; break; }
  }

  var nodes = [];
  for (var j = 0; j < msgs.length; j++) {
    var m = msgs[j];
    if (!m || typeof m !== 'object') continue;
    var role = String(m.role || 'user').toLowerCase();
    if (role === 'tool' || role === 'function' || m.tool_calls || m.function_call) continue;
    var text = getMsgText(m);
    if (!text || !text.trim()) continue;
    nodes.push({
      index: j, role: role, text: text,
      isLastUser: j === lastUserIdx,
      isPrefill: (role === 'assistant' || role === 'model') && j === msgs.length - 1 && j > lastUserIdx,
      msg: m
    });
  }

  var band = findHistoryBand(nodes);
  var headIdx = band ? band.start : nodes.length;

  for (var k = 0; k < nodes.length; k++) {
    var n = nodes[k];
    if (n.isLastUser || n.isPrefill) continue;
    if (n.role === 'assistant' || n.role === 'model') continue;
    if (band && k >= band.start && k <= band.end) continue;
    var sc = staticScore(n, nodes.length);
    if (sc < 52) continue;
    if (n.role === 'user' && !hasRuleMarkup(n.text)) continue;
    zones.push({
      score: sc,
      why: 'msg[' + n.index + '](' + n.role + ',' + Math.round(sc) + ')',
      get: (function (msg) { return function () { return getMsgText(msg); }; })(n.msg),
      set: (function (msg) { return function (v) { if (typeof msg.content === 'string') msg.content = v; else msg.content = [{ type: 'text', text: v }]; }; })(n.msg)
    });
  }

  zones.sort(function (a, b) { return b.score - a.score; });
  return zones.slice(0, maxZones);
}

/* ===== 2_refract.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 2/4 Refraction
 * Vi nhiễu 3 luồng (W Khoảng trắng / L Từ nối diễn ngôn / A Anchor) + Cắt tỉa ngân sách + Bảo vệ chữ ký khối + Idempotence
 * ========================================================================== */

var PROFILE = {
  off:   { tokens: 0,  w: 0, l: 0, a: 0, zones: 0 },
  light: { tokens: 18, w: 3, l: 1, a: 1, zones: 1 },
  mid:   { tokens: 56, w: 6, l: 2, a: 2, zones: 2 }
};
var HARD_TOKEN_CAP = 120;

var ANCHOR_TOPICS = ['rules', 'context', 'section', 'layout', 'style', 'frame', 'notes', 'spec'];
var ANCHOR_KINDS = ['part', 'block', 'node', 'unit', 'seg', 'item'];

/* Từ nối diễn ngôn: Biến đổi mức độ 0, tuyệt đối không chạm vào từ tình thái/phủ định/nghĩa vụ */
var DISCOURSE = [
  [/(^|[，。；：！？\n\s])(Ngoài ra,|Hơn nữa,)/g, ['Ngoài ra,', 'Hơn nữa,']],
  [/(^|[，。；：！？\n\s])(Do đó,|Vì vậy,|Cho nên,)/g, ['Do đó,', 'Vì vậy,', 'Cho nên,']],
  [/(^|[，。；：！？\n\s])(Tóm lại,|Nói tóm lại,|Nói một cách ngắn gọn,)/g, ['Tóm lại,', 'Nói tóm lại,', 'Nói một cách ngắn gọn,']],
  [/(^|[，。；：！？\n\s])(Ví dụ,|Chẳng hạn,|Đơn cử như,)/g, ['Ví dụ,', 'Chẳng hạn,', 'Đơn cử như,']],
  [/(^|[，。；：！？\n\s])(Đồng thời,|Song song với đó,)/g, ['Đồng thời,', 'Song song với đó,']],
  [/(^|[，。；：！？\n\s])(Nói cách khác,|Hay nói một cách khác,)/g, ['Nói cách khác,', 'Hay nói một cách khác,']],
  [/(\b)(For example,)/g, ['For example,', 'For instance,']],
  [/(\b)(Therefore,)/g, ['Therefore,', 'Thus,', 'Hence,']],
  [/(\b)(However,)/g, ['However,', 'Nevertheless,']]
];

var ANCHOR_STRIP = /(?:^|\n)[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*(?=\n|$)/g;

var W_STRIP_LIST = /^([ \t]*(?:[-*+]|\d+\.|>))[ \t]{2,}/gm;
var W_STRIP_GAP = /\n[ \t]{1,3}\n/g;

function stripArtifacts(text) {
  if (typeof text !== 'string') return text;

  /* 1) Xóa cả dòng anchor (cùng với ngắt dòng nó mang lại), tránh để lại dòng trống ở đầu */
  var lines = text.split('\n');
  var kept = [];
  for (var i = 0; i < lines.length; i++) {
    if (/^[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*$/.test(lines[i])) continue;
    kept.push(lines[i]);
  }
  var out = kept.join('\n');

  /* 2) Phục hồi luồng khoảng trắng: Khoảng cách giữa các đoạn và space thừa sau ký hiệu danh sách quay về 1 */
  out = out.replace(W_STRIP_GAP, '\n\n').replace(W_STRIP_LIST, '$1 ');
  return out;
}

/* ---------------- Nguồn ngẫu nhiên (seeded LCG, có thể tái lập) ---------------- */

function makeRng(seed) {
  var s = (seed >>> 0) || 0x20261101;
  return function () {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

/* ---------------- Chữ ký cấp khối ---------------- */

function blockSignature(text) {
  var lines = String(text || '').split('\n');
  var h = [0, 0, 0, 0, 0, 0], li = 0, q = 0, tb = 0, fence = 0;
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i];
    if (!ln.trim()) continue;
    if (/^[ \t]*(?:<!--|\/\/\]:[ \t]*#)/.test(ln)) continue;
    var mh = /^[ \t]*(#{1,6})[ \t]+\S/.exec(ln);
    if (mh) { h[mh[1].length - 1]++; continue; }
    if (/^[ \t]*(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(ln)) { li++; continue; }
    if (/^[ \t]*>/.test(ln)) { q++; continue; }
    if (/^[ \t]*\|.*\|[ \t]*$/.test(ln)) { tb++; continue; }
    if (/^[ \t]*(?:`{3,}|~{3,})/.test(ln)) { fence++; continue; }
  }
  return h.join(',') + '|' + li + '|' + q + '|' + tb + '|' + fence;
}

/* ---------------- Luồng W: Khoảng trắng cấu trúc cấp khối ---------------- */

function findWSites(text, spans) {
  var sites = [];
  var patterns = [
    /^(#{1,6})([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}[-+*])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}\d{1,4}[.)])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}>)([ \t]{1,2})(?=\S)/gm
  ];
  for (var i = 0; i < patterns.length; i++) {
    var re = new RegExp(patterns[i].source, 'gm');
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 500) {
      var pos = m.index + m[1].length + m[2].length;
      if (isProtected(spans, m.index, pos)) continue;
      sites.push({ pos: pos, kind: 'inline' });
    }
  }
  var gapRe = /([^\n>`~|}])\n(\n)(?=\S)/g;
  var gm;
  var g2 = 0;
  while ((gm = gapRe.exec(text)) !== null && g2++ < 500) {
    var gp = gm.index + 1;
    if (isProtected(spans, gp - 1, gp + 2)) continue;
    sites.push({ pos: gp + 1, kind: 'gap' });
  }
  sites.sort(function (a, b) { return a.pos - b.pos; });
  return sites;
}

function planW(text, spans, max, rng) {
  if (max <= 0) return [];
  var sites = findWSites(text, spans);
  if (!sites.length) return [];
  var picked = [];
  var startIdx = Math.floor(rng() * sites.length);
  for (var step = 0; step < sites.length && picked.length < max; step++) {
    var s = sites[(startIdx + step) % sites.length];
    var clash = false;
    for (var k = 0; k < picked.length; k++) if (Math.abs(picked[k].pos - s.pos) < 36) { clash = true; break; }
    if (clash) continue;
    picked.push(s);
  }
  return picked.map(function (s) {
    return {
      track: 'W', start: s.pos, end: s.pos,
      text: s.kind === 'gap' ? ' ' : ' ',
      weight: 1
    };
  });
}

/* ---------------- Luồng L: Luân phiên từ nối diễn ngôn ---------------- */

function planL(text, spans, max, rng) {
  if (max <= 0) return [];
  var cands = [];
  for (var i = 0; i < DISCOURSE.length; i++) {
    var re = new RegExp(DISCOURSE[i][0].source, DISCOURSE[i][0].flags);
    var alts = DISCOURSE[i][1];
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 200) {
      var lead = m[1] || '';
      var word = m[2] || '';
      if (!word) continue;
      var start = m.index + lead.length;
      var end = start + word.length;
      if (isProtected(spans, start, end)) continue;
      var pool = [];
      for (var a = 0; a < alts.length; a++) if (alts[a] !== word) pool.push(alts[a]);
      if (!pool.length) continue;
      cands.push({ start: start, end: end, text: pool[Math.floor(rng() * pool.length)] });
    }
  }
  if (!cands.length) return [];
  var picked = [];
  var offset = Math.floor(rng() * cands.length);
  for (var s = 0; s < cands.length && picked.length < max; s++) {
    var c = cands[(offset + s) % cands.length];
    var clash2 = false;
    for (var p = 0; p < picked.length; p++) if (Math.abs(picked[p].start - c.start) < 60) { clash2 = true; break; }
    if (clash2) continue;
    picked.push(c);
  }
  return picked.map(function (c) {
    return { track: 'L', start: c.start, end: c.end, text: c.text, weight: 1 };
  });
}

/* ---------------- Luồng A: Anchor an toàn cấp khối ---------------- */

function buildAnchor(rng, html) {
  var topic = ANCHOR_TOPICS[Math.floor(rng() * ANCHOR_TOPICS.length)];
  var kind = ANCHOR_KINDS[Math.floor(rng() * ANCHOR_KINDS.length)];
  var hex = Math.floor(rng() * 0xffff).toString(16);
  while (hex.length < 4) hex = '0' + hex;
  var tag = rng() < 0.5 ? 'ctx' : 'ref';
  return html ? '<!-- ' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ' -->'
              : '[//]: # (' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ')';
}

function isBlockLine(line) {
  var s = String(line || '');
  return /^[ \t]{0,3}(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(s) ||
         /^[ \t]{0,3}>/.test(s) ||
         /^[ \t]{0,3}\|.*\|[ \t]*$/.test(s) ||
         /^[ \t]{2,}\S/.test(s);
}

function findAnchorSites(text, spans) {
  var out = [];
  var idx = -1;
  var guard = 0;
  while ((idx = text.indexOf('\n', idx + 1)) !== -1 && guard++ < 4000) {
    if (isProtected(spans, idx, idx + 1)) continue;
    var lineStart = text.lastIndexOf('\n', idx - 1) + 1;
    var prevLine = text.slice(lineStart, idx);
    var nextNl = text.indexOf('\n', idx + 1);
    var nextLine = text.slice(idx + 1, nextNl === -1 ? text.length : nextNl);
    var prevTrim = prevLine.replace(/\s+$/, '');
    if (/[:：<{`\\]$/.test(prevTrim)) continue;
    if (isBlockLine(prevLine) && (isBlockLine(nextLine) || !nextLine.trim())) continue;
    var prevHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(prevLine);
    var nextHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(nextLine);
    var blankBoundary = !prevTrim && !isBlockLine(nextLine);
    if (prevHeading || nextHeading || blankBoundary) out.push(idx);
  }
  return out;
}

function planA(text, spans, isHead, max, rng) {
  if (max <= 0) return [];
  var sites = findAnchorSites(text, spans);
  var html = rng() < 0.5;
  var acts = [];
  if (isHead && !isProtected(spans, 0, 1)) {
    var a0 = buildAnchor(rng, html) + '\n';
    acts.push({ track: 'A', start: 0, end: 0, text: a0, weight: estimateTokens(a0) });
    return acts;
  }
  if (!sites.length) return acts;
  var pool = [];
  for (var i = 0; i < sites.length; i++) {
    if (sites[i] >= 4 && sites[i] <= 320) pool.push(sites[i]);
  }
  var target = pool.length ? pool[Math.floor(rng() * pool.length)] : sites[0];
  var ins = '\n' + buildAnchor(rng, !html);
  acts.push({ track: 'A', start: target, end: target, text: ins, weight: estimateTokens(ins) });
  return acts;
}

/* ---------------- Áp dụng (Bao gồm cắt tỉa ngân sách và bảo vệ chữ ký) ---------------- */

function refractZone(text, opt, rng) {
  var empty = { changed: false, text: text, added: 0, edits: 0, tracks: { W: 0, L: 0, A: 0 } };
  var cleaned = stripArtifacts(text);
  if (typeof cleaned !== 'string' || cleaned.replace(/\s/g, '').length < 40) return empty;

  var spans = collectSpans(cleaned);
  if (spans.length === 1 && spans[0][0] === 0 && spans[0][1] >= cleaned.length) return empty;

  var acts = [];
  if (opt.w > 0) acts = acts.concat(planW(cleaned, spans, opt.w, rng));
  if (opt.l > 0) acts = acts.concat(planL(cleaned, spans, opt.l, rng));
  if (opt.a > 0) acts = acts.concat(planA(cleaned, spans, opt.isHead, opt.a, rng));
  if (!acts.length) return empty;

  var total = 0;
  for (var i = 0; i < acts.length; i++) total += acts[i].weight;
  while (total > opt.budget && acts.length) {
    var dropA = -1, dropL = -1;
    for (var j = 0; j < acts.length; j++) {
      if (acts[j].track === 'A' && dropA < 0) dropA = j;
      if (acts[j].track === 'L' && dropL < 0) dropL = j;
    }
    var di = dropA >= 0 ? dropA : (dropL >= 0 ? dropL : acts.length - 1);
    total -= acts[di].weight;
    acts.splice(di, 1);
  }
  if (!acts.length) return empty;

  acts.sort(function (x, y) { return y.start - x.start || y.end - x.end; });
  var out = cleaned;
  var lastStart = 1e9;
  var applied = 0;
  var tracks = { W: 0, L: 0, A: 0 };
  for (var k = 0; k < acts.length; k++) {
    var act = acts[k];
    if (act.end > lastStart) continue;
    if (act.start > 0 && isProtected(spans, act.start, act.end)) continue;
    out = out.slice(0, act.start) + act.text + out.slice(act.end);
    lastStart = act.start;
    applied++;
    tracks[act.track]++;
  }
  if (!applied || out === cleaned) return empty;

  if (blockSignature(cleaned) !== blockSignature(out)) return empty;

  return { changed: true, text: out, added: Math.max(1, Math.ceil(total)), edits: applied, tracks: tracks };
}

/* ---------------- Viết lại request ---------------- */

function textOfMsg(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') return m.content[i].text || '';
    }
  }
  return '';
}

function setMsgText(m, v) {
  if (typeof m.content === 'string') { m.content = v; return; }
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') { m.content[i].text = v; return; }
    }
  }
}

function deriveBase(url, body) {
  try {
    if (body && typeof body.reverse_proxy === 'string' && body.reverse_proxy) return body.reverse_proxy.replace(/\/+$/, '');
    var u = new URL(url, HOST.location ? HOST.location.href : 'http://localhost');
    var path = u.pathname;
    var cut = path.indexOf('/api/backends/chat-completions');
    if (cut >= 0) return u.origin;
    return u.origin;
  } catch (e) { return cfg.dualBase || ''; }
}

function planRequest(rawBody, url, internal) {
  var out = { changed: [], model: '', base: '', body: rawBody };
  var edits = 0, added = 0;
  if (!rawBody) return out;
  var body;
  try { body = JSON.parse(rawBody); } catch (e) { return out; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return out;

  out.model = String(body.model || body.model_name || '');
  out.base = deriveBase(url, body);
  out.internal = !!internal;

  /* Request nội bộ (database/điền biểu mẫu/tạo ngầm): body là giao thức cấu trúc, cả alias lẫn vi nhiễu đều có thể làm hỏng bảng */
  if (internal) {
    if (cfg.pin) {
      if (Array.isArray(body.models) && body.models.length) { delete body.models; out.changed.push('Xóa models[]'); }
      if (Object.prototype.hasOwnProperty.call(body, 'allow_fallbacks') && body.allow_fallbacks !== false) {
        body.allow_fallbacks = false; out.changed.push('allow_fallbacks=false');
      }
    }
    if (out.changed.length) out.body = JSON.stringify(body);
    out.edits = 0; out.added = 0;
    return out;
  }

  /* L3 Khóa cứng alias: Khi không rỗng, sửa model thành giá trị này */
  if (cfg.alias) {
    var wantModel = String(cfg.alias);
    if (body.model && String(body.model) !== wantModel) {
      body.model = wantModel;
      out.changed.push('Alias→' + wantModel);
      out.model = wantModel;
    }
  }

  if (cfg.pin) {
    if (Array.isArray(body.models) && body.models.length) { delete body.models; out.changed.push('Xóa models[]'); }
    if (Object.prototype.hasOwnProperty.call(body, 'allow_fallbacks') && body.allow_fallbacks !== false) {
      body.allow_fallbacks = false; out.changed.push('allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_allow_fallbacks') && body.openrouter_allow_fallbacks !== false) {
      body.openrouter_allow_fallbacks = false; out.changed.push('openrouter_allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_use_fallback') && body.openrouter_use_fallback !== false) {
      body.openrouter_use_fallback = false; out.changed.push('openrouter_use_fallback=false');
    }
    if (body.provider && typeof body.provider === 'object' && !Array.isArray(body.provider) &&
        Object.prototype.hasOwnProperty.call(body.provider, 'allow_fallbacks') && body.provider.allow_fallbacks !== false) {
      body.provider.allow_fallbacks = false; out.changed.push('provider.allow_fallbacks=false');
    }
    if (body.route !== undefined && body.route !== null) { delete body.route; out.changed.push('Xóa route'); }
  }

  if (cfg.think === 'high') {
    var hasThink = body.thinking !== undefined || body.thinkingConfig !== undefined || body.reasoning_effort !== undefined;
    if (!hasThink) { body.reasoning_effort = 'high'; out.changed.push('reasoning_effort=high'); }
  }

  if (cfg.refract !== 'off') {
    var prof = PROFILE[cfg.refract] || PROFILE.off;
    var inner = body;
    if (body.request && typeof body.request === 'object' && !Array.isArray(body.request)) inner = body.request;
    var zones = pickZones(inner, '', prof.zones);
    var seedStr = String(out.base || '') + '|' + normModel(out.model) + '|' + saltKey('refract') + '|' + String(cfg.refractSeed || '');
    var seedNum = (cfg.refractMode === 'random') ? (Date.now() ^ 0x5f3759df) : hashStr(seedStr);
    var rng = makeRng(seedNum >>> 0);
    var touched = 0, tk = { W: 0, L: 0, A: 0 };
    var budget = Math.min(prof.tokens, HARD_TOKEN_CAP);
    for (var i = 0; i < zones.length; i++) {
      if (budget <= 0) break;
      var before = zones[i].get();
      var res = refractZone(before, {
        w: prof.w, l: prof.l, a: prof.a, isHead: i === 0, budget: budget
      }, rng);
      if (!res.changed) continue;
      zones[i].set(res.text);
      touched++;
      added += res.added;
      edits += res.edits;
      budget -= res.added;
      tk.W += res.tracks.W; tk.L += res.tracks.L; tk.A += res.tracks.A;
    }
    if (touched > 0) {
      out.changed.push('Vi nhiễu ' + touched + ' vùng/W' + tk.W + '·L' + tk.L + '·A' + tk.A + '/+' + added + 'tok');
    }
  }

  /* v8.31 Tầng tự sự: Chống toàn tri / Xóa nịnh nọt.
     Đặt sau vi nhiễu (nếu không cách diễn đạt mỗi lượt sẽ bị khoảng trắng và từ nối làm xáo trộn, cùng một nội dung lại thành hai cách nói),
     trước phá giáp (đuôi "viết trực tiếp" của phá giáp bắt buộc phải ép ở cuối cùng, đó là vị trí hiệu lực mạnh nhất).
     Lưu ý: Ở đây chỉ sửa bản sao JSON.parse ra, lịch sử chat không suy suyển một byte nào.
     Khi tắt cũng vẫn gọi một lần: Nhiệm vụ khác của nó là "bóc sạch các block còn sót lại của lượt trước",
     nếu dựa vào công tắc để skip thì khi gặp request mang block thừa sẽ vĩnh viễn không bóc được. Toàn bộ lệnh gọi chỉ tốn hai lần indexOf, có thể bỏ qua. */
  try {
    var nch = narrApply(body);
    for (var nz = 0; nz < nch.length; nz++) out.changed.push(nch[nz]);
  } catch (eNarr) {}

  /* v7.1 Phá giáp (Mức mạnh): Đặt sau vi nhiễu, trước khi serialize — nếu đặt phía trước sẽ bị vi nhiễu xáo trộn lại một lượt */
  if (cfg.enabled && cfg.jail === 'strong') {
    try {
      var jch = jailPatchBody(body);
      for (var jz = 0; jz < jch.length; jz++) out.changed.push(jch[jz]);
    } catch (eJail) {}
  }

  /* v7.4: Rốt cuộc đã khóa được bao nhiêu + có shield ngoại lai nào cùng inject vào một request không */
  try { out.audit = lockAudit(body); } catch (eA) {}
  try { out.foreign = foreignShield(body); } catch (eF) {}

  /* Then chốt: Chỉ cần đụng tới body là bắt buộc phải serialize ngược lại; nếu không việc khóa tham số chỉ sửa đổi object trên bộ nhớ */
  if (out.changed.length) out.body = JSON.stringify(body);

  out.edits = edits;
  out.added = added;
  return out;
}

/* ===== 12_narr.js ===== */
/* 12_narr.js — v8.31 Tầng tự sự: Chống toàn tri / Xóa nịnh nọt, mỗi loại ba mức
 *
 * Tại sao không dùng regex của SillyTavern nữa:
 *   Dấu `.` trong regex gốc `^(.+)$` không match qua dòng, `$` của JS cũng không nhận dấu xuống dòng ở cuối —— user chỉ cần nhập nhiều dòng là âm thầm mất tác dụng;
 *   Bật cả hai cái cùng lúc sẽ nuốt chửng output của nhau (một cái output 13 dòng, cái kia ^(.+)$ không khớp nổi dòng nào).
 *   Ở đây chuyển sang sửa trực tiếp request body: Nhiều dòng, lồng nhau, idempotence, de-duplicate toàn bộ do code bảo đảm, có lỗi cũng không bị âm thầm thất bại.
 *
 * Vị trí inject: Trong planRequest "sau vi nhiễu, trước phá giáp".
 *   - Sau vi nhiễu: Văn bản tự sự không thể bị khoảng trắng/từ nối làm xáo trộn, nếu không mỗi lượt diễn đạt một kiểu;
 *   - Trước phá giáp: Đuôi "viết trực tiếp" của phá giáp phải ép ở cuối cùng, đó là vị trí hiệu lực mạnh nhất.
 *
 * Ba điều bất biến:
 *   1) Chỉ sửa bản sao trong request body, lịch sử chat không đụng tới một chữ (cho nên gửi lại/refresh sẽ không bị tích tụ);
 *   2) Idempotence: Trước khi inject sẽ bóc khối của lần trước ra, inject N lần hay inject 1 lần đều ra kết quả y hệt;
 *   3) Fail-safe: Bất kỳ bước nào throw error đều trả về nguyên dạng, tuyệt đối không để tầng tự sự làm hỏng request.
 */

var NARR_TAG = 'AR-NAR';
var NARR_VER = '8.31';
var NARR_OPEN = '〔AR-NAR ' + NARR_VER + '〕';
var NARR_CLOSE = '〔/AR-NAR〕';
var NARR_TIERS = ['off', 'lite', 'full'];

/* ---------------- Nội dung prompt ----------------
   Mức nhẹ là "một câu nhắc nhở", mức mạnh là "quy tắc thực thi được + tự kiểm duyệt khi hạ bút".
   Toàn bộ do tôi viết lại, không phải copy từ regex cũ:
   - Điều 6 của Xóa nịnh nọt cũ "cách qua màn duy nhất là user tử vong" đã bị xóa bỏ. Câu đó sẽ dẫn dụ model viết ra kết cục từ chối/tử vong,
     mà câu từ chối trong 7_jail sẽ bị phán đoán thành "phản hồi rỗng" → kích hoạt tự động viết tiếp → user sẽ thấy script tự gửi request tới model.
     Đã đổi thành "không có kết cục tất thắng", giữ lại cốt lõi "thế giới không chiều chuộng bạn", loại bỏ lối thoát khiến hệ thống rơi vào bẫy.
   - Phần tự kiểm duyệt của Chống toàn tri cũ là hỏi từng câu, ở đây nén lại thành một câu: Tự kiểm duyệt từng câu trong phản hồi dài sẽ bị model bỏ qua thẳng thừng.
   - Thiết luật và hành động của user chia làm hai khối, không lồng vào nhau (trước đây nhét $1 vào trong 【Hành động】, nhập nhiều dòng là vỡ vụn).
*/
var NARR_KNOW = {
  lite: '[Góc nhìn bị hạn chế] Chỉ viết những gì mắt thấy tai nghe trong phân cảnh này. Mọi nhân vật đều không biết nội tâm, dự định chưa nói ra của <user>, cũng không biết diễn biến cốt truyện bên ngoài nơi này.',
  full: [
    '[Thiết luật lượt này | Ưu tiên cao hơn character card, world info và văn phong trước đây]',
    '1. Chỉ viết những gì ống kính máy quay ghi lại được, micro thu âm được: Động tác, đối thoại, biểu cảm, môi trường.',
    '2. Mọi nhân vật đều không biết nội tâm của <user>, dự định chưa nói ra, tình tiết cốt truyện chưa xảy ra, tình hình ngoài nơi này; tuyệt đối không xuất hiện các meta-info như "người chơi/user/AI/thiết lập/prompt".',
    '3. Không viết hộ nội tâm và quyết định của <user>.',
    '4. Từng câu thoại, từng phán đoán đều phải truy nguyên được từ sự việc đã diễn ra.',
    '5. Cấm các mẫu câu: Hắn sớm đã biết / Dường như nhìn thấu tâm tư / Trong cõi u minh / Cùng lúc đó, tại một nơi khác.',
    '6. Khi cần một ai đó biết chuyện, hãy viết ra hành động hoặc manh mối cho thấy hắn "làm sao biết được" trước.',
    '7. Trong chính văn không xuất hiện OOC, giải thích hệ thống, lời thoại ngoài lề trong ngoặc đơn, cũng không nhắc lại quy tắc này.',
    '[Tự kiểm duyệt khi hạ bút, không xuất ra] Thông tin trong câu này, người nói làm sao biết được? Không tìm ra nguồn gốc thì viết lại. Thà để hắn phán đoán sai, còn hơn để hắn biết trước tương lai.'
  ].join('\n')
};

var NARR_CHARM = {
  lite: '[Thế giới không xoay quanh bạn] NPC có cuộc sống và kế hoạch riêng, sự chú ý sẽ không tự động hướng về <user>.',
  full: [
    '[Tone giọng chủ đạo lượt này]',
    '1. Đây là một thế giới tự vận hành. NPC có quỹ đạo, mối quan hệ và lịch trình riêng trong ngày, không xoay quanh <user>.',
    '2. <user> chỉ là một người trong câu chuyện này, không phải người chơi ngồi trên khán đài.',
    '3. Hành động của <user> có thể bị NPC ngắt lời, phớt lờ, hiểu lầm hoặc từ chối, không có hào quang nhân vật chính.',
    '4. Đừng coi <user> như camera hay công cụ tự sự: Khi hắn vắng mặt, thế giới vẫn diễn ra bình thường.',
    '5. Không có kết cục tất thắng. Đi sai đường, bị từ chối, bị thương, thất bại đều được phép xảy ra.'
  ].join('\n')
};

/* ---------------- Trạng thái ---------------- */

function narrPick(v) {
  var s = String(v == null ? '' : v);
  for (var i = 0; i < NARR_TIERS.length; i++) if (NARR_TIERS[i] === s) return s;
  return 'off';
}
function narrTag(v) {
  var s = narrPick(v);
  return s === 'off' ? 'Tắt' : (s === 'lite' ? 'Nhẹ' : 'Mạnh');
}
function narrNext(v) {
  var s = narrPick(v);
  return s === 'off' ? 'lite' : (s === 'lite' ? 'full' : 'off');
}

/* Tên: Nếu lấy được name1 của ST thì đổi thành tên thật, không lấy được thì fallback về "bạn".
   Lưu ý đừng để sót ngoặc nhọn trong prompt — một số route sẽ coi <user> là tag lạ rồi nuốt mất. */
function narrUserName() {
  try {
    var c = stCtx();
    if (!c) return '';
    var n = String(c.name1 == null ? '' : c.name1).trim();
    n = n.replace(/[〔〕【】\[\]<>]/g, '').slice(0, 24).trim();
    return n;
  } catch (e) { return ''; }
}

function narrFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('<user>') < 0) return s;
  var n = narrUserName() || 'bạn';
  return s.split('<user>').join(n);
}

/* Ghép toàn bộ block cần inject cho lượt này; khi cả hai đều tắt thì trả về chuỗi rỗng */
function narrBody() {
  var parts = [];
  var charm = NARR_CHARM[narrPick(cfg && cfg.charm)] || '';
  var know = NARR_KNOW[narrPick(cfg && cfg.know)] || '';
  if (charm) parts.push(narrFill(charm));
  if (know) parts.push(narrFill(know));      /* Chống toàn tri ở lớp trong: Gần vị trí sinh text nhất */
  if (!parts.length) return '';
  return NARR_OPEN + '\n' + parts.join('\n') + '\n' + NARR_CLOSE;
}

function narrLabel() {
  var a = (cfg && cfg.know !== 'off') ? ('Chống toàn tri' + narrTag(cfg.know)) : '';
  var b = (cfg && cfg.charm !== 'off') ? ('Xóa nịnh nọt' + narrTag(cfg.charm)) : '';
  if (a && b) return a + '+' + b;
  return a || b || 'Tắt';
}

/* Ước tính sơ bộ token: Tiếng Trung khoảng 0.7 tok/chữ, chỉ dùng để hiện độ lớn trên panel, không dùng làm căn cứ tính phí */
function narrTokens() {
  var b = narrBody();
  if (!b) return 0;
  return Math.round(b.length * 0.7);
}

/* Bóc khối đã inject lần trước ra. Không tìm thấy marker thì trả về nguyên dạng —— tuyệt đối không "đoán mò để xóa". */
function narrStripOnce(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf('〔' + NARR_TAG);
  if (i < 0) return t;
  var j = t.indexOf(NARR_CLOSE, i);
  if (j < 0) return t;
  j += NARR_CLOSE.length;
  var head = t.slice(0, i);
  var tail = t.slice(j);
  /* Ăn luôn khoảng trắng ở hai đầu, nếu không mỗi lần tái inject sẽ thừa ra một dòng trống, càng cuộn càng dài */
  head = head.replace(/[ \t]+$/, '');
  tail = tail.replace(/^[ \t\r\n]+/, '');
  if (!tail) return head.replace(/[\s]+$/, '');
  return head + (head ? '\n\n' : '') + tail;
}

/* Dữ liệu lịch sử cũ có thể sót lại hai khối (bản cũ đã inject + bản này lại inject), bóc một khối một lần là chưa đủ.
   Giới hạn 8 lần chỉ để phòng ngừa vòng lặp vô tận, bình thường một lượt là xong. */
function narrStrip(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < 8; k++) {
    var n = narrStripOnce(t);
    if (n === t) break;
    t = n;
  }
  return t;
}

/* Quá trình inject thực sự: Chỉ sửa bản sao body truyền vào */
function narrApply(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  /* Tìm ngược từ cuối lên tin nhắn user đầu tiên: Trong lượt /continue của phá giáp, tin nhắn cuối cùng là placeholder của assistant */
  var idx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var m = msgs[i];
    if (m && String(m.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = String(textOfMsg(m2) || '');
  var base = narrStrip(old);
  var block = narrBody();

  if (!block) {
    if (base !== old) { setMsgText(m2, base); out.push('Tự sự: Xóa sạch'); }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    setMsgText(m2, next);
    out.push('Tự sự: ' + narrLabel());
  }
  return out;
}

/* ===== 5_route.js ===== */
/* ============================================================================
 * Anti-Route v7 — 5/6 Route
 * Cổng kiểm tra tính xác thực kênh / Khóa cứng alias / Báo cáo tinh gọn / KPI tỷ lệ route / Kiểm tra tính quan sát của tier
 * Nguyên tắc: Toàn bộ là "đầu dò nhánh phụ + hiển thị", không thêm bất kỳ tính toán nào vào đường dẫn sinh text
 * ========================================================================== */

var CH_KEY = 'ar7.ch';
var ALIAS_CACHE = null;

/* ---------------- Trạng thái kênh ---------------- */

function chKeyOf(base, key) {
  return String(hashStr(String(base || '').replace(/\/+$/, '') + '|' + String(key || '')));
}

/* Base URL kênh hiện tại: Ưu tiên giá trị điền trong panel, kế đến dùng base thực tế gửi đi ở lượt request trước */
function curBase() {
  var b = String(cfg.dualBase || '').replace(/\/+$/, '');
  if (b) return b;
  try { if (lastReq && lastReq.base) return String(lastReq.base).replace(/\/+$/, ''); } catch (e) {}
  return '';
}

function readChAll() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(CH_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeChAll(o) {
  try { HOST.localStorage.setItem(CH_KEY, JSON.stringify(o)); } catch (e) {}
}

function chState() {
  var b = curBase();
  if (!b) return { echoes: null, at: 0, base: '' };
  var all = readChAll();
  var st = all[chKeyOf(b, cfg.dualKey || '')];
  if (!st || typeof st !== 'object') return { echoes: null, at: 0, base: b };
  st.base = b;
  return st;
}

function setChState(st) {
  var b = curBase();
  if (!b) return false;
  var all = readChAll();
  var next = { echoes: st.echoes, at: nowMs(), base: b, note: st.note || '' };
  all[chKeyOf(b, cfg.dualKey || '')] = next;
  writeChAll(all);
  return true;
}

/* Nhãn tính xác thực: true = echo không thể xác thực / false = có thể xác thực / null = chưa xác thực */
function verifiableLabel() {
  var st = chState();
  if (st.echoes === true) return 'Không thể xác thực';
  if (st.echoes === false) return 'Có thể xác thực';
  return 'Chưa xác thực';
}

function verifiableCode() {
  var st = chState();
  if (st.echoes === true) return 'no';
  if (st.echoes === false) return 'yes';
  return 'unknown';
}

/* ---------------- Đầu dò tối thiểu ---------------- */

function probeFetchFn() {
  try { if (typeof probeFetch === 'function' && probeFetch) return probeFetch; } catch (e) {}
  try { return HOST.fetch; } catch (e) { return null; }
}

function probeOnce(url, bodyObj, ms) {
  return new Promise(function (resolve) {
    var done = false;
    var timer = setTimeout(function () {
      if (done) return;
      done = true;
      resolve({ status: 0, model: '', err: 'timeout' });
    }, ms || 20000);
    var f = probeFetchFn();
    if (!f) { clearTimeout(timer); resolve({ status: 0, model: '', err: 'no-fetch' }); return; }
    var init = {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bodyObj)
    };
    try {
      if (cfg.dualKey) init.headers.Authorization = 'Bearer ' + cfg.dualKey;
    } catch (e) {}
    var p;
    try {
      p = f.call(HOST, url, init);
    } catch (e) {
      clearTimeout(timer); resolve({ status: 0, model: '', err: 'throw' }); return;
    }
    p.then(function (res) {
      var out = { status: res.status, model: '', err: '', ctx: '' };
      return res.text().then(function (t) {
        out.raw = String(t || '').slice(0, 4000);
        try {
          var j = JSON.parse(t);
          out.model = String(j.model || (j.candidates && j.candidates[0] && j.candidates[0].modelVersion) || '');
          if (j.error && j.error.message) out.err = String(j.error.message).slice(0, 120);
        } catch (e) {
          var m = /"(?:model|modelVersion)"\s*:\s*"([^"]{1,120})"/.exec(t || '');
          if (m) out.model = m[1];
          if (/131072|token count exceeds/i.test(t || '')) out.ctx = '131072';
        }
        return out;
      }).catch(function () { return out; });
    }).then(function (out2) {
