/* ---------------- v7.4 Audit khóa / Shield ngoại lai ---------------- */

var LOCK_FIELDS = ['allow_fallbacks', 'openrouter_allow_fallbacks', 'openrouter_use_fallback', 'provider.allow_fallbacks'];
var LAST_AUDIT = null;
var LAST_FOREIGN = 0;

function readLockField(body, path) {
  if (!body || typeof body !== 'object') return undefined;
  if (path.indexOf('.') < 0) return Object.prototype.hasOwnProperty.call(body, path) ? body[path] : undefined;
  var parts = path.split('.');
  var cur = body;
  for (var i = 0; i < parts.length; i++) {
    if (!cur || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, parts[i])) return undefined;
    cur = cur[parts[i]];
  }
  return cur;
}

function lockAudit(body) {
  var rows = [], pinned = 0, present = 0;
  for (var i = 0; i < LOCK_FIELDS.length; i++) {
    var v = readLockField(body, LOCK_FIELDS[i]);
    var has = v !== undefined;
    var ok = has && v === false;
    if (has) present++;
    if (ok) pinned++;
    rows.push({ name: LOCK_FIELDS[i], present: has, locked: ok });
  }
  LAST_AUDIT = { total: LOCK_FIELDS.length, present: present, pinned: pinned, rows: rows };
  return LAST_AUDIT;
}

function auditLabel() {
  return LAST_AUDIT ? (LAST_AUDIT.pinned + '/' + LAST_AUDIT.total) : '—';
}

function auditColor() {
  if (!LAST_AUDIT) return 'gray';
  if (LAST_AUDIT.pinned === LAST_AUDIT.total) return 'ok';
  if (LAST_AUDIT.pinned > 0) return 'warn';
  return 'gray';
}

function foreignShield(body) {
  var msgs = body && Array.isArray(body.messages) ? body.messages : null;
  if (!msgs || !msgs.length) { LAST_FOREIGN = 0; return 0; }
  var hits = 0;
  var n = Math.min(12, msgs.length);
  for (var i = 0; i < n; i++) {
    var m = msgs[i];
    if (!m) continue;
    var t = typeof m.content === 'string' ? m.content : '';
    if (!t) continue;
    var c1 = (t.match(/<!--/g) || []).length;
    if (c1 >= 2) hits++;
    var c2 = (t.match(/^\[[a-zA-Z0-9_]{4,}\]:\s*#/gm) || []).length;
    if (c2 >= 2) hits++;
    var c3 = (t.match(/[\u200b\u200c\u200d\ufeff]{3,}/g) || []).length;
    if (c3 >= 2) hits++;
    if (/\[(?:IZUMI_ANTI_ROUTE|ANTI_ROUTE|GEMINI_ANTI_ROUTE)\]/i.test(t)) hits++;
  }
  LAST_FOREIGN = hits;
  return hits;
}

function foreignCount() { return LAST_FOREIGN; }

/* ===== 13_stats.js ===== */
/* ============================================================================
 * Anti-Route v7 — 13/Stats Sổ cái kênh / Card fingerprint / Xuất log / Đối chiếu A-B
 * Nguyên tắc: Chỉ thực hiện "đo lường và hiển thị". Không đụng tới request generate, không clone 200, không quyết định thay cho người dùng.
 *   - Sổ cái: Tích lũy các lượt đã có kết luận theo từng kênh (không bị giới hạn 40 dòng của log), đưa ra khoảng tin cậy Wilson
 *   - Card fingerprint: Gom phần "kênh này có thể xác thực hay không" thành một đoạn văn, kênh trả về echo sẽ tự động hạ trọng số
 *   - Export: Một đoạn văn bản có thể paste <= 1800 từ + một dòng payload base64 cho máy đọc
 *   - A/B: Request trần vs Cấu hình hiện tại, mỗi bên 2 lần, chỉ báo cáo xu hướng chứ không kết luận tuyệt đối
 * ========================================================================== */

var LED_KEY = 'ar7.led';
var AB_STATE = { running: false, last: null };

function statBase() {
  try { return String(curBase() || '').replace(/\/+$/, ''); } catch (e) { return ''; }
}

/* Gom sổ cái theo base: Cùng một reverse proxy đổi key thì không nên tách rời */
function statKey() {
  var b = statBase();
  return b ? String(hashStr(b)).slice(0, 10) : 'local';
}

function readLed() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(LED_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeLed(o) {
  try { HOST.localStorage.setItem(LED_KEY, JSON.stringify(o)); } catch (e) {}
}

function ledEmpty() {
  return { n: 0, same: 0, diff: 0, thin: 0, echo: 0, blocked: 0, weak: 0, at: 0 };
}

function ledRow() {
  var all = readLed();
  var r = all[statKey()];
  if (!r || typeof r !== 'object') return ledEmpty();
  var o = ledEmpty();
  var keys = ['n', 'same', 'diff', 'thin', 'echo', 'blocked', 'weak', 'at'];
  for (var i = 0; i < keys.length; i++) {
    var v = Number(r[keys[i]]);
    o[keys[i]] = isFinite(v) ? v : 0;
  }
  return o;
}

/* Chỉ nhận các lượt "có kết luận": Request nội bộ, hạng C, unknown/empty/error đều không tính vào mẫu số.
   Đây chính là lý do tỷ lệ route luôn bị ước tính quá cao —— mẫu số bị lẫn những lượt không hợp lệ. */
function ledAdd(rec) {
  try {
    if (!rec || rec.internal) return;
    var conf = rec.conf || 'C';
    var c = rec.code;
    if (c !== 'same' && c !== 'diff' && c !== 'thin' && c !== 'echo' && c !== 'blocked') return;
    var all = readLed();
    var k = statKey();
    var r = all[k];
    if (!r || typeof r !== 'object') r = ledEmpty();
    r.at = nowMs();
    if (conf === 'A' || conf === 'B') {
      r.n = Number(r.n || 0) + 1;
      r[c] = Number(r[c] || 0) + 1;
    } else {
      /* Hạng C cũng ghi nhận, nhưng chỉ ghi vào ô "bằng chứng yếu": Tính gộp vào tỷ lệ bị tráo sẽ biến phỏng đoán thành sự thật */
      r.weak = Number(r.weak || 0) + 1;
    }
    all[k] = r;
    writeLed(all);
  } catch (e) {}
}

/* Tỷ lệ bị tráo = ba loại không nên xuất hiện (bị tráo / mất suy nghĩ / echo) chiếm trên tổng số lượt có kết luận */
function ledStat() {
  var r = ledRow();
  var bad = r.diff + r.thin + r.echo;
  var w = wilson(bad, r.n);
  return {
    n: r.n, bad: bad,
    pct: r.n ? Math.round(w.p * 1000) / 10 : 0,
    lo: Math.round(w.lo * 1000) / 10,
    hi: Math.round(w.hi * 1000) / 10,
    enough: r.n >= 5,
    row: r
  };
}

function ledLine() {
  var s = ledStat();
  if (!s.n) return 'Sổ cái kênh: Chưa có lượt nào có kết luận (hãy chat trước hai lượt)';
  var ci = s.enough ? (' (Khoảng 95% ' + s.lo + '–' + s.hi + '%)') : ' (Mẫu chưa đủ, tạm thời đừng coi là kết luận)';
  var weak = Number(s.row && s.row.weak || 0);
  return 'Sổ cái kênh n=' + s.n + ' · Bị tráo ' + s.pct + '%' + ci +
    (weak ? ', ngoài ra có ' + weak + ' lượt bằng chứng quá yếu nên không tính vào' : '');
}

/* ---------------- Card fingerprint kênh (Không lưu trữ mới, chỉ gom các quan sát sẵn có thành một câu) ---------------- */

function fpCard() {
  var b = statBase() || ' (Kênh chưa rõ)';
  var st = { echoes: null };
  try { st = chState() || st; } catch (e) {}
  var ver = (st.echoes === true) ? 'Echo (Tên không khớp không thể làm bằng chứng)'
