  var ali = 0;
  try { ali = (ALIAS_CACHE && ALIAS_CACHE.length) || 0; } catch (e2) { ali = 0; }
  var s = ledStat();
  var lines = [
    '🏷 Kênh ' + String(b).replace(/^https?:\/\//, '').slice(0, 42),
    'Tính xác thực: ' + ver,
    'Alias: ' + (ali ? ali + ' cái khả dụng' : 'Chưa quét (Nhấn "🏷 Quét alias")'),
    'Sổ cái: ' + (s.n ? ('n=' + s.n + ', bị tráo ' + s.pct + '%' + (s.enough ? '' : ' (Mẫu chưa đủ)')) : 'Rỗng'),
    'Kết luận: ' + (st.echoes === true
      ? 'Kênh này sẽ echo lại tên model của bạn, việc "bị tráo" khác họ đều sẽ bị hạ cấp thành "không thể phán đoán".'
      : (st.echoes === false ? 'Tên có thể dùng làm bằng chứng hạng B; chỉ khi khác họ và tự khai trong response body mới là hạng A.' : 'Kênh chưa xác thực chỉ có bằng chứng hạng C, đừng dựa vào đó để đưa ra kết luận.'))
  ];
  return lines.join('\n');
}

/* ---------------- Xuất bản ghi ---------------- */

function b64(s) {
  try {
    if (HOST.btoa) return HOST.btoa(unescape(encodeURIComponent(String(s))));
  } catch (e) {}
  return '';
}

function redact(s) {
  return String(s == null ? '' : s)
    .replace(/sk-[A-Za-z0-9_\-]{6,}/g, 'sk-***')
    .replace(/([?&](?:key|token|api_key)=)[^&\s]+/gi, '$1***');
}

function hhmm(ms) {
  try {
    var d = new Date(ms);
    return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  } catch (e) { return '--:--'; }
}

/* Lấy từ mới đến cũ, cho đến giới hạn 1800 chữ; thà bớt vài lượt chứ không xuất một đoạn văn bản bị cắt cụt nham nhở */
function exportText() {
  var log = readLog() || [];
  var s = ledStat();
  var head = [
    'Ánh Sáng Luke V' + VERSION + ' · Xuất nhật ký',
    'Kênh: ' + (statBase() || ' (Chưa rõ)'),
    'Sổ cái: n=' + s.n + ', bị tráo ' + s.pct + '% (' + s.lo + '–' + s.hi + '%)' + (s.enough ? '' : ' Mẫu chưa đủ'),
    '---'
  ];
  var body = [];
  var used = head.join('\n').length;
  var picked = [];
  for (var i = log.length - 1; i >= 0; i--) {
    var r = log[i];
    if (!r) continue;
    var line = hhmm(r.at) + ' ' + (r.req || '—') + ' → ' + (r.obs || '—') +
      ' [' + (r.verdict || '?') + '/' + (r.conf || 'C') + ']' +
      (r.status ? ' HTTP' + r.status : '') +
      (r.chars ? ' ' + r.chars + ' chữ' : '') +
      (r.internal ? ' (Nội bộ)' : '') +
      (r.note ? ' — ' + redact(r.note) : '');
    if (used + line.length + 1 > 1700) break;
    used += line.length + 1;
    body.push(line);
    picked.push({
      t: r.at, req: r.req, obs: r.obs, code: r.code, conf: r.conf,
      st: r.status, ch: r.chars, in: r.internal ? 1 : 0, n: redact(r.note)
    });
  }
  var payload = b64(JSON.stringify({
    v: VERSION, base: statBase(), led: { n: s.n, bad: s.bad, pct: s.pct }, rec: picked
  }));
  var out = head.join('\n') + '\n' + body.join('\n');
  if (payload) out += '\n#AR6LOG 1 ' + payload;
  return out;
}

/* ---------------- Đối chiếu A/B (Request trần vs Cấu hình hiện tại) ---------------- */

function abBody(framed) {
  var b = {
    model: (cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon'),
    messages: [{ role: 'user', content: 'Nói một câu "Được".' }],
    max_tokens: 24,
    stream: false
  };
  if (!framed) return b;
  try {
    var p = planRequest(JSON.stringify(b), openAIUrl(statBase()), false);
    if (p && p.body && p.body !== JSON.stringify(b)) return JSON.parse(p.body);
  } catch (e) {}
  return b;
}

function abArm(framed) {
  var url = openAIUrl(statBase());
  return probeOnce(url, abBody(framed), 45000).then(function (r) {
    return { framed: framed, status: r.status, model: r.model || '', err: r.err || '' };
  });
}

/* 2×2: Chỉ báo cáo "cấu hình có làm thay đổi tên quan sát được hay không", không đưa ra kết luận "bên nào tốt hơn" */
function abProbe() {
  if (AB_STATE.running) return Promise.resolve({ ok: false, msg: 'Đang chạy' });
  if (!statBase()) return Promise.resolve({ ok: false, msg: 'Vui lòng điền Base của reverse proxy trước' });
  AB_STATE.running = true;
  render();
  var seq = [false, true, false, true];
  var out = [];
  var step = function (i) {
    if (i >= seq.length) return Promise.resolve(out);
    return abArm(seq[i]).then(function (r) { out.push(r); return step(i + 1); });
  };
  return step(0).then(function (arr) {
    AB_STATE.running = false;
    var plain = [], framed = [];
    for (var i = 0; i < arr.length; i++) (arr[i].framed ? framed : plain).push(arr[i]);
    var same = function (a) { return a[0] && a[1] && a[0].model && a[0].model === a[1].model; };
    var note;
    if (!plain.length || !plain[0].model) note = 'Request trần không nhận được model, đối chiếu không thành lập (có thể kênh không ghi trường model)';
    else if (same(plain) && same(framed)) note = 'Hai nhánh đều tự ổn định, và cấu hình không làm thay đổi tên quan sát được —— Cấu hình an toàn';
    else if (same(plain) && !same(framed)) note = 'Sau khi bật cấu hình thì tên bắt đầu nhảy —— Cấu hình có thể gặp vấn đề tương thích với kênh';
    else note = 'Bản thân request trần đã không ổn định —— Đây không phải lỗi do cấu hình, mà do chính kênh đang biến động';
    var res = { ok: true, plain: plain, framed: framed, note: note, at: nowMs() };
    AB_STATE.last = res;
    render();
    return res;
  })['catch'](function (e) {
    AB_STATE.running = false;
    render();
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function abLine() {
  if (AB_STATE.running) return '⚖️ Đối chiếu A/B đang chạy…';
  var r = AB_STATE.last;
  if (!r) return '⚖️ Đối chiếu A/B: Chưa từng chạy (mỗi bên 2 request nhỏ, khoảng 10 giây)';
  var f = function (a) {
    return a.map(function (x) { return (x.model || ('HTTP' + x.status)); }).join(' / ');
  };
  return '⚖️ Trần: ' + f(r.plain) + ' ｜ Kèm cấu hình: ' + f(r.framed) + ' — ' + r.note;
}

/* ===== 6_float.js ===== */
/* ============================================================================
 * Anti-Route v7 — 6/6 Float
 * Nút nổi: Tùy chỉnh icon / kích thước / hình dạng / độ trong suốt / hít mép / kéo thả / thu gọn
 * Nguồn: Giải pháp nút nổi v6.7.4 từ cộng đồng, viết lại theo 5 điểm sửa đổi của chúng ta:
 *   1) Ảnh cục bộ giới hạn 300KB và downscale xuống 128px (localStorage chỉ có 5MB)
 *   2) Icon link ngoài tải thất bại sẽ tự động fallback về emoji
 *   3) Ngưỡng chạm nhẹ/kéo thả 12px + nhấn giữ 400ms mới vào trạng thái kéo thả
 *   4) Khu vực cài đặt gập độc lập, mặc định thu gọn, không chiếm chỗ bảng phán đoán
 *   5) Không làm ô nhiễm global của HOST nữa (trạng thái đặt trong state)
 * ========================================================================== */

var FLOAT_IMAGE_KEY = 'ar7.float.image';
var floatImageCache = null;
var floatPreview = null;
var floatDragging = false;

function floatImage() {
  if (floatPreview) return floatPreview;
  if (floatImageCache !== null) return floatImageCache;
  try { floatImageCache = HOST.localStorage.getItem(FLOAT_IMAGE_KEY) || ''; } catch (e) { floatImageCache = ''; }
  return floatImageCache;
}

function floatIconMarkup() {
  var url = floatImage() || cfg.floatIcon || '';
  if (url && /^(https?:\/\/|data:image\/)/i.test(url)) {
    return '<img class="ar6-custom-icon" draggable="false" alt="" src="' + esc(url) + '"' +
      ' onerror="this.style.display=\'none\';var p=this.parentNode;if(p){var s=p.querySelector(\'.ar6-fb\');if(s)s.style.display=\'inline\';}"' +
      ' style="position:absolute!important;inset:0!important;width:100%!important;height:100%!important;' +
      'max-width:none!important;max-height:none!important;min-width:100%!important;min-height:100%!important;' +
      'object-fit:cover!important;object-position:center!important;border-radius:inherit!important;' +
      'margin:0!important;padding:0!important;border:0!important;pointer-events:none!important;display:block!important">' +
      '<span class="ar6-fb" style="display:none;pointer-events:none;font-size:22px">🛡️</span>';
  }
  return '<span style="pointer-events:none;font-size:23px">🛡️</span>';
}

function ar6Rgb(hex, a) {
  var h = String(hex || '#0d1117').replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  var n = parseInt(h, 16);
  if (!isFinite(n)) n = 0x0d1117;
  var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
}

var PAD_OPEN = false;
var PAD_W = 190, PAD_H = 176;

/* Kích thước hộp của node gốc hiện tại: Quả cầu / Tay cầm / Bảng điều khiển */
function floatBoxSize() {
  if (PAD_OPEN) return { w: PAD_W, h: PAD_H };
  var n = floatSizePx();
  if (String(cfg.floatMode) === 'tuck') return { w: Math.max(10, Math.round(n * 0.3)), h: n };
  return { w: n, h: n };
}

function floatSizePx() {
  var n = Number(cfg.floatSize) || 44;
  return Math.max(28, Math.min(80, n));
}

function floatTint() {
  var code = 'gray';
  try {
    if (typeof kpi === 'function') {
      var k = kpi();
      /* v8.3: kpi chỉ cung cấp eff, không có total; warn phải phán đoán trước, nếu không sẽ vĩnh viễn không chạm tới */
      var n = Number(k.eff) || 0;
      var bad = Number(k.bad) || 0;
      code = (n >= 4 && bad / n >= 0.15) ? 'warn' : (bad > 0 ? 'bad' : 'ok');
    }
  } catch (e) {}
  if (code === 'bad') return { line: 'rgba(248,81,73,.55)', halo: 'rgba(248,81,73,.16)' };
  if (code === 'warn') return { line: 'rgba(210,153,34,.5)', halo: 'rgba(210,153,34,.14)' };
  return { line: 'rgba(88,166,255,.45)', halo: 'rgba(88,166,255,.14)' };
}

function floatStyle() {
  var box = floatBoxSize();
  var shape = cfg.floatShape === 'square' ? '12px' : '50%';
  if (PAD_OPEN) shape = '14px';
  var op = Math.max(0.12, Math.min(1, (Number(cfg.floatOpacity) || 45) / 100));
  var tint = floatTint();
  /* Trạng thái chờ bán trong suốt dùng nền rgba, chứ không dùng opacity của container —— nếu không vòng năng lượng sẽ bị làm mờ theo */
  /* Bảng điều khiển là panel thao tác: Cố định nền tối, tránh tình trạng user chỉnh màu cầu quá sáng làm chữ không đọc được */
  var bg = PAD_OPEN ? ar6Rgb('#161b22', 0.97) : ar6Rgb(cfg.floatBg || '#0d1117', op);
  return 'width:' + box.w + 'px;height:' + box.h + 'px;min-width:' + box.w + 'px;min-height:' + box.h + 'px;' +
    'padding:0!important;border-radius:' + shape + ';background:' + bg + ';' +
    'border:1px solid ' + (cfg.floatBorder ? tint.line : 'transparent') + ';' +
    'box-shadow:' + (cfg.floatShadow ? ('0 10px 26px rgba(0,0,0,.45),0 0 0 4px ' + tint.halo) : 'none') + ';' +
    'opacity:1;touch-action:none;user-select:none;-webkit-user-select:none;overflow:visible;' +
    'box-sizing:border-box;display:flex;align-items:center;justify-content:center;position:fixed;z-index:2147483000;left:0;top:0;' +
    'cursor:' + (PAD_OPEN ? 'default' : 'grab') + ';' +
    'transition:width .16s,height .16s,border-radius .16s,box-shadow .25s;';
}

var FLOAT_GEOM = { x: null, y: null };

/* ---- v8.1 Core layout: Vùng an toàn + Tọa độ chuẩn hóa + Hít mép ---- */

function floatVW() {
  var vv = HOST.visualViewport;
  var w = (vv && vv.width) || HOST.innerWidth || 360;
  return Math.round(w);
}

function floatVH() {
  var vv = HOST.visualViewport;
  var h = (vv && vv.height) || HOST.innerHeight || 640;
  return Math.round(h);
}

/* Vùng an toàn: Hai bên chừa PAD, đáy tránh vùng nhập liệu và thanh cử chỉ */
function getSafeBox() {
  var pad = (typeof uiMode === 'function' && uiMode() === 'mobile') ? 8 : 12;
  var l = pad, t = pad, r = floatVW() - pad, b = floatVH() - pad - 34;
  try {
    if (DOC && DOC.querySelector) {
      var f = DOC.querySelector('#send_form') || DOC.querySelector('#form_sheld');
      if (f) {
        var fr = f.getBoundingClientRect();
        if (fr && fr.height > 8 && fr.top > 40) b = Math.min(b, Math.round(fr.top) - pad);
      }
    }
  } catch (e) {}
  if (r - l < 80) r = l + 80;
  if (b - t < 80) b = t + 80;
  return { l: l, t: t, r: r, b: b };
}

function floatClampPx(x, y, w, h) {
  var s = getSafeBox();
  var maxX = Math.max(s.l, s.r - w);
  var maxY = Math.max(s.t, s.b - h);
  return {
    x: Math.round(Math.max(s.l, Math.min(maxX, x))),
    y: Math.round(Math.max(s.t, Math.min(maxY, y)))
  };
}

/* Tính vị trí pixel từ cfg.fxN/fyN/fEdge */
function floatLayoutPx() {
  var b = floatBoxSize();
  var w = b.w, h = b.h;
  var s = getSafeBox();
  var vw = floatVW();
  var nx = (typeof cfg.fxN === 'number') ? cfg.fxN : 1;
  var ny = (typeof cfg.fyN === 'number') ? cfg.fyN : 0.82;
  nx = Math.max(0, Math.min(1, nx));
  ny = Math.max(0, Math.min(1, ny));
  var x = s.l + nx * Math.max(0, (s.r - s.l) - w);
  var y = s.t + ny * Math.max(0, (s.b - s.t) - h);
  var mode = String(cfg.floatMode);
  if (!PAD_OPEN && mode === 'dock') {
    var reveal = Math.max(0.45, Math.min(0.8, (Number(cfg.floatDock) || 45) / 100));
    if (cfg.fEdge === 'l') x = -w * (1 - reveal);
    else if (cfg.fEdge === 'r') x = vw - w * reveal;
  } else if (!PAD_OPEN && mode === 'tuck') {
    x = (cfg.fEdge === 'l') ? 0 : (vw - w);
  }
  return { x: x, y: y, n: w, w: w, h: h };
}

/* Kéo xong ghi ngược lại tọa độ chuẩn hóa */
function floatSaveFromPx(r) {
  if (!r) return;
  var b = r.getBoundingClientRect();
  var box = floatBoxSize();
  var n = box.w;
  var s = getSafeBox();
  var w = Math.max(1, (s.r - s.l) - box.w);
  var h = Math.max(1, (s.b - s.t) - box.h);
  cfg.fxN = Math.max(0, Math.min(1, (b.left - s.l) / w));
  cfg.fyN = Math.max(0, Math.min(1, (b.top - s.t) / h));
  var mid = s.l + (s.r - s.l - box.w) / 2;
  cfg.fEdge = (b.left + box.w / 2 < mid) ? 'l' : 'r';
  cfg.floatX = Math.round(b.left);
  cfg.floatY = Math.round(b.top);
}

function floatApplyPosition(r, docked) {
  if (!r) return;
  var p = floatLayoutPx();
  var dockOn = docked && !PAD_OPEN && cfg.floatMode === 'dock';
  var tuckOn = docked && !PAD_OPEN && cfg.floatMode === 'tuck';
  if (!dockOn && !tuckOn) {
    var c = floatClampPx(p.x, p.y, p.w, p.h);
    p.x = c.x;
    p.y = c.y;
  }
  FLOAT_GEOM.x = Math.round(p.x);
  FLOAT_GEOM.y = Math.round(p.y);
  r.style.left = FLOAT_GEOM.x + 'px';
  r.style.top = FLOAT_GEOM.y + 'px';
  r.style.right = 'auto';
  r.style.bottom = 'auto';
  r.style.width = p.w + 'px';
  r.style.height = p.h + 'px';
  r.style.minWidth = p.w + 'px';
  r.style.minHeight = p.h + 'px';
}

function bindFloatGestures(r) {
  var pill = r.querySelector('.ar6-pill');
  if (!pill) return;
  var sx = 0, sy = 0, ox = 0, oy = 0;
  var downAt = 0, dragging = false, active = false, holdTimer = null, armed = false, moved = false;

  function commit() {
    var n = floatSizePx();
    var b = r.getBoundingClientRect();
    var c = floatClampPx(b.left, b.top, n, n);
    r.style.left = c.x + 'px';
    r.style.top = c.y + 'px';
    floatSaveFromPx(r);
    saveCfg();
    floatApplyPosition(r, true);
  }

  function openPanelFromBall() {
    /* Cầu ở nửa bên nào thì panel mở rộng từ nửa bên đó */
    var vw = floatVW();
    var vh = floatVH();
    var pw = Math.min(vw * 0.92, 380);
    var ph = Math.min(vh * 0.62, 720);
    var b = r.getBoundingClientRect();
    var s = getSafeBox();
    var mx = (b.left + b.width / 2 > vw / 2) ? (s.r - pw) : s.l;
    var my = Math.max(s.t, Math.min(s.b - ph, b.top - 8));
    cfg.mx = Math.round(mx);
    cfg.my = Math.round(my);
    saveCfg();
    minimized = false;
    syncMin();
    render();
  }

  pill.addEventListener('pointerdown', function (e) {
    if (e.button !== undefined && e.button !== 0) return;
    active = true; moved = false; armed = false; dragging = false;
    var b = r.getBoundingClientRect();
    ox = b.left; oy = b.top; sx = e.clientX; sy = e.clientY;
    downAt = Date.now();
    try { pill.setPointerCapture(e.pointerId); } catch (err) {}
    holdTimer = setTimeout(function () { holdTimer = null; armed = true; }, 450);
  }, { passive: true });

  pill.addEventListener('pointermove', function (e) {
    if (!active) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (!dragging && Math.abs(dx) + Math.abs(dy) < 6) return;
    dragging = true; moved = true;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (e.preventDefault) e.preventDefault();
    var n = floatSizePx();
    var s = getSafeBox();
    var nx = Math.max(-n, Math.min(floatVW() - 1, ox + dx));
    var ny = Math.max(s.t - 24, Math.min(s.b - n, oy + dy));
    r.style.right = 'auto';
    r.style.bottom = 'auto';
    r.style.left = Math.round(nx) + 'px';
    r.style.top = Math.round(ny) + 'px';
  }, { passive: false });

  function end() {
    if (!active) return;
    active = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (dragging) { dragging = false; commit(); return; }
    if (armed) { armed = false; try { openPanelFromBall(); } catch (eOpen) {} return; }
    if (Date.now() - downAt < 450) { try { openPad(); } catch (ePad) {} }
  }

  pill.addEventListener('pointerup', end);
  pill.addEventListener('pointercancel', function () {
    active = false; dragging = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
  });
}

/* ---- v8.1 Kéo thả panel: Tiêu đề/vùng trống kéo trực tiếp, vùng cuộn nhấn giữ 450ms mới kéo ---- */
function installRootDrag(r, kind) {
  if (!r) return;
  if (r.__ar6rd) { r.__ar6kind = kind; return; }
  r.__ar6rd = true; r.__ar6kind = kind;
  var active = false, armed = false, moved = false;
  var sx = 0, sy = 0, ox = 0, oy = 0;
  var holdTimer = null;
  /* v8.30: Tách riêng xử lý touch và chuột. Khi ngón tay chạm vào phần nội dung có thể cuộn sẽ không cướp sự kiện ngay,
     nếu không preventDefault sẽ chặn đứng cuộn gốc —— người dùng sẽ thấy "panel không vuốt được mà lại bị kéo đi". */
  var touchMode = false, armLong = false;

  function hitInteractive(t) {
    var p = t;
    while (p && p !== r) {
      if (p.getAttribute && p.getAttribute('data-ar6')) return true;
      var tag = (p.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select' || tag === 'button' || tag === 'summary' || tag === 'a') return true;
      p = p.parentNode;
    }
    return false;
  }

  function hitHeader(t) {
    var p = t;
    while (p && p !== r) {
      if (p.className) {
        var cls = String(p.className).split(/\s+/);
        for (var ci = 0; ci < cls.length; ci++) if (cls[ci] === 'ar6-h' || cls[ci] === 'ar6-grip') return true;
      }
      p = p.parentNode;
    }
    return false;
  }

  function hitScroll(t) {
    var p = t;
    while (p) {
      try {
        if (p.nodeType === 1 && p.clientHeight > 0 && p.scrollHeight > p.clientHeight + 2) return true;
      } catch (e) {}
      if (p === r) break;
      p = p.parentNode;
    }
    return false;
  }

  r.addEventListener('pointerdown', function (e) {
    if (e.button !== undefined && e.button !== 0) return;
    var t = e.target || e.srcElement;
    if (!t || hitInteractive(t)) return;
    var isTouch = (e.pointerType === 'touch');
    touchMode = isTouch; armLong = false;
    /* Tiêu đề: Mọi phương thức nhập liệu đều có thể kéo trực tiếp; Nội dung: Chuột có thể kéo, ngón tay phải nhấn giữ 450ms trước.
       Ngón tay vừa chạm đã armed sẽ nuốt mất thao tác cuộn gốc, khiến người dùng cảm giác "không vuốt được". */
    var direct = hitHeader(t) || (!isTouch && !hitScroll(t));
    var b = r.getBoundingClientRect();
    active = true; moved = false; armed = false;
    sx = e.clientX; sy = e.clientY; ox = b.left; oy = b.top;
    if (direct) { armed = true; }
    else {
      holdTimer = setTimeout(function () { holdTimer = null; armed = true; armLong = true; }, 450);
    }
  }, { passive: true });

  r.addEventListener('pointermove', function (e) {
    if (!active) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (!moved && Math.abs(dx) + Math.abs(dy) < 6) return;
    if (!armed) {
      active = false;
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
      return;
    }
    moved = true;
    /* Cảm ứng bắt buộc phải sau khi nhấn giữ mới cho phép nuốt sự kiện; chưa nhấn giữ đều thả cho trình duyệt cuộn */
    if (e.preventDefault && (!touchMode || armLong)) e.preventDefault();
    r.style.transition = 'none';
    r.style.transform = 'translate3d(' + Math.round(dx) + 'px,' + Math.round(dy) + 'px,0)';
  }, { passive: false });

  function end(cancelled) {
    if (!active) return;
    active = false;
    if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
    if (moved && !cancelled) {
      /* Đo rect trước (bao gồm translate3d), rồi mới xóa transform —— ngược thứ tự sẽ bị nảy về chỗ cũ */
      var b = r.getBoundingClientRect();
      var w = b.width || 320, h = b.height || 240;
      var c = floatClampPx(b.left, b.top, w, h);
      r.style.transform = '';
      r.style.transition = '';
      r.style.left = c.x + 'px';
      r.style.top = c.y + 'px';
      r.style.right = 'auto';
      r.style.bottom = 'auto';
      var k2 = r.__ar6kind || kind;
      if (k2 === 'ball') floatSaveFromPx(r);
      else if (k2 === 'pad') { floatSaveFromPx(r); }
      else { cfg.mx = c.x; cfg.my = c.y; saveCfg(); }
    } else {
      r.style.transform = '';
      r.style.transition = '';
    }
    moved = false; armed = false; armLong = false;
  }

  r.addEventListener('pointerup', function () { end(false); });
  r.addEventListener('pointercancel', function () { end(true); });
}

/* ---------------- Cài đặt giao diện (Gập độc lập, mặc định thu gọn) ---------------- */

var FLOAT_UI_OPEN = false;

function floatSettingsHTML() {
  var modes = [['dock', 'Hít mép ẩn một nửa'], ['float', 'Nút nổi cố định'], ['tuck', 'Tay cầm sát mép (tiết kiệm chỗ nhất)']];
  var opts = '';
  for (var i = 0; i < modes.length; i++) {
    opts += '<option value="' + modes[i][0] + '"' + (cfg.floatMode === modes[i][0] ? ' selected' : '') + '>' + modes[i][1] + '</option>';
  }
  var n = floatSizePx();
  return '<details class="ar6-custom"' + (FLOAT_UI_OPEN ? ' open' : '') + '>' +
    '<summary>Giao diện nút nổi</summary>' +
    '<div class="ar6-custom-body">' +
