      '<label class="ar6-mode-row"><span>Ảnh cục bộ &lt;300KB</span><input type="file" data-ar6-setting="imageFile" accept="image/png,image/jpeg,image/webp,image/gif"></label>' +
      '<label class="ar6-mode-row"><span>Vị trí ngang</span>' +
        '<input type="range" min="0" max="100" step="1" data-ar6-pos="x" value="' + Math.round((typeof cfg.fxN === 'number' ? cfg.fxN : 1) * 100) + '"><b>' + Math.round((typeof cfg.fxN === 'number' ? cfg.fxN : 1) * 100) + '%</b></label>' +
      '<label class="ar6-mode-row"><span>Vị trí dọc</span>' +
