function jailOffer(j) {
  var cur = jailLastAi();
  var key = cur ? (String(cur.idx) + '|' + String(cur.msg.send_date || '')) : 'noctx';

  /* v0.2: Lượt bắn trước khắc phục xong, nếu tin nhắn này đã quay về bình thường, ghi nhận một lần "cải thiện" */
  if (JL.pendKey && key === JL.pendKey && j.code === 'ok') {
    JL.ok++; JL.pendKey = '';
  }
  JAIL_ASK.at = nowMs();
  JAIL_ASK.code = (j && j.code) || '';
  JAIL_ASK.key = key;
  var node = null;
  try {
    /* v8.0.3: Đăng ký thành layer nổi, nhấn vào khung xác nhận sẽ không thu gọn panel chính */
    if (typeof CARD === 'object' && CARD) { CARD.open = true; CARD.rid = -1; CARD.tab = 'jail'; }
    node = mountHTML(jailConfirmHTML(j, cur));
  } catch (eM) {
    try { banner('🩹 Không thể vẽ khung xác nhận: ' + String(eM && eM.message || eM), 'bad'); } catch (e2) {}
    return false;
  }
