  node.addEventListener('click', function (ev) {
    var t = ev.target;
    var act = (t && t.getAttribute && t.getAttribute('data-ar6-card')) || '';
    if (act === 'jailgo') {
      closeCard();
      var g = jailGate(key);
      if (!g.ok) {
        if (g.why === 'max') banner('🩹 Lượt này đã khắc phục ' + JL.count + ' lần nhưng vẫn có lỗi, tạm dừng lại', 'bad');
        else if (g.why === 'rate') banner('🩹 Đã khắc phục quá nhiều lần trong một phút, tạm dừng lại', 'bad');
        else banner('🩹 Hiện không thể khắc phục (' + g.why + ')', 'warn');
        return;
      }
      jailSchedule(j, JL.count + 1, 1);   /* v0.12: Đồng bộ với var max = 1 trong jailFire, không hiển thị (1/2) nữa */
      return;
