function jailAskPending() { return !JAIL_ASK.at && (nowMs() - JAIL_ASK.at < 120000); }

function jailSchedule(j, n, max) {
  JL.count = n;
  JL.at = nowMs();
  JL.lock = true;
  JL.lockAt = nowMs();
  banner('🩹 ' + j.note + ', tự động viết tiếp (' + n + '/' + max + ')…', 'warn');
  var tries = 0;
  var iv = setInterval(function () {
    tries++;
    var busy = false;
    try { busy = isBusy(); } catch (e) {}
    if (!busy) {
      clearInterval(iv);
      JL.lock = false;
      jailFire();
    } else if (tries >= JAIL_WAIT_MAX) {
      clearInterval(iv);
      JL.lock = false;
      banner('🩹 SillyTavern liên tục trong trạng thái sinh văn bản, lượt này không khắc phục nữa', 'warn');
    }
  }, 250);
  WATCHERS.push(iv);
}

