function jailStatLine() {
  var t = Number(JL.try || 0), k = Number(JL.ok || 0);
  if (!t) return 'Phá giáp: Phiên này chưa từng khắc phục (' + (cfg.jail === 'off' ? 'hiện đang tắt' : 'hiện đang bật') + ')';
  var pct = t ? Math.round(k / t * 100) : 0;
  return 'Phá giáp: Khắc phục ' + t + ' lần · Sau khi khắc phục đã phục hồi ' + k + ' lần (' + pct + '%)' +
    (t >= 5 && pct === 0 ? ' ｜ Chưa từng thành công lần nào, đừng khắc phục nữa, hãy đổi kênh' : '');
}

function jailAfterFinish(ev) {
  if (!cfg || !cfg.enabled || cfg.jail === 'off' || cfg.safe) return;
  if (!ev || ev.status !== 200 || ev.error) return;
  /* v8.29: Request nội bộ không có sản phẩm chat, đừng lấy nó để phán đoán phản hồi rỗng/cắt cụt */
  if (ev.internal) return;
  /* v8.29: Vừa tự mình kích hoạt viết tiếp —— lần kết thúc tiếp theo phần lớn là phản hồi của chính phát bắn đó, tạm tha một lượt để tránh khắc phục liên hoàn */
  if (JL.selfAt && nowMs() - JL.selfAt < 90000) { JL.selfAt = 0; return; }

  var j = jailInspect(ev);
  if (!j) return;

  if (j.code === 'refuse') {
    /* v0.2: Từ chối không chỉ dừng ở việc thông báo "đã dừng lại", mà còn phân loại rõ thuộc nhóm nào, bước tiếp theo nên làm gì */
    JL.lastWhy = j.hard ? 'safety' : 'tone';
    banner('🩹 ' + j.note + (j.hard ? ': Lượt này đừng khắc phục, hãy đổi kênh hoặc đổi model rồi thử lại' : ': Lượt này không khắc phục, hãy xem chính văn bị đứt ở đâu trước'), 'bad');
    return;
  }
  if (j.code !== 'empty' && j.code !== 'trunc') return;

  var cur = jailLastAi();
  var key = cur ? (String(cur.idx) + '|' + String(cur.msg.send_date || '')) : 'noctx';

  /* v0.2: Sau khi lượt khắc phục trước kết thúc, nếu tin nhắn này đã bình thường, ghi nhận một lần "cải thiện" */
  if (JL.pendKey && key === JL.pendKey && j.code === 'ok') {
    JL.ok++; JL.pendKey = '';
  }
  var g = jailGate(key);
  if (!g.ok) {
    if (g.why === 'max') banner('🩹 Lượt này đã khắc phục ' + JL.count + ' lần nhưng vẫn có lỗi, tạm dừng lại (kiểm tra kênh hoặc preset)', 'bad');
    else if (g.why === 'rate') banner('🩹 Đã khắc phục 6 lần trong một phút, tạm dừng lại (trông giống vòng lặp vô tận)', 'bad');
    return;
  }
  var max = 1;
  if (cfg.jailConfirm === false && JL.count < 1) {
    JL.try++; JL.pendKey = key;
    jailSchedule(j, JL.count + 1, max);
    return;
  }
  jailOffer(j);
}

