/* ============================================================================
 * Anti-Route v7.2 — 8/8 Sàng lọc danh tính (Kiểm tra sàng lọc bad token)
 *
 * Công dụng: Bộ phát hiện hạ cấp bất đối xứng.
 *   - Chép sai (tỷ lệ trúng thấp) ⇒ Phần lớn không phải model cao cấp mục tiêu (rẻ tiền, có thể chạy thường xuyên)
 *   - Chép đúng (tỷ lệ trúng cao) ⇒ Không chứng minh được là model mục tiêu, chỉ có thể nói "không giống kẻ đóng thế giá rẻ"
 * Thiết luật: Chỉ gửi một request nhỏ độc lập (không chạm vào request chat), thất bại không throw, không ghi vào chat.
 * ========================================================================== */

var ID_KEY = 'ar7.id';
var ID_ITEMS = [
  '',
  'Kv7Qm2Lz9RxT',
  'b3f9c1e7a2d84b06',
  'NlPz4Wq8Jh2V',
  'FragmentationCacheXn3',
  'SrvGroupKernelBody',
  'Qz9Lm4Tb7Wn2',
  '7fa2c9e1d3b84605',
  'Hn5Kp3Xs8Qv1',
  'ThreadLocalFragmentation',
  'Xz6Wq9Lm3Rt7'
];
var ID = { running: false, result: null, used: [] };

function idLoad() {
  try {
    var s = JSON.parse(localStorage.getItem(ID_KEY) || '{}');
    ID.used = Array.isArray(s.used) ? s.used : [];
    ID.result = s.result || null;
  } catch (e) { ID.used = []; ID.result = null; }
}

function idSave() {
  try {
    localStorage.setItem(ID_KEY, JSON.stringify({ used: ID.used.slice(-24), result: ID.result }));
  } catch (e) {}
}

/* Luân phiên: Ưu tiên mục chưa từng chạy, chạy hết một vòng thì reset lại */
function idPick() {
  idLoad();
  var pool = [];
  for (var i = 0; i < ID_ITEMS.length; i++) {
    if (ID.used.indexOf(ID_ITEMS[i]) < 0) pool.push(ID_ITEMS[i]);
  }
  if (pool.length < 6) { ID.used = []; pool = ID_ITEMS.slice(); }
  return pool.slice(0, 8);
}

function idBody(items) {
  var lines = [];
  for (var i = 0; i < items.length; i++) lines.push((i + 1) + ') ' + items[i]);
  var user = 'Dưới đây có ' + items.length + ' dòng định danh. Hãy sao chép nguyên văn từng dòng từng chữ một (chữ hoa chữ thường, chữ số, chữ cái đều không được thay đổi), ' +
    'và đoán xem nó có khả năng xuất phát từ hệ thống nào nhất (một câu, dưới mười chữ).\n' +
    'Chỉ xuất một mảng JSON, không xuất bất kỳ lời giải thích nào, không bọc bằng khối code, định dạng:\n' +
    '[{"id":"nguyên văn","copy":"nguyên văn bạn sao chép","guess":"suy đoán"}]\n\n' + lines.join('\n');
  return {
    messages: [
      { role: 'system', content: 'Bạn là một bộ sao chép từng chữ. Chỉ sao chép, không giải thích, không sửa bất kỳ lỗi chính tả nào.' },
      { role: 'user', content: user }
    ],
    max_tokens: 800,
    stream: false
  };
}

function idNorm(s) {
  return String(s == null ? '' : s).replace(/^[\s"'`「」『』]+|[\s"'`「」『』]+$/g, '').replace(/\s+/g, '');
}

/* Tách [{id,copy}] ra khỏi văn bản: Toàn bộ JSON → Khối code → Cắt mảng đầu tiên → Regex từng dòng */
function idEntries(text) {
  var t = String(text || '');
  var tries = [t];
  var f = /```(?:json)?\s*([\s\S]*?)```/i.exec(t);
  if (f) tries.push(f[1]);
  var a = t.indexOf('['), b = t.lastIndexOf(']');
  if (a >= 0 && b > a) tries.push(t.slice(a, b + 1));
  for (var i = 0; i < tries.length; i++) {
    try {
      var arr = JSON.parse(tries[i]);
      if (Array.isArray(arr)) return arr;
    } catch (e) {}
  }
  var out = [];
  var rx = /"id"\s*:\s*"([^"]*)"[\s\S]{0,200}?"copy"\s*:\s*"([^"]*)"/gi;
  var m;
  while ((m = rx.exec(t)) && out.length < 40) out.push({ id: m[1], copy: m[2] });
  return out;
}

function idScore(text, items) {
  var rows = [];
  var entries = idEntries(text);
  for (var i = 0; i < items.length; i++) {
    var want = items[i];
    var got = '';
    for (var k = 0; k < entries.length; k++) {
      var e = entries[k] || {};
      var eid = idNorm(e.id), ecopy = idNorm(e.copy);
      if (eid === idNorm(want) || ecopy === idNorm(want)) { got = String(e.copy || e.id || ''); break; }
    }
    if (!got && entries.length === items.length) got = String(entries[i].copy || entries[i].id || '');
    rows.push({ item: want, got: got, ok: idNorm(got) === idNorm(want) });
  }
  return rows;
}

function idVerdict(hit, n) {
  if (!n) return { code: 'error', label: 'Chưa đo', note: 'Không nhận được response có thể phân tích' };
  var rate = hit / n;
  var w = wilson(hit, n);
  var ci = (Math.round(w.lo * 1000) / 10) + '% ~ ' + (Math.round(w.hi * 1000) / 10) + '%';
  if (n < 6) return { code: 'unknown', label: 'Mẫu chưa đủ', note: 'Chỉ mới chạy ' + n + ' dòng, kết luận không khả dụng (95%CI ' + ci + ')' };
  if (rate < 0.5) return { code: 'fail', label: 'Không giống cao cấp', note: 'Trúng ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95%CI ' + ci + ') ⇒ Phần lớn không phải model mục tiêu, hoặc lần này đã bị hạ cấp' };
  if (rate > 0.85) return { code: 'pass', label: 'Nghi ngờ cao cấp', note: 'Trúng ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95%CI ' + ci + ') ⇒ Không chứng minh được danh tính, chỉ nói lên rằng "không giống kẻ đóng thế giá rẻ"' };
  return { code: 'mid', label: 'Chưa xác định', note: 'Trúng ' + hit + '/' + n + ' (' + Math.round(rate * 100) + '%, 95%CI ' + ci + ') ⇒ Mẫu chưa thể phân biệt, hãy chạy lại lần nữa' };
}

function runIdentityProbe() {
  if (ID.running) return Promise.resolve({ ok: false, msg: 'Đang chạy, vui lòng đợi' });
  var base = String(cfg.dualBase || (lastReq && lastReq.base) || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: 'Vui lòng điền Base của reverse proxy trước (hoặc chạy bình thường một lượt trước)' });
  var items = idPick();
  if (!items.length) return Promise.resolve({ ok: false, msg: 'Kho đầu dò rỗng' });
  var url = openAIUrl(base);
  var body = idBody(items);
  ID.running = true;
  return probeOnce(url, body, 45000).then(function (r) {
    ID.running = false;
    var text = String(r.raw || '');
    if (!text) {
      var bad = { at: nowMs(), n: items.length, hit: 0, verdict: 'error', note: 'Đầu dò không có response: ' + (r.err || ('HTTP ' + r.status)), rows: [] };
      ID.result = bad; idSave(); render();
      return { ok: false, msg: bad.note };
    }
    var rows = idScore(text, items);
    var hit = 0;
    for (var i = 0; i < rows.length; i++) if (rows[i].ok) hit++;
    var v = idVerdict(hit, rows.length);
    ID.result = {
      at: nowMs(), n: rows.length, hit: hit, verdict: v.code,
      label: v.label, note: v.note, model: String(r.model || ''), rows: rows
    };
    for (var k = 0; k < items.length; k++) if (ID.used.indexOf(items[k]) < 0) ID.used.push(items[k]);
    idSave(); render();
    return { ok: true, hit: hit, n: rows.length, verdict: v.code, label: v.label, note: v.note };
  })['catch'](function (e) {
    ID.running = false;
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function idCard() {
  var r = ID.result;
  if (!r) return '<div class="ar6-note">Sàng lọc danh tính: Chưa chạy. Nhấn "Sàng lọc danh tính" —— Chép sai ⇒ Phần lớn không phải model cao cấp; Chép đúng ⇒ Chỉ loại trừ kẻ đóng thế giá rẻ, không chứng minh được danh tính.</div>';
  var color = r.verdict === 'fail' ? 'ar6-bad' : (r.verdict === 'pass' ? 'ar6-ok' : 'ar6-warn');
  var h = '<div class="ar6-note"><span class="' + color + '">' + esc(r.label || r.verdict) + '</span> · ' + esc(r.note || '') + '</div>';
  var rows = r.rows || [];
  if (rows.length) {
    h += '<div class="ar6-kv">';
    for (var i = 0; i < rows.length && i < 10; i++) {
      h += '<span class="ar6-k">' + (rows[i].ok ? '✅' : '❌') + ' ' + esc(rows[i].item) + '</span>' +
        '<span class="ar6-v">' + esc(rows[i].got || ' (Không chép)') + '</span>';
    }
    h += '</div>';
  }
  return h;
}

function idFooter() {
  var r = ID.result;
  if (!r) return 'Danh tính Chưa đo';
  return 'Danh tính ' + (r.label || r.verdict) + ' ' + r.hit + '/' + r.n;
}

/* ===== 3_net.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 3/4 Net
 * Request hook / Bộ quan sát host zero-lock / Bộ phán đoán / Hai đầu dò
 * Then chốt: HTTP 200 không chạm vào res.body, không gọi tee() và clone()
 * ========================================================================== */

var origFetch = null;
var hooked = false;
var booted = false;
var lastReq = null;
var inflight = 0;

function nowMs() { return Date.now(); }

function urlOf(input) {
  try {
    if (typeof input === 'string') return input;
    if (input && typeof input.url === 'string') return input.url;
  } catch (e) {}
  return '';
}

function isGenerateUrl(u) {
  return /\/chat-completions\/generate\b/.test(String(u || ''));
}

/* ---------------- Bằng chứng và Phán đoán ---------------- */

/* Các phiên bản Gemini đã ngừng hoạt động: Loại tên này chỉ có thể là "nhãn request" hoặc gateway echo, không thể dùng làm bằng chứng danh tính */
var RETIRED_MODEL_RE = /gemini[\s._-]?(?:1\.0|1\.5|2\.0|2\.5)[\s._-]?(?:pro|flash|ultra)|(?:pro|flash)-00[12]|gemini-pro-vision/i;

var PEEK_SEQ = 0;
var PEEKS = {};

/* Request nội bộ: Các plugin như database/điền biểu mẫu tự gắn marker phát lệnh generate, không tạo ra sản phẩm chat */
var INTERNAL_FETCH_KEY = (typeof Symbol === 'function' && Symbol.for) ? Symbol.for('acu.internal-generation-fetch') : null;

function isInternalRequest(init, bodyObj) {
  try {
    if (init && INTERNAL_FETCH_KEY && init[INTERNAL_FETCH_KEY] === true) return true;
  } catch (e0) {}
  try {
    var msgs = bodyObj && bodyObj.messages;
    if (!Array.isArray(msgs) || !msgs.length) return false;
    /* v8.29: Request generate bình thường của SillyTavern chắc chắn có type (normal/swipe/quiet…); body do plugin tự ghép sẽ không có */
    if (bodyObj.type) return false;
    if (msgs.length > 2) return false;
    for (var i = 0; i < msgs.length; i++) {
      if (String((msgs[i] && msgs[i].role) || '') === 'assistant') return false;
    }
    /* Chỉ nhìn số lượng tin nhắn sẽ dễ nhận nhầm "lượt đầu system+user" thành request nội bộ, dẫn tới vĩnh viễn không đọc được chính văn.
       Bắt buộc phải có thêm bằng chứng cho thấy nó đi qua kênh riêng: Kênh custom + địa chỉ reverse proxy. */
    if (String(bodyObj.chat_completion_source || '') !== 'custom') return false;
    if (!bodyObj.reverse_proxy) return false;
    return true;
  } catch (e1) { return false; }
}

function pushObs(ev, val, src) {
  try {
    var v = String(val == null ? "" : val).trim();
    if (!v || ev.observed.indexOf(v) >= 0) return;
    ev.observed.push(v);
    if (!ev.observedSrc) ev.observedSrc = [];
    ev.observedSrc.push(src || "?");
  } catch (e) { }
}

function newEvidence(model, status, transport) {
  return {
    requestedModel: model, observed: [], observedSrc: [], status: status, transport: transport,
    verifiable: 'unknown',
    sawText: false, hasThink: false, hasReasonField: false,
    outputChars: 0, thoughtTok: 0, firstMs: 0, totalMs: 0, error: ''
  };
}

/* v0.13: Phạm vi kiểm tra. 'in' nằm trong phạm vi / 'out' không nằm trong phạm vi / 'anon' chưa đọc được tên model */
function scopeLabel() {
  var n = 0, a = String(cfg.scopeList || '').split(',');
  for (var i = 0; i < a.length; i++) { if (String(a[i] || '').trim()) n++; }
  if (cfg.scope === 'only') return 'Chỉ kiểm tra ' + n + ' mục';
  if (cfg.scope === 'skip') return 'Bỏ qua ' + n + ' mục';
  return 'Toàn bộ';
}

function scopeMatch(model) {
  var mode = String(cfg.scope || 'all');
  if (mode !== 'only' && mode !== 'skip') return 'in';
  var list = String(cfg.scopeList || '').split(',');
  var keys = [];
  for (var i = 0; i < list.length; i++) {
    var k = String(list[i] || '').trim().toLowerCase();
    if (k) keys.push(k);
  }
  if (!keys.length) return 'in';          /* Danh sách trống thì đừng âm thầm bỏ sót mọi thứ */
  var m = String(model || '').trim().toLowerCase();
  if (!m) return 'anon';                  /* Không đọc được tên model: Không giả vờ nó nằm trong phạm vi, cũng không giả vờ nó nằm ngoài */
  var hit = false;
  for (var j = 0; j < keys.length; j++) { if (m.indexOf(keys[j]) >= 0) { hit = true; break; } }
  if (mode === 'only') return hit ? 'in' : 'out';
  return hit ? 'out' : 'in';
}

var VERDICT = {
  same:    { label: 'Khớp', color: 'ok' },
  diff:    { label: 'Bị tráo', color: 'bad' },
  thin:    { label: 'Mất suy nghĩ', color: 'warn' },
  unknown: { label: 'Chưa rõ', color: 'gray' },
  quota:   { label: 'Hạn ngạch', color: 'warn' },
  blocked: { label: 'Bị chặn', color: 'bad' },
  gate:    { label: 'Lỗi gateway', color: 'bad' },
  empty:   { label: 'Không có chính văn', color: 'gray' },
  echo:    { label: 'Echo', color: 'gray' },
  error:   { label: 'Thất bại', color: 'bad' },
  skip:    { label: 'Bỏ qua', color: 'gray' }
};

function channelSeesThinking() {
  try {
    var log = readLog() || [];
    for (var i = 0; i < log.length && i < 30; i++) {
      if (log[i] && log[i].think) return true;
    }
  } catch (e) {}
  return false;
}

function verdictOf(ev) {
  if (ev.error) return { code: 'error', note: ev.error, conf: 'C' };
  if (ev.status === 429) return { code: 'quota', note: 'HTTP 429', conf: 'C' };
  if (ev.status >= 500) return { code: 'gate', note: 'HTTP ' + ev.status, conf: 'C' };
  if (ev.blocked) return { code: 'blocked', note: ev.blocked, conf: 'C' };
  if (!ev.sawText && ev.status >= 400) return { code: 'error', note: 'HTTP ' + ev.status, conf: 'C' };
  /* v8.29: Request nội bộ (database/điền biểu mẫu) vốn dĩ không tạo ra sản phẩm chat ⇒ Không đọc được chính văn không đồng nghĩa với phản hồi rỗng */
  if (!ev.sawText && ev.internal) {
    return { code: 'unknown', note: 'Request nội bộ (database hoặc điền biểu mẫu): Không có sản phẩm chat, không phán đoán phản hồi rỗng', conf: 'C' };
  }
  if (!ev.sawText) {
    if (ev.emptyConfirmed) return { code: 'empty', note: 'Cả response body và chat đều không có chính văn (xác nhận phản hồi rỗng)', conf: 'C' };
    return { code: 'empty', note: 'Chưa đọc được chính văn (chưa lấy được response body, lấy mẫu nhánh phụ có thể đang tắt)', conf: 'C' };
  }

  /* v0.13: Đến đây mới xét phạm vi —— Phản hồi rỗng/lỗi/chặn thuộc về "phản hồi đã mất", không liên quan đến model nào, phán đoán trước;
     "Có bị tráo hay không" mới liên quan đến model, model không nằm trong phạm vi thì chỉ để lại một bản ghi màu xám */
  var sc = scopeMatch(ev.requestedModel);
  if (sc === 'out') {
    return { code: 'skip', note: 'Không nằm trong phạm vi kiểm tra (' + scopeLabel() + ')', conf: 'C' };
  }

  var req = ev.requestedModel;
  var ver = ev.verifiable || 'unknown';          /* yes=có thể kiểm tra, no=echo, unknown=chưa kiểm tra */
  var obs = [], srcs = [];
  for (var i0 = 0; i0 < ev.observed.length; i0++) {
    var x0 = String(ev.observed[i0] || '').trim();
    if (!x0 || /^(?:auto|router|default|unknown|any)$/i.test(x0)) continue;
    var s0 = (ev.observedSrc && ev.observedSrc[i0]) || '?';
    if (s0 === 'msg' && RETIRED_MODEL_RE.test(x0)) continue;   /* Nhãn cũ không tính là bằng chứng */
    obs.push(x0); srcs.push(s0);
  }

  /* Thứ tự ưu tiên bằng chứng: Response body > Nhật ký chat (nhãn); cùng nguồn tính theo thứ tự đến */
  var order = [], orderSrc = [];
  for (var s1 = 0; s1 < srcs.length; s1++) {
    if (srcs[s1] === 'body') { order.push(obs[s1]); orderSrc.push('body'); }
  }
  for (var s2 = 0; s2 < srcs.length; s2++) {
    if (srcs[s2] !== 'body') { order.push(obs[s2]); orderSrc.push(srcs[s2]); }
  }

  for (var i = 0; i < order.length; i++) {
    var a = normModel(req), b = normModel(order[i]);
    if (!a || !b) continue;
    var fromBody = orderSrc[i] === 'body';
    var same = (a === b);
    var fa = familyOf(a), fb = familyOf(b);

    /* Kênh không đọc model: Nhãn trên nhật ký chat không đáng tin cậy; nhưng phần tự khai trong response body vẫn có hiệu lực */
    if (ver === 'no' && !fromBody) {
      if (same) continue;
      continue;
    }

    var baseConf = fromBody ? ((ver === 'yes') ? 'A' : 'B') : (ver === 'yes' ? 'B' : 'C');

    if (same) {
      if (!ev.internal && isProLike(a) && !ev.hasThink && channelSeesThinking()) {
        return { code: 'thin', note: 'Model khớp nhưng lượt này không có suy nghĩ', conf: 'B', obs: order[i] };
      }
      return { code: 'same', note: shortName(order[i]) + (fromBody ? ' (Response body)' : ''), conf: baseConf, obs: order[i] };
    }

    /* Khác hãng: Bảng tier không thể so sánh, trực tiếp tính là bị tráo; và echo sẽ chỉ phản hồi lại tên đã request ⇒ Sự khác biệt khác họ mặc nhiên loại trừ echo */
    if (fa && fb && fa !== fb) {
      return {
        code: 'diff',
        note: 'Khác họ: ' + shortName(a) + ' (' + fa + ') → ' + shortName(b) + ' (' + fb + ')',
        conf: fromBody ? 'A' : baseConf, obs: order[i]
      };
    }

    var ta = tierOf(a), tb = tierOf(b);
    if (ta > 0 && tb > 0 && tb < ta) {
      return { code: 'diff', note: shortName(order[i]) + ' (T' + tb + '<T' + ta + ')', conf: baseConf, obs: order[i] };
    }
    /* Response body khai báo một model khác: Ngay cả khi cùng tier, cũng tính là bị tráo */
    if (fromBody) {
      return { code: 'diff', note: 'Response body: ' + shortName(b) + ' ≠ Request ' + shortName(a), conf: baseConf, obs: order[i] };
    }
    return { code: 'echo', note: 'Model khác nhau nhưng không thể định tier: ' + shortName(order[i]), conf: 'C', obs: order[i] };
  }
  return {
    code: 'unknown',
    note: ev.internal ? 'Request nội bộ (database/điền biểu mẫu): Không có sản phẩm chat, response body cũng không trả về model' :
      (ver === 'no' ? 'Kênh không thể xác thực, không có bằng chứng danh tính' : 'Upstream không trả về định danh model'),
    conf: 'C'
  };
}

function finish(ev, meta) {
  /* Khi nhật ký chat chưa commit (hoặc commit chậm), đừng vội kết luận "không có chính văn":
     Trong response body rõ ràng có văn bản thì hãy đợi nó hoàn tất, rồi dùng nó làm phương án dự phòng. */
  /* v0.12: Request nội bộ không lấy body, cũng sẽ không có PEEKS để đợi —— trước đây chỗ này sẽ chạy không tải 6 giây mới ghi bản ghi */
  if (!ev.sawText && ev.status === 200 && ev.rid && !ev.internal) {
    var pk0 = PEEKS[ev.rid];
    if (!ev.__peekAt) ev.__peekAt = nowMs();
    var waited = nowMs() - ev.__peekAt;
    /* Đợi nó hoàn tất: Kết thúc luồng stream và đọc peek không đồng bộ, 900ms đơn lẻ thường không đủ */
    if ((!pk0 || !pk0.done) && waited < 6000) {
      ev.__peekDefer = (ev.__peekDefer || 0) + 1;
      setTimeout(function () { try { finish(ev, meta); } catch (eD) {} }, 700);
      return null;
    }
    if (pk0 && pk0.hasText) {
      ev.sawText = true;
      ev.bodyText = true;
      if (!ev.outputChars || ev.outputChars < pk0.textChars) ev.outputChars = pk0.textChars;
    } else if (pk0 && pk0.done) {
      /* Response body cũng đã đọc xong, thực sự không có chữ: Đây mới là phản hồi rỗng thật sự */
      ev.emptyConfirmed = true;
    }
  }
  var v = verdictOf(ev);
  if (v && ev.bodyText && !ev.chatSaw) {
    ev.bodyOnly = true;
    v.note = (v.note ? v.note + '; ' : '') + 'Chính văn lấy từ response body (chat chưa commit)';
  }
  var rec = {
    at: nowMs(),
    req: shortName(ev.requestedModel),
    obs: shortName(v.obs || (ev.observed.length ? ev.observed[0] : '—')),
    src: (function () {
      try {
        if (v.obs) { var k = ev.observed.indexOf(v.obs); return k >= 0 ? (ev.observedSrc[k] || '') : ''; }
      } catch (eSrc) {}
      return (ev.observedSrc && ev.observedSrc[0]) || '';
    })(),
    retired: !!(ev.observed.length && RETIRED_MODEL_RE.test(String(ev.observed[0]))),
    code: v.code,
    conf: v.conf || 'C',
    verifiable: ev.verifiable || 'unknown',
    alias: cfg.alias || '',
    verdict: (VERDICT[v.code] || VERDICT.unknown).label,
    note: v.note,
    status: ev.status,
    ttft: ev.firstMs,
    total: ev.totalMs,
    chars: ev.outputChars,
    think: ev.hasThink ? 1 : (ev.hasReasonField ? 0 : null),
    changed: (meta && meta.changed) || [],
    edits: (meta && meta.edits) || 0,
    added: (meta && meta.added) || 0,
    rid: ev.rid || 0,
    internal: !!ev.internal,
    bodyText: !!ev.bodyText,
    audit: (meta && meta.audit) || null,
    foreign: (meta && meta.foreign) || 0,
    base: (meta && meta.base) || '',
    errModel: ev.errModel || '',
    tooLong: !!ev.tooLong
  };
  /* Kênh echo: Tên không khớp không thể dùng làm bằng chứng "bị tráo", hạ cấp xuống "echo" */
  if (rec.code === 'diff' && rec.verifiable === 'no') {
    rec.code = 'echo';
    rec.verdict = 'Echo';
    rec.note = 'Kênh này sẽ echo lại tên model của bạn, tên không khớp không thể làm bằng chứng';
  }
  try { ledAdd(rec); } catch (eLed) {}
  pushLog(rec);
  render();
  var kind = (VERDICT[v.code] || VERDICT.unknown).color;
  if (v.code === 'diff' || v.code === 'blocked' || v.code === 'gate') {
    banner('🔴 ' + rec.verdict + ': ' + v.note + ' (Request ' + rec.req + ')', kind);
  } else if (v.code === 'thin') {
    banner('🟠 ' + rec.verdict + ': ' + v.note + ' (Request ' + rec.req + ')', kind);
  } else if (v.code === 'empty') {
    banner('⚪ ' + rec.verdict + ': ' + v.note + ' (Request ' + rec.req + ')', kind);
  } else if (v.code === 'same') {
    banner('🟢 Khớp: ' + v.note + ' (' + (rec.ttft ? (rec.ttft / 1000).toFixed(1) + 's ký tự đầu, ' : '') + rec.chars + ' chữ)', kind);
  } else {
    banner('⚪ ' + rec.verdict + ': ' + v.note, kind);
  }
  /* v7.1 Phá giáp: Biện pháp khắc phục sau sự cố được móc vào đây —— mỗi lần thu hồi lượt sinh văn bản đều bắt buộc đi qua điểm này */
  try { jailAfterFinish(ev); } catch (eJail) {}
  /* v7.3: Tự động bật card bằng chứng khi phán đoán là "bị tráo / mất suy nghĩ" (sau 1.6s, đợi việc lấy mẫu response body hoàn tất) */
  try {
    if (cfg.cardAuto && (v.code === 'diff' || v.code === 'thin')) {
      setTimeout(function () {
        try {
          /* v8.0.3: Hộp thoại xác nhận phá giáp / card đã mở được ưu tiên, đừng đè lên giao diện người dùng đang thao tác */
          if (CARD && CARD.open) return;
          if (typeof jailAskPending === 'function' && jailAskPending()) return;
          openCard(rec);
        } catch (eC) {}
      }, 1600);
    }
  } catch (eCard) {}
  return rec;
}

/* ---------------- Phân tích error body (chỉ clone khi >=400) ---------------- */

/* Error body chỉ phân tích "upstream đã phản hồi gì", tuyệt đối không đụng vào sawText.
   v8.29 return toàn bộ hàm đã vô tình khóa chết cả blocked —— khiến phanh "bị chặn không khắc phục" của phá giáp trở thành vô hiệu.
   Hiện tại tách thành hai việc: model chỉ giữ lại để hiển thị (không pushObs, 4xx không phán đoán bị tráo), blocked / vượt độ dài mới là đầu vào phán đoán. */
function salvageError(text, ev) {
  if (typeof text !== 'string' || !text) return;
  var mre = /"(?:modelVersion|model)"\s*:\s*"([^"]{1,120})"/g;
