          this.__ar6plan = plan;
        }
      } catch (e) {}
      return origSend.call(this, body);
    };
    wrappedOpen.__ar6 = true;
    wrappedSend.__ar6 = true;
    wrappedSend.__ar6orig = origSend;
    wrappedOpen.__ar6orig = origOpen;
    X.prototype.open = wrappedOpen;
    X.prototype.send = wrappedSend;
    HOOK_TARGET.xhr = { X: X, origOpen: origOpen, origSend: origSend };
    return true;
  } catch (e) { return false; }
}

function unhookXhr() {
  try {
    XHR_DEAD = true;
    var rec = HOOK_TARGET.xhr;
    if (!rec) return;
    if (rec.X.prototype.open.__ar6) rec.X.prototype.open = rec.origOpen;
    if (rec.X.prototype.send.__ar6) rec.X.prototype.send = rec.origSend;
    HOOK_TARGET.xhr = null;
  } catch (e) {}
}

/* ---------------- Đầu dò ---------------- */

function httpJson(url, opts, timeoutMs) {
  var f = probeFetch || origFetch || HOST.fetch;
  return new Promise(function (resolve, reject) {
    var done = false;
    var timer = setTimeout(function () {
      if (!done) { done = true; reject(new Error('timeout')); }
    }, timeoutMs || 20000);
    try {
      f(url, opts).then(function (res) {
        return res.text().then(function (t) {
          if (done) return;
          done = true; clearTimeout(timer);
          resolve({ status: res.status, text: t });
        });
      }).catch(function (e) {
        if (done) return;
        done = true; clearTimeout(timer);
        reject(e);
      });
    } catch (e) {
      if (!done) { done = true; clearTimeout(timer); reject(e); }
    }
  });
}

function stripApiSuffix(b) {
  return String(b || '').replace(/\/+$/, '')
    .replace(/\/(?:chat\/completions|completions|messages)$/, '')
    .replace(/\/v1beta\d*$/, '')
    .replace(/\/v1$/, '');
}

function openAIUrl(base) {
  var b = String(base || '').replace(/\/chat\/completions\/?$/, '').replace(/\/+$/, '');
  if (!b) return '';
  return b + '/chat/completions';
}

function nativeUrl(base, model) {
  var m = String(model || '').replace(/:streamGenerateContent$/, '').replace(/:generateContent$/, '');
  return stripApiSuffix(base) + '/v1beta/models/' + encodeURIComponent(m) + ':generateContent';
}

var probeBusy = false;

function runNativeProbe() {
  if (probeBusy) return;
  var base = cfg.dualBase || (lastReq && lastReq.base) || '';
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Đầu dò cần gửi trước một lượt, hoặc điền Base vào panel', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Đang gửi request đầu dò native…', 'gray');
  var body = { contents: [{ role: 'user', parts: [{ text: 'ping' }] }], generationConfig: { maxOutputTokens: 8, temperature: 0 } };
  var headers = { 'content-type': 'application/json' };
  if (key) headers['x-goog-api-key'] = key;
  httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify(body) }, 25000)
    .then(function (r) {
      probeBusy = false;
      if (r.status >= 400 && /invalid|unsupported|400|422/.test(String(r.status))) {
        return httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: 'ping' }] }] }) }, 25000)
          .then(function (r2) { reportNative(r2, model); });
      }
      reportNative(r, model);
    })
    .catch(function (e) {
      probeBusy = false;
      banner('🔴 Đầu dò native thất bại: ' + String(e && e.message || e).slice(0, 60), 'bad');
    });
}

function reportNative(r, model) {
  var mv = '';
  try {
    var j = JSON.parse(r.text);
    mv = String((j.modelVersion || j.model || '') || '');
  } catch (e) {}
  var vt = mv ? tierOf(mv) : 0;
  var rt = tierOf(model);
  if (!mv) banner('⚪ Endpoint native trả về ' + r.status + ', không có modelVersion (reverse proxy này có thể không hỗ trợ /v1beta)', 'gray');
  else if (rt > 0 && vt > 0 && vt < rt) banner('🔴 Endpoint native xác nhận bị hạ tier: Request T' + rt + ' → Thực tế ' + mv, 'bad');
  else banner('🟢 Endpoint native trả về modelVersion=' + mv, 'ok');
  render();
}

function runDualProbe() {
  if (probeBusy) return;
  var base = openAIUrl(cfg.dualBase);
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Dấu vân tay kênh đôi cần gửi trước một lượt, hoặc điền Base vào panel', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Đang gửi request dấu vân tay kênh đôi…', 'gray');
  var headers = { 'content-type': 'application/json' };
  if (key) headers['authorization'] = 'Bearer ' + key;
  var ghost = model + '-zzz-not-a-real-model';
  function ask(m) {
    return httpJson(base, {
      method: 'POST', headers: headers,
      body: JSON.stringify({ model: m, messages: [{ role: 'user', content: 'hi' }], max_tokens: 8, stream: false })
    }, 25000).then(function (r) { return r.status; }).catch(function () { return 0; });
  }
  Promise.all([ask(model), ask(ghost)]).then(function (codes) {
    probeBusy = false;
    var real = codes[0], g = codes[1];
    if (!real || real >= 400) banner('🔴 Request tên thật thất bại (HTTP ' + real + '), tuyến kết nối không khả dụng', 'bad');
    else if (!g || g >= 400) banner('🟢 Chế độ nghiêm ngặt: Tên ma bị từ chối (HTTP ' + g + ') ⇒ Gateway điều phối theo tên, trường model đáng tin cậy', 'ok');
    else banner('🟠 Chế độ nới lỏng: Tên ma vẫn trả về 200 ⇒ Gateway không kiểm tra model, trường model trả về không đáng tin cậy', 'warn');
    render();
  });
}

/* ===== 9_card.js ===== */
/* ============================================================================
 * Anti-Route v7.3-test — 9/9 Card bằng chứng (Dành cho người đọc, chụp màn hình, chuyển tiếp)
 *
 * Mục đích: Biến cảm giác "tôi thấy model bị hạ trí thông minh" thành card có thể chụp màn hình trực tiếp.
 * Trái: Những gì tôi đã request
 * Phải: Những gì upstream thông báo đã trả về (nguyên văn response body)
 * Dưới: Bằng chứng hình thái của lượt này (token suy nghĩ / ký tự đầu / số chữ / tốc độ)
 * Đáy: Đoạn trích response nguyên bản, chưa qua xử lý —— Khiến không ai có thể ngụy biện "đây là do script tự bịa ra"
 *
 * Thiết luật: Chỉ đọc không ghi, tuyệt đối không làm nghẽn tiến trình sinh văn bản; toàn bộ DOM đều dùng inline style (không phụ thuộc CSS của trang).
 * ========================================================================== */

var CARD = { open: false, rid: 0 };

var CARD_COLOR = {
 diff: '#f85149',
 thin: '#d29922',
 echo: '#8b949e',
 unknown: '#8b949e',
 same: '#3fb950',
 quota: '#a371f7',
 blocked: '#f85149',
 gate: '#d29922',
 empty: '#8b949e',
 error: '#8b949e'
};

function cardColor(code) {
 return CARD_COLOR[code] || '#8b949e';
}

function cardRate(rec) {
 var n = Number(rec.total) || 0;
 var c = Number(rec.chars) || 0;
 if (!n || !c) return 0;
 return Math.round(c * 1000 / n);
}

/* Dùng ký tự khối để vẽ biểu đồ xu hướng: Không cần canvas, chụp màn hình vẫn rất rõ */
function cardSpark(vals) {
 var chars = ' ▂▃▄▅▆▇█';
 var arr = (vals || []).filter(function (v) { return typeof v === 'number' && isFinite(v); });
 if (!arr.length) return '';
 var min = Math.min.apply(null, arr);
 var max = Math.max.apply(null, arr);
 var span = max - min;
 var out = '';
 for (var i = 0; i < arr.length; i++) {
 var idx = span <= 0 ? 4 : Math.round((arr[i] - min) / span * 7);
 if (idx < 0) idx = 0; if (idx > 7) idx = 7;
 out += chars.charAt(idx);
 }
 return out;
}

function cardPeek(rec) {
 try {
 if (!rec || rec.rid == null) return null;
 return PEEKS[rec.rid] || null;
 } catch (e) { return null; }
}

function cardOneLine(rec) {
 var pk = cardPeek(rec);
 var req = rec.req || '?';
 var obs = rec.obs && rec.obs !== '—' ? rec.obs : '';
 var tail = '';
 if (rec.code === 'diff') {
 tail = obs ? ('Request ' + req + ' → Upstream trả về ' + obs) : ('Request ' + req + ', nhưng bằng chứng không khớp với request');
 } else if (rec.code === 'thin') {
 tail = 'Request ' + req + ', chính văn ' + rec.chars + ' chữ, token suy nghĩ là 0';
 } else if (rec.code === 'echo') {
 tail = 'Request ' + req + ', nhãn trả về khác request, nhưng kênh này không đọc model (echo)';
 } else if (rec.code === 'same') {
 tail = 'Request ' + req + ', kết quả trả về khớp';
 } else {
 tail = 'Request ' + req + ', không thể phán đoán (' + (rec.verdict || '') + ')';
 }
 if (pk && pk.modelVersion) tail += ' ｜ modelVersion: ' + pk.modelVersion;
 return tail;
}

function cardText(rec) {
 if (!rec) return '';
 var d = new Date(Number(rec.at) || Date.now());
 var pad = function (n) { return (n < 10 ? '0' : '') + n; };
 var ts = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' +
 pad(d.getHours()) + ':' + pad(d.getMinutes());
 var pk = cardPeek(rec);
 var lines = [];
 lines.push('【Bằng chứng Anti-Route】' + ts);
 lines.push('Phán đoán: ' + (rec.verdict || '') + ' (Mức bằng chứng ' + (rec.conf || 'C') + ')');
 lines.push(cardOneLine(rec));
 lines.push('Nguyên nhân: ' + (rec.note || ''));
 lines.push('Token suy nghĩ: ' + (pk && pk.thoughts != null ? pk.thoughts : (rec.think ? 'Quan sát thấy' : '0/Không quan sát thấy')) +
 ' ｜ Ký tự đầu: ' + (rec.ttft ? rec.ttft + 'ms' : '—') +
 ' ｜ Chính văn: ' + (rec.chars || 0) + ' chữ ｜ Tốc độ: ' + cardRate(rec) + ' chữ/giây');
 if (pk && (pk.model || pk.modelVersion)) {
 lines.push('Upstream tự khai: model=' + (pk.model || '—') + ' modelVersion=' + (pk.modelVersion || '—'));
 }
 if (pk && pk.raw) lines.push('Đoạn trích gốc: ' + pk.raw.slice(0, 200));
 lines.push('Kênh: ' + (rec.base || '—'));
 lines.push('Phiên bản: Ánh Sáng Luke V' + VERSION + ' (Lõi Anti-Route 8.31)');
 return lines.join('\n');
}

function cardCopy(rec) {
 var txt = cardText(rec);
 try {
 if (HOST.navigator && HOST.navigator.clipboard && HOST.navigator.clipboard.writeText) {
 HOST.navigator.clipboard.writeText(txt).then(function () {
 banner('Đã sao chép văn bản bằng chứng, có thể gửi trực tiếp', 'ok');
 })['catch'](function () { cardCopyFallback(txt); });
 return;
 }
 } catch (e) {}
 cardCopyFallback(txt);
}

function cardCopyFallback(txt) {
 try {
 var ta = DOC.createElement('textarea');
 ta.value = txt;
 ta.setAttribute('style', 'position:fixed;left:-9999px;top:0;opacity:0');
 DOC.body.appendChild(ta);
 ta.select();
 DOC.execCommand('copy');
 DOC.body.removeChild(ta);
 banner('Đã sao chép văn bản bằng chứng', 'ok');
 } catch (e) {
 banner('Sao chép thất bại, vui lòng nhấn giữ card để chụp màn hình', 'warn');
 }
}

function cardBars(vals, color) {
 var arr = (vals || []).filter(function (v) { return typeof v === 'number' && isFinite(v); });
 if (!arr.length) return '';
 var max = Math.max.apply(null, arr);
 var h = '';
 for (var i = 0; i < arr.length; i++) {
 var pct = max > 0 ? Math.max(6, Math.round(arr[i] / max * 100)) : 6;
 var last = i === arr.length - 1;
 h += '<div style="flex:1;display:flex;align-items:flex-end;height:34px">' +
 '<div style="width:100%;height:' + pct + '%;background:' + (last ? color : '#1f6feb') +
 ';border-radius:2px"></div></div>';
 }
 return '<div style="display:flex;gap:2px;align-items:flex-end">' + h + '</div>';
}

function cardEngineHTML(rec) {
 var pk = cardPeek(rec);
 var col = cardColor(rec.code);
 var obs = (rec.obs && rec.obs !== '—') ? rec.obs : ' (Chưa trả về)';
