 h += '<div id="ar6-card" style="position:fixed;inset:0;z-index:2147483600;background:rgba(1,4,9,.86);display:flex;align-items:center;justify-content:center;padding:12px;font-family:system-ui,-apple-system,\'Segoe UI\',sans-serif">';
 h += '<div style="width:402px;max-width:calc(100vw - 20px);max-height:92vh;overflow-x:hidden;overflow:auto;background:#0d1117;color:#e6edf3;border:1px solid #30363d;border-radius:16px;box-shadow:0 12px 48px rgba(0,0,0,.6)">';
 h += cardTabBar('engine');

 /* Thanh kết luận trên cùng */
