 h += '<div style="font-size:20px;font-weight:700;color:' + col + ';line-height:1.3">' +
 esc(rec.verdict || 'Chưa rõ') + '</div>';
 h += '<div style="font-size:12px;color:#8b949e;margin-top:6px">Mức bằng chứng <b style="color:#e6edf3">' +
