/* ---------------- Báo cáo (Dành cho người đọc) ---------------- */

function cardTabBar(tab) {
 var on = 'background:#1f6feb;border:1px solid #1f6feb;color:#fff';
 var off = 'background:#161b22;border:1px solid #30363d;color:#c9d1d9';
 var h = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:10px 16px 0">';
 h += '<button data-ar6-card="tab" data-tab="human" style="min-height:34px;border-radius:8px;font-size:13px;' + (tab === 'engine' ? off : on) + '">Báo cáo</button>';
 h += '<button data-ar6-card="tab" data-tab="engine" style="min-height:34px;border-radius:8px;font-size:13px;' + (tab === 'engine' ? on : off) + '">Tra cứu</button>';
 return h + '</div>';
}

function cardHumanVerdict(rec) {
 var c = rec.code;
 if (c === 'diff') return { t: 'Lượt này đã bị tráo model', s: 'Model được request và model trả về không phải là một. Đây là bằng chứng đanh thép nhất, có thể chụp màn hình trực tiếp.', c: '#f85149' };
 if (c === 'thin') return { t: 'Model không đổi, nhưng nó không hề suy nghĩ', s: 'Phản hồi vẫn còn, nhưng không có bất kỳ tiến trình suy nghĩ nào —— Thường thấy khi mức suy nghĩ bị ép xuống mức thấp nhất.', c: '#d29922' };
 if (c === 'same') return { t: 'Lượt này bình thường', s: 'Model trả về khớp với request, chính văn cũng đầy đủ.', c: '#3fb950' };
 if (c === 'echo') return { t: 'Kênh chỉ đang echo lại tên model', s: 'Nó không đọc tên model, vì vậy việc "tên khớp nhau" không thể dùng làm bằng chứng.', c: '#8b949e' };
 if (c === 'quota') return { t: 'Hạn ngạch đã cạn', s: 'Đây là giới hạn lưu lượng, không phải âm thầm tráo model.', c: '#a371f7' };
 if (c === 'blocked') return { t: 'Bị upstream chặn', s: 'Chặn an toàn nội dung, không phải hạ cấp model.', c: '#f85149' };
 if (c === 'empty') {
 if (/xác nhận phản hồi rỗng|确认空回/.test(String(rec.note || ''))) {
 return { t: 'Lượt này thực sự không có chính văn', s: 'Cả chat và response body đều không có chữ —— Phản hồi rỗng thật sự, gửi lại lần nữa thường sẽ bình thường.', c: '#8b949e' };
 }
 return { t: 'Chưa đọc được chính văn (không phải lỗi model)', s: 'Lần này chưa lấy được chữ từ response body (lấy mẫu nhánh phụ có thể đang tắt), tạm thời đừng coi là bị hạ cấp.', c: '#8b949e' };
 }
 if (c === 'error') return { t: 'Request thất bại', s: 'Lỗi HTTP, hãy kiểm tra lại kênh và khóa API.', c: '#f85149' };
