 ] },
 { h: 'Khu kiểm tra', l: [
 '"Đầu dò native": Làm gì: Hỏi thẳng upstream "ngươi là ai", nếu lấy được sẽ hiển thị model thực tế.',
 ' Khi nào không nên nhấn: Khi kênh không có interface native, nó sẽ chỉ trả về 404.',
 '"Kênh đôi": Làm gì: Gửi một lần tên thật, một lần tên giả. Tên giả cũng 200 ⇒ Kênh không đọc tên model.',
 '"Tự kiểm 20 mục": Làm gì: Mở rộng từng kết quả kiểm tra tích hợp, dùng để báo lỗi.',
 ' Khi nào nhấn: Vừa cài xong, nhấn cái khác không phản hồi, số liệu đứng yên, hoặc sau khi đổi thiết bị.',
 '"Kiểm tra kênh": Làm gì: Tương tự kênh đôi, nhưng kết quả sẽ được ghi vào hồ sơ kênh để dùng cho các phán đoán phía sau.',
 ' Khi nào nhấn: Việc đầu tiên nên làm sau khi cài đặt.',
 '"Quét alias": Làm gì: Thử 5 cách viết phổ biến (Tên gốc / google/ / models/ / pg- / -high), xem cách nào được chấp nhận.',
 '"Kiểm tra tier": Làm gì: Gửi cùng một câu hai lần (yêu cầu suy nghĩ cao / yêu cầu thấp nhất), so sánh thời gian tiêu tốn và lượng suy nghĩ.',
 ' Nhìn vào đâu: Khác biệt rõ rệt = Kênh tôn trọng tier; Gần như giống nhau = Tier bị bỏ qua, nên đổi kênh.',
 '"Báo cáo giảm dung lượng": Làm gì: Thống kê các đoạn trùng lặp và số lượng ký tự trong request, chỉ ra chỗ nào có thể lược bớt. Chỉ báo cáo, không sửa preset.',
 '"Sàng lọc danh tính": Làm gì: Chấm điểm tái hiện danh sách từ, phán đoán phản hồi hiện tại có phải model bạn nghĩ hay không.'
 ] },
 { h: 'Bản ghi và ô nhập liệu', l: [
 '"Báo cáo", "Tra cứu": Hai mặt của cùng một lượt —— Dành cho người xem, dành cho kỹ sư xem.',
 '"Hướng dẫn": Chính là trang này, mở bất cứ lúc nào, dùng được offline.',
 '"Request gần nhất": Trải rộng request body thực tế đã gửi ở lượt trước, dùng để đối chiếu xem "rốt cuộc có sửa hay không".',
 '"Base / Key": Điền địa chỉ reverse proxy (vd: https://x/v1) và key, dùng cho đầu dò và kiểm tra kênh.',
 ' Điền xong nhấn "Lưu", lần sau không cần điền lại; không điền cũng không ảnh hưởng chức năng chính.'
 ] },
 { h: 'Chỉ số chân trang', l: [
 '"Nút n/1": Nút bấm lối vào duy nhất đã được gắn hay chưa. 0/1 = Chưa gắn được (không có môi trường Tavern Helper hoặc phiên bản quá cũ), panel vẫn dùng bình thường.',
 '"Bị tráo / Mất suy nghĩ / Khớp / Chưa định": Đếm lịch sử cục bộ máy này, tối đa 30 bản ghi.',
 '"Khóa n/4": Số lượng công tắc "cho phép đổi model" đã bị tắt bỏ.',
 '"Shield n": Phát hiện bạn đã cài đặt khiên bảo vệ khác, hai bên sẽ triệt tiêu lẫn nhau, khuyến nghị chỉ giữ lại một cái.'
 ] }
 ],

 /* ---------------- Tầng tự sự ---------------- */
 narr: [
 { h: 'Giải quyết điều gì', l: [
 'Cả hai đều là "ràng buộc văn phong", không phải tính năng bảo mật:',
 'Chống toàn tri —— Model không được biết những gì bạn nghĩ trong lòng, tình tiết chưa xảy ra, chuyện đang diễn ra ở nơi khác.',
 'Bỏ nịnh —— Nhân vật không nên suốt ngày xoay quanh bạn, thế giới không vì bạn mà tồn tại.',
 'Chúng chỉ sửa bản sao request gửi đi lần này, nhật ký chat và preset không động một chữ.'
 ] },
 { h: 'Chống toàn tri: Ba mức', kv: [
 ['Tắt', 'Không thêm gì (mặc định)'],
 ['Nhẹ', 'Khoảng 60 chữ. Một câu: Chỉ viết những gì thấy và nghe được trong cảnh này, không ai biết chuyện bạn chưa nói ra miệng.'],
 ['Mạnh', 'Khoảng 330 chữ. 7 thiết luật + một câu tự kiểm tra khi đặt bút: Mỗi câu đều phải trả lời được "hắn làm sao biết được điều đó".']
 ] },
 { h: 'Bỏ nịnh: Ba mức', kv: [
 ['Tắt', 'Không thêm gì (mặc định)'],
 ['Nhẹ', 'Khoảng 40 chữ. Một câu: Thế giới không xoay quanh bạn, NPC có lịch trình riêng.'],
 ['Mạnh', 'Khoảng 180 chữ. 5 âm điệu nền tảng: NPC có quỹ đạo riêng · Bạn sẽ bị phớt lờ/hiểu lầm/từ chối · Người khác không hiểu bạn ngay lập tức · Không có kết cục tất thắng.']
 ] },
 { h: 'Điểm tôi đã sửa so với bản thảo gốc, cần làm rõ', l: [
 'Trong bản thảo gốc của Bỏ nịnh có câu "Cách duy nhất để qua ải là user chết", tôi đã xóa.',
 'Lý do: Nó xúi giục model viết ra từ chối / kết cục chết chóc, mà "từ chối" trong phá giáp sẽ bị phán là rỗng, từ đó kích hoạt tự động viết tiếp —— chẳng khác nào cài lại cái hố "không ai nói gì nó cũng tự request model" vừa fix ở bản 8.29.',
 'Thay bằng: "Không có kết cục tất thắng. Đi sai đường, bị từ chối, bị thương, thất bại đều được phép xảy ra". Giữ lại cốt lõi (thế giới không chiều chuộng bạn), loại bỏ lối thoát khiến hệ thống sập hố.',
 'Ngoài ra mục "tự kiểm tra từng câu" của Chống toàn tri trong bản thảo gốc đã được nén thành một câu: Trong phản hồi dài, model sẽ nhảy cóc qua việc kiểm tra từng câu, giữ lại chỉ tổ tốn token.'
 ] },
 { h: 'Chi phí và vị trí inject', l: [
 'Mức nhẹ tốn khoảng +120 tok/lượt, hai mức mạnh tốn khoảng +470 (panel sẽ hiển thị số đo thực tế).',
 'Vị trí inject cố định: Sau vi nhiễu, trước phá giáp. Đuôi "viết trực tiếp" của phá giáp bắt buộc phải nằm ở cuối cùng, đó là vị trí có cường độ cao nhất.',
 'Tính lũy đẳng: Cùng một request inject hai lần, kết quả trùng từng chữ, không bị chồng chất dài thêm.',
 'Tắt đi sẽ bóc sạch khối đã để lại lần trước, không lưu tàn dư trong request.'
 ] },
 { h: 'Khi nào không nên bật', l: [
 'Viết thường nhật, hài kịch nhẹ nhàng, các cảnh cần nhân vật "hiểu ý bạn ngay" —— Bật chống toàn tri sẽ làm nhân vật trở nên cùn mòn/chậm hiểu.',
 'Khi làm thí nghiệm đối chứng A/B thì tắt cả hai, kẻo thêm biến số, khó đưa ra kết luận rõ ràng.',
 'Context dài nhạy cảm với token: Hai mức mạnh tăng thêm 470 token mỗi lượt, vài chục lượt là một khoản tiền đáng kể.',
 'Muốn xem rốt cuộc nó chèn cái gì: Trong console gõ __AR6__.narrBody(), hoặc __AR6__.narrTokens() để xem số token.'
 ] }
 ],

 /* ---------------- Chi tiết phá giáp ---------------- */
 jail: [
 { h: 'Rốt cuộc nó đang làm gì', l: [
 'Mỗi lượt kết thúc, nó kiểm tra chính văn lần này:',
 ' Có rỗng hay không;',
 ' Đuôi có dừng ở dấu phẩy, dấu ngắt câu, hai chấm, gạch ngang;',
 ' Có dừng ở dấu mở ngoặc kép, mở ngoặc đơn;',
 ' Khối code đã đóng chưa;',
 ' Bài dài (>800 chữ) trong 120 chữ cuối cùng có dấu chấm câu hay không.',
 'Trúng bất kỳ điều nào, nó sẽ coi như "có vẻ đã bị cắt cụt", và hỏi bạn có muốn khắc phục không.'
 ] },
 { h: 'Sự khác biệt giữa ba chế độ', kv: [
 ['Tắt', 'Hoàn toàn không kiểm tra, không làm gì cả (mặc định)'],
 ['Bình thường', 'Chỉ kiểm tra sau sự việc: Phát hiện phản hồi rỗng/cắt cụt → Hỏi bạn → Bạn nhấn mới khắc phục. Không sửa request bạn gửi đi'],
 ['Siêu cấp', 'Bình thường + Sửa request: Bổ sung chỉ thị "xuất trực tiếp chính văn", bảo đảm giới hạn output tối thiểu 2048, nới lỏng thiết lập an toàn. Trước khi bật sẽ hiện một popup xác nhận rủi ro']
 ] },
 { h: 'Ba nút trong popup', l: [
 '"Khắc phục 1 lần": Thực sự gửi một request viết tiếp (/continue), nối tiếp câu chuyện.',
 '"Không cần": Lần này không khắc phục, đóng popup. Bản ghi vẫn giữ nguyên như cũ.',
 '"Phiên này đừng hỏi lại": Về sau cứ đủ điều kiện là tự động khắc phục, không hiện popup nữa (= Tắt xác nhận).',
 'Hối hận: Tại khu phá giáp nhấn vào "Hỏi trước khi khắc phục" một cái là mở lại xác nhận.'
 ] },
 { h: 'Vì sao mặc định "Hỏi bạn trước"', l: [
 'Tự động viết tiếp từng nối một câu thành ba đoạn, người dùng lại tưởng model bị điên.',
 'Hiện tại mặc định bạn nhấn một lần nó mới khắc phục một lần —— thà tốn thêm một cú click, còn hơn tự dưng mọc thêm một đoạn kỳ quặc.',
 'Nếu bạn thực sự muốn tự động: Trong popup nhấn nút thứ ba, hoặc tắt "Hỏi trước khi khắc phục" ở khu phá giáp.'
 ] },
 { h: 'Phanh hãm (Chống lặp vô tận)', l: [
 'Cùng một lượt tối đa khắc phục 1 lần (trước đây ghi 2 lần, code thực tế là 1 lần).',
 'Giữa hai lần cách nhau ít nhất 2.5 giây.',
 'Bản thân vừa khắc phục trong vòng 90 giây thì sẽ không tự động khắc phục nữa —— Đây là phanh chống tự kích thích.',
 '20 giây không có lượt viết tiếp mới sẽ reset bộ đếm.',
 'Khi bị upstream chặn (chính sách an toàn) sẽ không khắc phục, chỉ cảnh báo.'
 ] },
 { h: 'Giữa tự sự và phá giáp ai chốt hạ', l: [
 'Tự sự được inject trước phá giáp, do đó câu "viết trực tiếp" của phá giáp luôn ở dòng cuối cùng, hiệu lực cao nhất.',
 'Bật cả hai không đánh nhau: Một bên ràng buộc cách viết, một bên yêu cầu viết tiếp.',
 'Thứ tự nếu đảo ngược, model sẽ đọc câu "viết trực tiếp" như một phần của chính văn rồi nhắc lại —— cho nên thứ tự này được khóa cứng.'
 ] },
 { h: 'Vì sao Siêu cấp phải hiện popup', l: [
 'Vì Siêu cấp sẽ sửa request bạn gửi đi. Body request thay đổi thì độ tin cậy của các phán đoán như "tên model có khớp không" sẽ giảm —— kết luận chống route sẽ không sạch bằng chế độ Bình thường.',
 'Nó cũng có thể khiến kênh coi request lần này là bất thường, dẫn đến dễ bị chặn hơn.',
 'Do đó nó mặc định tắt, mỗi lần bật đều yêu cầu bạn xác nhận thủ công: Đây không phải thủ tục hình thức, mà thực sự có cái giá phải trả.'
 ] },
 { h: 'Nó sửa được gì và không sửa được gì', l: [
 'Sửa được: Bị cắt cụt (dừng giữa chừng nửa câu), phản hồi rỗng (lần này model không nhả chữ), chính văn bị upstream nuốt chửng.',
 'Không sửa được: Tầng an toàn từ chối. Nó nhận ra được và sẽ báo thẳng "câu này đừng khắc phục" —— lệnh viết tiếp không đổi được phán đoán của bộ lọc, đổi kênh hoặc đổi model mới có tác dụng.',
 'Khắc phục một lần là "cho thêm một cơ hội", không phải "nói thay bạn". Khắc phục xong mà vẫn không được thì chứng tỏ vấn đề này việc viết tiếp không giải quyết nổi.'
 ] },
 { h: 'Khi nào nên bật, nên bật chế độ nào', kv: [
 ['Thỉnh thoảng rỗng, còn lại bình thường', 'An toàn (Đủ dùng, và không đổi request)'],
 ['Thường xuyên viết dở đứt ở dấu phẩy', 'Siêu cấp (Bổ sung chỉ thị output + bảo đảm độ dài)'],
 ['Ngắn đến mức vô lý, một câu là xong', 'Siêu cấp, đồng thời xem Kiểm tra tier'],
 ['Kênh vốn dĩ bình thường', 'Tắt (Tiết kiệm token, bớt đi một biến số)'],
 ['Nội dung dễ bị kiểm duyệt chặn', 'Tắt (Siêu cấp nới lỏng thiết lập an toàn, có thể dễ bị chặn hơn)']
 ] }
 ],

 /* ---------------- Đọc kết quả thế nào ---------------- */
 read: [
 { h: 'Bị tráo (Đỏ)', l: [
 'Model trả về và model được request không phải là một (bao gồm cả khác họ, ví dụ request Gemini trả về DeepSeek).',
 'Đây là bằng chứng đanh thép nhất, có thể chụp màn hình trực tiếp.',
 'Việc nên làm: Nhấn "Tra cứu" lấy nguyên văn response → Đổi kênh, hoặc đổi alias rồi thử lại.'
 ] },
 { h: 'Mất suy nghĩ (Vàng)', l: [
 'Tên model không đổi, nhưng trong response body lượt này token suy nghĩ là 0.',
 'Thường thấy khi tier suy nghĩ bị ép xuống mức thấp nhất, hoặc kênh căn bản không bật suy nghĩ.',
 'Lưu ý: Không nhìn thấy ≠ Không có —— Kênh có thể không truyền chuỗi suy nghĩ về.',
 'Việc nên làm: Nhấn "Kiểm tra tier"; nếu báo "Bị bỏ qua" thì đổi kênh.'
 ] },
 { h: 'Khớp (Xanh lá)', l: [
 'Tên trùng khớp, chính văn cũng đầy đủ.',
 'Nhưng nếu kênh thuộc diện echo tên ("Kiểm tra kênh" trả về 200), dòng này không tính, chỉ là nó chép lại chữ của bạn mà thôi.',
 'Việc nên làm: Trước tiên xác nhận kênh có nhận diện tên hay không.'
 ] },
 { h: 'Chỉ là echo (Xám)', l: [
 'Tên khác nhau, nhưng kênh căn bản không đọc tên, vì vậy sai lệch không thể làm bằng chứng.',
 'Trường hợp này chỉ có thể nhìn vào hình thái: Số chữ, thời lượng, suy nghĩ.'
 ] },
 { h: 'Không thể phán đoán (Xám)', l: [
 'Chưa lấy được thông tin có thể phán đoán —— Không phải "không có chuyện gì", mà là "chưa thấy được".',
 'Thường thấy khi: Kênh không trả về tên model; Request nội bộ (database/điền biểu mẫu) không có sản phẩm chat.',
 'Việc nên làm: Trước tiên "Kiểm tra kênh"; nếu vẫn chưa rõ thì chỉ có thể phán đoán dựa vào hình thái.'
 ] },
 { h: 'Không có chính văn (Xám)', l: [
 'Lượt này không có chính văn, chia làm hai loại:',
 ' Xác nhận phản hồi rỗng: Cả response body và chat đều không có chữ → Gửi lại một lần thường sẽ bình thường;',
 ' Chưa đọc được: Lấy mẫu nhánh phụ đang tắt hoặc chưa lấy được → Tạm thời đừng coi là bị hạ cấp.'
 ] },
 { h: 'Mức bằng chứng A / B / C', l: [
 'A: Response body tự khai, và khác họ hoặc kênh có thể xác thực —— Đanh thép nhất.',
 'B: Response body tự khai, nhưng kênh không thể xác thực (có thể là echo).',
 'C: Chỉ có nhãn trong nhật ký chat, hoặc không có gì cả.',
 'Mức thấp không có nghĩa là an toàn, chỉ thể hiện "bằng chứng này chưa đủ đanh thép".'
 ] },
 { h: 'Bốn con số và hai dòng chữ nhỏ', l: [
 'Bị tráo / Mất suy nghĩ / Khớp / Chưa định: Đếm lịch sử máy này (tối đa 30 bản ghi).',
 'Tỷ lệ route: Chỉ tính các lượt có bằng chứng mức A/B, kèm khoảng tin cậy 95%; khi mẫu quá ít sẽ ghi "Không đủ mẫu".',
 '"Khóa n/4": Số lượng công tắc "cho phép đổi model" đã bị tắt bỏ.',
 '"Shield n": Phát hiện bạn đã cài đặt khiên bảo vệ khác, hai bên sẽ triệt tiêu lẫn nhau, khuyến nghị chỉ giữ lại một cái.'
 ] }
 ],

 /* ---------------- Câu hỏi thường gặp ---------------- */
 faq: [
 { q: 'Cài hai gói thì làm thế nào? Gói cũ có cần xóa không?', a: [
 'Chỉ giữ lại một gói. Cài cả hai sẽ tranh chấp cùng một fetch, biểu hiện là "cả hai đều như chưa cài".',
 'Gói cũ (Anti-Route 8.x) vui lòng tắt hoặc xóa trong Tavern Helper trước, sau đó mới import Ánh Sáng Luke V0.1.',
 'Trước khi xóa không cần backup cấu hình: Key lưu trữ không đổi, các cài đặt sẽ được kế thừa sang.'
 ] },
 { q: 'Đổi tên thành Ánh Sáng Luke, cấu hình cũ của tôi có còn không?', a: [
