function ico(name) {
  var d = AR6_ICONS[name] || AR6_ICONS.dot;
  return '<svg class="ar6-i" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" style="width:14px;height:14px;flex:0 0 14px" aria-hidden="true"><path d="' + d + '"/></svg>';
}

function icoOf(label) {
  var s = String(label || '');
  if (s.indexOf('防全知') >= 0 || s.indexOf('Chống toàn tri') >= 0) return 'compass';
  if (s.indexOf('去媚') >= 0 || s.indexOf('Bỏ nịnh') >= 0) return 'orbit';
  if (s.indexOf('对照') >= 0 || s.indexOf('A/B') >= 0 || s.indexOf('Đối chiếu') >= 0) return 'scale';
  if (s.indexOf('导出') >= 0 || s.indexOf('Xuất') >= 0) return 'out';
  if (s.indexOf('账本') >= 0 || s.indexOf('Sổ cái') >= 0) return 'ledger';
  if (s.indexOf('渠道卡') >= 0 || s.indexOf('Thẻ kênh') >= 0) return 'tag';
  if (s.indexOf('安全') >= 0 || s.indexOf('An toàn') >= 0) return 'shield-off';
  if (s.indexOf('自检') >= 0 || s.indexOf('Tự kiểm tra') >= 0) return 'stethoscope';
  if (s.indexOf('破甲') >= 0 || s.indexOf('Phá giáp') >= 0) return 'bandage';
  if (s.indexOf('补一次') >= 0 || s.indexOf('Bù một lần') >= 0) return 'bandage';
  if (s.indexOf('确认') >= 0 || s.indexOf('Xác nhận') >= 0) return 'bell';
  if (s.indexOf('思考') >= 0 || s.indexOf('Suy nghĩ') >= 0) return 'brain';
  if (s.indexOf('微扰') >= 0 || s.indexOf('混淆') >= 0 || s.indexOf('Vi nhiễu') >= 0 || s.indexOf('Xáo trộn') >= 0) return 'feather';
  if (s.indexOf('钉') >= 0 || s.indexOf('Ghim') >= 0) return 'pin';
  if (s.indexOf('观察') >= 0 || s.indexOf('Quan sát') >= 0) return 'eye';
  if (s.indexOf('原生') >= 0 || s.indexOf('探针') >= 0 || s.indexOf('Native') >= 0 || s.indexOf('Probe') >= 0) return 'microscope';
  if (s.indexOf('双通道') >= 0 || s.indexOf('Kênh đôi') >= 0) return 'flask';
  if (s.indexOf('验渠道') >= 0 || s.indexOf('Kiểm tra kênh') >= 0) return 'telescope';
  if (s.indexOf('别名') >= 0 || s.indexOf('Alias') >= 0) return 'tag';
  if (s.indexOf('档位') >= 0 || s.indexOf('Cấp độ') >= 0) return 'gauge';
  if (s.indexOf('身份') >= 0 || s.indexOf('Danh tính') >= 0) return 'target';
  if (s.indexOf('报告') >= 0 || s.indexOf('Báo cáo') >= 0) return 'file';
  if (s.indexOf('排查') >= 0 || s.indexOf('Rà soát') >= 0) return 'wrench';
  if (s.indexOf('说明') >= 0 || s.indexOf('Hướng dẫn') >= 0) return 'book';
  if (s.indexOf('清空') >= 0 || s.indexOf('Xóa sạch') >= 0) return 'trash';
  if (s.indexOf('外观') >= 0 || s.indexOf('Giao diện') >= 0) return 'palette';
  if (s.indexOf('悬浮') >= 0 || s.indexOf('找回') >= 0 || s.indexOf('Nổi') >= 0 || s.indexOf('Tìm lại') >= 0) return 'ghost';
  if (s.indexOf('请求') >= 0 || s.indexOf('Yêu cầu') >= 0) return 'file';
  return 'dot';
}

/* Bỏ emoji ở đầu, chỉ dùng để hiển thị; data-ar6 vẫn dùng chuỗi gốc, việc dispatch không bị ảnh hưởng */
function chipText(label) {
  var s = String(label || '');
  var i = 0;
  while (i < s.length) {
    var c = s.charCodeAt(i);
    if ((c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 0x4e00 && c <= 0x9fff)) break;
    i++;
  }
  return s.slice(i) || s;
}

function chip(label, on) {
  return '<button class="ar6-b' + (on ? ' on' : '') + '" data-ar6="' + esc(String(label)) + '">' +
    ico(icoOf(label)) + '<span>' + esc(chipText(label)) + '</span></button>';
}

function btnIco(act, name, text, cls) {
  return '<button class="ar6-b' + (cls ? ' ' + cls : '') + '" data-ar6="' + act + '">' +
    ico(name) + '<span>' + esc(text) + '</span></button>';
}

