var OUTSIDE_BOUND = false;

/* Nhấp vào khoảng trống ngoài panel: Có overlay thì đóng overlay, không có overlay thì thu gọn panel */
function bindOutsideDismiss() {
  if (OUTSIDE_BOUND) return;
  if (!DOC || typeof DOC.addEventListener !== 'function') return;
  OUTSIDE_BOUND = true;
  DOC.addEventListener('pointerdown', function (ev) {
    try {
      if (DISPOSED) return;
      var t = ev && ev.target;
      if (t && t.closest && t.closest('#ar6-bn2')) return;
      if (CARD && CARD.open) {
        if (t && t.id === 'ar6-card') closeCard();   /* Chỉ đóng khi nhấp vào chính lớp mask, nhấp bên trong card thì không đóng */
        return;
      }
      if (minimized) return;
      var el = DOC.getElementById(ROOT_ID);
      if (!el) return;
      if (t && el.contains && el.contains(t)) return;
      if (t && t.closest && t.closest('#' + ROOT_ID)) return;
      minimized = true;
      syncMin();
      render();
    } catch (e) {}
  }, true);
}

function fitPanel(el) {
  try {
    if (!el || minimized) return;
    var vv = (HOST.visualViewport && HOST.visualViewport.height) || HOST.innerHeight || 720;
    var mode = uiMode();
    var maxH = Math.round(vv * (mode === 'mobile' ? 0.72 : 0.78));
    if (mode !== 'mobile') maxH = Math.min(maxH, 820);
    /* v8.30: Chừa không gian cho nút bấm cố định dưới đáy (#send_form), tránh cạnh dưới panel đè lên khung nhập liệu */
    if (maxH > vv - 96) maxH = Math.round(vv - 96);
    if (maxH < 240) maxH = 240;
    el.style.height = maxH + 'px';
    el.style.maxHeight = maxH + 'px';
    el.style.display = 'flex';
    el.style.flexDirection = 'column';
    el.style.overflow = 'hidden';
    /* v8.30: Sau khi cố định chiều cao, bắt buộc phải kẹp top trở lại vùng hiển thị.
       Bản 8.28 chỉ gán chiều cao mà không kiểm tra vị trí, trên điện thoại hễ top lệch xuống dưới là cạnh đáy rơi ra ngoài màn hình,
       thứ người dùng thấy chính là "chỉ có nửa trên" — đây chính là một trong những nguyên nhân gốc rễ của phản hồi lần này. */
    var top = parseFloat(el.style.top);
    if (!isFinite(top)) top = el.getBoundingClientRect().top;
    if (isFinite(top)) {
      var limit = vv - maxH - 6;
      if (limit < 6) limit = 6;
      var nt = top;
      if (top > limit) nt = limit;
      else if (top < 6) nt = 6;
      if (nt !== top) { el.style.top = Math.round(nt) + 'px'; el.style.bottom = 'auto'; }
      if (typeof cfg === 'object' && cfg) {
        if (!(Math.abs((cfg.my == null ? nt : cfg.my) - nt) <= 2)) { cfg.my = Math.round(nt); try { saveCfg(); } catch (eS) {} }
        else cfg.my = Math.round(nt);
      }
    }
  } catch (e) {}
}

