    html += '<div class="ar6-foot"><span>Hook <b class="' + (hooked ? 'ok' : 'bad') + '">' + (hooked ? 'Có' : 'Không') + '</b></span>' +
      '<span>XHR <b class="' + (HOOK_TARGET.xhr ? 'ok' : 'gray') + '">' + (HOOK_TARGET.xhr ? 'Bật' : 'Tắt') + '</b></span>' +
      '<span class="ar6-sp"></span><span>Host ' + ((HOST === HOST.top) ? 'top' : 'iframe') + '</span>' +
      '<span>Style <b class="' + (DOC.getElementById(STYLE_ID) ? 'ok' : 'bad') + '">' + (DOC.getElementById(STYLE_ID) ? '✓' : '✗') + '</b></span>' +
      '<span>Click <b class="mono">' + clickCount + '</b></span>' +
      '<span>Nút <b class="' + (btnReady() ? 'ok' : (BTN_OK ? 'warn' : 'bad')) + '">' + btnSummary() + '</b></span>' +
      '<span>Khả nghiệm <b class="' + (verifiableCode() === 'yes' ? 'ok' : (verifiableCode() === 'no' ? 'bad' : 'gray')) + '">' + verifiableLabel() + '</b></span>' +
      (cfg.alias ? '<span>Alias <b class="mono">' + esc(cfg.alias) + '</b></span>' : '') +
      '<span>Ghim <b class="' + auditColor() + '">' + auditLabel() + '</b></span>' +
      (foreignCount() >= 2 ? '<span>Khiên <b class="warn">' + foreignCount() + '</b></span>' : '') +
      '<span>' + esc(idFooter()) + '</span>' +
      '<span>Giữ lại ' + readLog().length + '/' + (cfg.keep || MAX_LOG) + '</span></div>';

    html += '</div></div>';
  }

  var prevFocus = null;
  try { prevFocus = DOC.activeElement; } catch (eF0) {}
  var wasMin = (LAST_MIN === true);
  LAST_MIN = minimized;
  var scTop = 0;
  try { var oldBody = r.querySelector('.ar6-body'); if (oldBody) scTop = oldBody.scrollTop || 0; } catch (eSc) {}
  r.innerHTML = html;
  try {
    if (scTop > 0) { var nb = r.querySelector('.ar6-body'); if (nb) nb.scrollTop = scTop; }
  } catch (eSc2) {}
  /* v8.0.3: Phục hồi focus (vẽ lại sẽ thay thế DOM) */
  try {
    if (prevFocus && prevFocus.getAttribute) {
      var fkey = prevFocus.getAttribute('data-ar6');
      if (fkey) {
        var back = r.querySelector('[data-ar6="' + fkey.replace(/"/g, '') + '"]');
        if (back && back.focus) back.focus();
