  } catch (eFr) {}
  /* Dự phòng định vị inline: Một số container/CSP có thể khiến style mất hiệu lực, tại đây ghi lại thuộc tính then chốt */
  var panelEl = r.firstChild;
  /* v8.0.3: Chỉ phát animation xuất hiện một lần khi chuyển "từ thu gọn sang mở rộng" */
  try { if (panelEl && !minimized && wasMin && panelEl.classList) panelEl.classList.add('ar6-anim'); } catch (eAn) {}
  try {
    if (panelEl && panelEl.className && panelEl.className.indexOf('ar6-pill') >= 0) {
      panelEl.style.cursor = 'pointer';
    }
  } catch (e) {}

  if (!minimized) { try { fitPanel(r); } catch (eFP) {} }
  if (!minimized && panelEl) { try { installRootDrag(r, 'panel'); } catch (eRD) {} }
  if (minimized) {
    try { if (!PAD_OPEN) bindFloatGestures(r); installRootDrag(r, PAD_OPEN ? 'pad' : 'ball'); floatApplyPosition(r, true); } catch (eF) {}
  } else {
    try { installFloatSettings(r); } catch (eFS) {}
  }

  if (!r.__ar6bound) {
    r.__ar6bound = true;
    /* Chỉ gắn trực tiếp từng phần tử (hàm bindDirect bên dưới), tránh event delegation và gắn trực tiếp cùng kích hoạt một cử chỉ 2 lần */
    r.addEventListener('input', onPanelInput);
    r.addEventListener('change', onPanelChange);
  }
  bindDirect(r);
  setTimeout(verifyVisible, 400);
  return true;
}

/* Gắn trực tiếp từng nút bấm: Một số tiện ích mở rộng có thể chặn bubbling hoặc nuốt mất click, khiến delegation bị vô hiệu */
function bindDirect(r) {
  try {
    var nodes = r.querySelectorAll('[data-ar6]');
    for (var i = 0; i < nodes.length; i++) {
      (function (n) {
        if (n.__ar6direct) return;
        var tag = (n.tagName || '').toUpperCase();
        if (tag === 'INPUT') return;          /* Ô nhập liệu đi qua sự kiện input */
        if (n.getAttribute('data-ar6') === 'expand') return;  /* v8.1: Chuyển giao cho nhánh tap của bindFloatGestures, tránh pointerdown cướp quyền kéo thả */
        n.__ar6direct = true;
        /* Chỉ lắng nghe một loại sự kiện kích hoạt: Khi gắn cả hai, pointerdown đổi trạng thái và vẽ lại,
           click tiếp theo rơi vào node mới, timestamp lọc trùng của closure cũ mất hiệu lực, tương đương bị bật ngược lại. */
        var sx = 0, sy = 0, seen = 0, seenId = -1, seenAt = 0;
        var fire = function (ev) {
          try {
            onPanelClick({ target: n, type: (ev && ev.type) || 'click',
              preventDefault: function () {}, stopPropagation: function () {} });
          } catch (e) {}
        };
        n.addEventListener('pointerdown', function (ev) {
          try {
            sx = ev.clientX || 0; sy = ev.clientY || 0; seen = 1;
            seenId = (ev.pointerId == null ? -1 : ev.pointerId);
            seenAt = Date.now();
          } catch (e) {}
        }, true);
        n.addEventListener('pointerup', function (ev) {
          try {
            if (!seen) return;
            var dx = Math.abs((ev.clientX || 0) - sx), dy = Math.abs((ev.clientY || 0) - sy);
            var pid = (ev.pointerId == null ? -1 : ev.pointerId);
            var held = Date.now() - seenAt;
            seen = 0;
            if (dx > 8 || dy > 8) return;                              /* Bắt đầu vuốt thì không kích hoạt */
            if (seenId !== -1 && pid !== -1 && pid !== seenId) return;  /* Không phải cùng một ngón tay */
            if (held > 900) return;                                     /* Nhấn giữ rồi thả ra không tính là click */
            fire(ev);
          } catch (e) {}
        }, true);
        n.addEventListener('click', function (ev) {
          /* Khi sự kiện con trỏ khả dụng, click chỉ đóng vai trò dự phòng trợ năng (pointerup đã xử lý trước) */
          try { if (HOST.PointerEvent) return; fire(ev); } catch (e) { fire(ev); }
        }, true);
      })(nodes[i]);
    }
  } catch (e) {}
}

function verifyVisible() {
  try {
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (!el) return;
    var b = el.getBoundingClientRect();
    /* v8.1: Ngưỡng 12 (giá trị 40 cũ sẽ phán đoán nhầm quả cầu nổi hợp lệ 28~38px thành dị thường, tái tạo xong thành 0x0) */
    if (!b || b.width < 12 || b.height < 12 || b.top < -5000 || b.left < -5000) {
      var mode = uiMode();
      el.setAttribute('style', panelStyle(mode, minimized));
      el.style.zIndex = '2147483000';
      try { if (minimized) floatApplyPosition(el, true); } catch (eA) {}
      if (el.parentNode !== DOC.body) DOC.body.appendChild(el);
      if (HOST.console) HOST.console.warn('[AR6] Vị trí panel bất thường, đã khôi phục');
    }
    /* v8.30: Cạnh dưới rơi ra ngoài viewport (thanh địa chỉ điện thoại co giãn, bàn phím bật lên phổ biến nhất) kiểm tra riêng một lần.
       Chỉ bổ sung chiều cao và top, không can thiệp toàn bộ style, tránh xóa mất kết quả của fitPanel một lần nữa. */
    var vv = (HOST.visualViewport && HOST.visualViewport.height) || HOST.innerHeight || 720;
    if (!minimized && b && b.height >= 12 && b.bottom > vv + 2) {
      try { fitPanel(el); } catch (eFB) {}
    }
  } catch (e) {}
}

/* v8.30: Khám sức khỏe một dòng. Khi điện thoại bị "chỉ có nửa trên" thì xem mục này trước —
   css.h có bị gán cứng thành px không, clientHeight/scrollHeight của body có bị tách rời không, cạnh dưới panel (fit) có vượt ngoài vùng hiển thị không. */
/* Việc sao chép bắt buộc phải chờ promise: Mã cũ báo "Đã sao chép" ngay cả khi quyền clipboard bị từ chối. */
function copyTo(txt, label) {
  var body = String(txt == null ? '' : txt);
  try {
    var nav = HOST.navigator;
    if (nav && nav.clipboard && nav.clipboard.writeText) {
      nav.clipboard.writeText(body).then(function () {
        banner(label + ' Đã sao chép (' + body.length + ' ký tự)', 'ok');
      }, function () {
        banner(label + ' Trình duyệt từ chối sao chép, đã in ra console (có thể chọn thủ công)', 'warn');
        try { HOST.console.log(body); } catch (e2) {}
      });
      return;
    }
  } catch (e) {}
  banner(label + ' Trình duyệt này không có quyền truy cập clipboard, đã in ra console', 'warn');
  try { HOST.console.log(body); } catch (e3) {}
}

function ar6Diag() {
  try {
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (!el) return 'no-panel';
    var b = el.getBoundingClientRect();
    var body = el.querySelector ? el.querySelector('.ar6-body') : null;
    var hd = el.querySelector ? el.querySelector('.ar6-h') : null;
    var vv = (HOST.visualViewport && HOST.visualViewport.height) || HOST.innerHeight || 0;
    var cs = (HOST.getComputedStyle ? HOST.getComputedStyle(el) : null);
    var bcs = (body && HOST.getComputedStyle ? HOST.getComputedStyle(body) : null);
