function renderTable(log) {
  if (!log || !log.length) return '<div class="ar6-empty">Chưa có bản ghi nào. Sau khi gửi một lượt hội thoại, nơi này sẽ xuất hiện một dòng; vuốt sang trái/phải để xem toàn bộ các cột.</div>';
  var trs = log.slice(0, 14).map(function (r) {
    var kc = r.code === 'same' ? 'ok' : (r.code === 'diff' || r.code === 'empty' || r.code === 'blocked' || r.code === 'gate' || r.code === 'error' ? 'bad' : (r.code === 'thin' || r.code === 'quota' ? 'warn' : 'gray'));
    var tr = (r.ttft ? (r.ttft / 1000).toFixed(1) + 's' : '—');
    var req = esc(r.req || '—');
    var obs = esc(r.obs || '—');
    var src = r.src ? '<i class="ar6-src">' + esc(srcName(r.src)) + '</i>' : '';
    var same = req === obs;
    return '<tr>' +
      '<td class="c1">' + hhmm(r.at) + '</td>' +
      '<td class="c2 ar6-mono">' + req + '</td>' +
      '<td class="c3 ar6-mono">' + (same ? obs : obs) + src + '</td>' +
      '<td class="c4"><span class="ar6-tag ' + kc + '">' + esc(r.verdict || '') + '</span></td>' +
      '<td class="c5">' + tr + '</td>' +
      '<td class="c6">' + esc(String(Math.round(Number(r.chars) || 0))) + '</td>' +
      '<td class="c7">' + (r.think ? '✓' : '—') + '</td>' +
      '<td class="c8">' + (Number(r.edits) ? '+' + esc(String(Math.round(Number(r.edits)))) : '—') + '</td>' +
    '</tr>';
  }).join('');
  return '<div class="ar6-tw"><table class="ar6-t"><thead><tr>' +
    '<th class="c1">Thời gian</th><th class="c2">Model yêu cầu</th><th class="c3">Thượng nguồn · Nguồn</th><th class="c4">Phán quyết</th>' +
    '<th class="c5">Từ đầu (TTFT)</th><th class="c6">Số ký tự</th><th class="c7">Suy nghĩ</th><th class="c8">Chỉnh sửa</th>' +
    '</tr></thead><tbody>' + trs + '</tbody></table></div>';
}

function srcName(s) {
  var t = String(s || '');
  if (t.indexOf('body') >= 0) return 'Response Body';
  if (t.indexOf('msg') >= 0) return 'Tin nhắn';
  return 'Chưa kiểm';
}

function renderSelfTest(res) {
  if (!res || !res.items) return '';
  var pass = res.items.filter(function (i) { return i.ok; }).length;
  var rows = res.items.map(function (i) {
    return '<div style="font-size:11px;padding:1px 0"><span style="display:inline-block;width:14px;color:' + (i.ok ? '#1a7f37' : '#cf222e') + '">' + (i.ok ? '✓' : '✗') + '</span>' + esc(i.name) + (i.ok ? '' : ' <span style="color:#a40e26">— ' + esc(i.err || '') + '</span>') + '</div>';
  }).join('');
  return '<div class="ar6-sec">Tự kiểm tra ' + pass + '/' + res.items.length + ' <button class="ar6-b" data-ar6="selftoggle" style="padding:0 6px;font-size:10px">Thu gọn</button></div>' +
    '<div style="padding:2px 12px 8px;max-height:150px;overflow:auto" id="ar6-selftest">' + rows + '</div>';
}

/* ---------------- Sự kiện ---------------- */

var ACT_GAP = {};
var ACT_FREEZE = 0;
var ACT_TRIP_AT = 0;

function onPanelClick(e) {
  /* Lọc trùng dự phòng: Chỉ có hiệu lực trên "click theo sát ngay sau pointerdown" (Android khi chạm nhẹ sẽ phát liên tiếp hai sự kiện,
     mà vẽ lại sẽ thay thế node, khiến timestamp closure cũ mất hiệu lực). Click thuần nhấn liên tục không bị ảnh hưởng. */
  {
    var a0 = e && e.target && e.target.getAttribute ? e.target.getAttribute('data-ar6') : '';
    if (a0) {
      var ty0 = (e && e.type) || 'click';
      var nowT = Date.now();
      if (nowT < ACT_FREEZE) return;                       /* Trong thời gian ngắt mạch bỏ qua toàn bộ */
      var gap = ACT_GAP[a0];
      if (gap && nowT - gap.t0 <= 1500) {
        gap.n++;
        if (gap.n > 6) {                                   /* Cùng một thao tác trong 1.5s vượt quá 6 lần => Đóng băng 2s */
          ACT_FREEZE = nowT + 2000;
          gap.n = 0; gap.t0 = nowT;
          if (nowT - ACT_TRIP_AT > 8000) {
            ACT_TRIP_AT = nowT;
            try { banner('Nút bấm bị kích hoạt liên tục, đã tạm dừng 2 giây (nghi ngờ host dispatch lặp click)', 'warn'); } catch (eB) {}
          }
          return;
        }
        if (nowT - gap.t0 < 250) return;                   /* Cùng một thao tác trong 250ms chỉ nhận một lần */
      } else {
        ACT_GAP[a0] = { n: 1, t0: nowT };
      }
      var rec0 = ACT_TS[a0];
      if (ty0 === 'click' && rec0 && rec0.type === 'pointerdown' && nowT - rec0.ts < 600) return;
      ACT_TS[a0] = { type: ty0, ts: nowT };
    }
  }
  var t = e.target;
  while (t && t !== DOC.body && !(t.getAttribute && t.getAttribute('data-ar6'))) t = t.parentNode;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  if (!act) return;

  if (act === 'verify') {
    banner('🔭 Đang kiểm tra kênh (Probe alias ma)…', 'gray');
    runChannelVerify().then(function (r) {
      if (!r.ok) { banner('Kiểm tra thất bại: ' + (r.msg || r.note || 'Không rõ'), 'bad'); return; }
      if (r.echoes) banner('⚠️ Kênh không đọc trường model (Echo): Không thể xác thực danh tính, phán quyết hạ cấp thành "Echo"', 'warn');
      else banner('✅ Kênh khả nghiệm: Alias ma bị từ chối (HTTP ' + r.status + '), trường model có thể dùng làm bằng chứng', 'ok');
    })['catch'](function (e) { banner('Lỗi kiểm tra: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'alias') {
    banner('🏷 Đang quét alias (5 ứng viên, mỗi ứng viên 16 token)…', 'gray');
    runAliasSweep().then(function (r) {
      if (!r.ok) { banner('Quét thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      var ok = 0;
      for (var i = 0; i < r.rows.length; i++) if (r.rows[i].ok) ok++;
      banner('🏷 Quét alias hoàn tất: ' + ok + '/' + r.rows.length + ' khả dụng, chi tiết xem tại panel', ok ? 'ok' : 'warn');
    })['catch'](function (e) { banner('Lỗi quét: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'level') {
    banner('🧠 Đang so sánh hai mức HIGH / minimal…', 'gray');
    runLevelCheck().then(function (r) {
      if (!r.ok) { banner('Kiểm tra cấp độ thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      if (r.verdict === 'honored') banner('✅ ' + r.note, 'ok');
      else if (r.verdict === 'ignored') banner('⚠️ ' + r.note, 'warn');
      else banner(r.note, 'gray');
    })['catch'](function (e) { banner('Lỗi kiểm tra cấp độ: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'slim') {
    var raw = '';
    try { raw = (lastReq && (lastReq.raw || JSON.stringify(lastReq.body || {}))) || ''; } catch (eR) { raw = ''; }
    var rep0 = slimReport(raw);
    if (!rep0) { banner('🪶 Hãy chạy một lượt hội thoại trước rồi quay lại kiểm tra tinh gọn', 'gray'); return; }
    banner('🪶 ' + rep0.advice, Number(rep0.chars) > 12000 ? 'warn' : 'ok');
    return;
  }
  if (act === 'idprobe') {
    if (ID.running) { banner('Sàng lọc danh tính đang chạy, vui lòng chờ…', 'gray'); return; }
    banner('Đang chạy sàng lọc danh tính (8 token xấu, một request nhỏ)…', 'gray');
    runIdentityProbe().then(function (r) {
      if (!r.ok) { banner('Sàng lọc danh tính thất bại: ' + (r.msg || 'Không rõ'), 'bad'); return; }
      if (r.verdict === 'fail') banner('⚠️ ' + r.label + ': ' + r.note, 'bad');
      else if (r.verdict === 'pass') banner('✅ ' + r.label + ': ' + r.note, 'ok');
      else banner(r.label + ': ' + r.note, 'gray');
    })['catch'](function (e) { banner('Lỗi sàng lọc danh tính: ' + String(e && e.message || e), 'bad'); });
    return;
  }
  if (act === 'card') { openCard(null, 'engine'); return; }
  if (act === 'help') { openHelp('how'); return; }
  if (act === 'report') { openCard(null, 'human'); return; }
  if (act === 'expand') { PAD_OPEN = false; minimized = false; syncMin(); render(); return; }
  if (act === 'min') { PAD_OPEN = false; minimized = true; syncMin(); render(); return; }
  if (act === 'padclose') { closePad(); return; }
  if (act === 'padpanel') { PAD_OPEN = false; minimized = false; syncMin(); render(); return; }
  if (act === 'tuck') {
    PAD_OPEN = false;
    cfg.floatMode = 'tuck';
    cfg.fEdge = ((isFinite(Number(cfg.fxN)) ? Number(cfg.fxN) : 1) < 0.5) ? 'l' : 'r';
    minimized = true; syncMin(); render();
    banner('Đã áp sát viền thu gọn: Mép màn hình vẫn để lại một thanh kéo, nhấp vào là có thể khôi phục', 'gray');
    return;
  }
  if (act === 'hide') {
    /* Lối vào phiên bản cũ: Không còn ẩn hoàn toàn, đổi thành áp sát viền (hidden là cửa một chiều) */
    cfg.floatMode = 'tuck';
    cfg.fEdge = ((isFinite(Number(cfg.fxN)) ? Number(cfg.fxN) : 1) < 0.5) ? 'l' : 'r';
    minimized = true; syncMin(); render();
    banner('Đã áp sát viền thu gọn (nhấp vào thanh kéo mép màn hình để quay lại)', 'gray');
    return;
  }

  if (act === '🩺 安全:开' || act === '🩺 安全:关' || act === '🩺 An toàn: Bật' || act === '🩺 An toàn: Tắt') {
    cfg.safe = !cfg.safe;
    saveCfg();
    ensureHooks();
    banner(cfg.safe ? '🩺 Chế độ an toàn: Đã dừng hook (chỉ giữ lại panel)' : '🛡️ Đã khôi phục hook', cfg.safe ? 'warn' : 'ok');
    render();
    return;
  }
  if ((act && (act.indexOf('● 已开启') >= 0 || act.indexOf('● Đã bật') >= 0)) || act === '● 已开启' || act === '○ 已关闭' || act === '● Đã bật' || act === '○ Đã tắt') {
    cfg.enabled = !cfg.enabled; saveCfg(); render();
    banner(cfg.enabled ? 'Phòng hộ đã bật' : 'Phòng hộ đã tắt', cfg.enabled ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('🩹 补前先问:') === 0 || act.indexOf('🔔 确认:') === 0 || act.indexOf('🩹 Hỏi trước khi bù:') === 0 || act.indexOf('🔔 Xác nhận:') === 0) {
    cfg.jailConfirm = (cfg.jailConfirm === false);
    saveCfg(); render();
    banner(cfg.jailConfirm ? '🔔 Sẽ hỏi ý kiến bạn trước khi bù' : '🔔 Không hỏi nữa, tự động bù', cfg.jailConfirm ? 'ok' : 'warn');
    return;
  }
  if (act === 'jailnow') {
    var lastAi = jailLastAi();
    if (!lastAi) { banner('🩹 Không có nội dung để viết tiếp (tin nhắn cuối không phải của AI)', 'gray'); return; }
    var tailTxt = String(lastAi.msg.mes || '');
    var whyTxt = jailTruncWhy(tailTxt, tailTxt.length);
    var jObj = { code: whyTxt ? 'trunc' : (tailTxt.trim() ? 'ok' : 'empty'), note: whyTxt || (tailTxt.trim() ? 'Bù thủ công một lần' : 'Mục này không có nội dung') };
    var gMan = jailGate(String(lastAi.idx) + '|' + String(lastAi.msg.send_date || ''));
    if (!gMan.ok) {
      banner(gMan.why === 'max' ? '🩹 Lượt này đã bù ' + JL.count + ' lần rồi' : '🩹 Hiện tại không thể bù (' + gMan.why + ')', 'warn');
      return;
    }
    jailOffer(jObj);
    return;
  }
  if (act.indexOf('🩹 破甲:') === 0 || act.indexOf('🩹 Phá giáp:') === 0) {
    var nx = jailNext();
    /* v0.3: Vào chế độ siêu cấp cần hỏi trước một lần; bước này chưa đổi cfg, người dùng nhấp "Bật" mới có hiệu lực */
    if (nx === 'strong') { jailSuperAsk(); return; }
    cfg.jail = nx;
    var jm = '🩹 Phá giáp: ' + jailLabel();
    if (nx !== 'off' && !cfg.observe) { cfg.observe = true; jm += ' (Đã tự động bật trình quan sát, tính năng viết tiếp dựa vào đây để kích hoạt)'; }
    if (nx === 'strong') {
      var jp = [];
      if (cfg.jailTok) jp.push('Token sàn');
      if (cfg.jailSafe) jp.push('Gỡ an toàn');
      if (cfg.jailPre) jp.push('Khung tiền kiểm');
      if (cfg.jailText) jp.push('Khế ước xuất');
      jm += ' (Sửa đổi request: ' + (jp.length ? jp.join(' + ') : 'chưa bật mục con, tương đương chỉ cứu vãn sau sự việc') + ')';
    }
    saveCfg(); ensureHooks(); render();
    banner(jm, nx === 'off' ? 'gray' : 'warn');
    return;
  }
  if (act.indexOf('保底token:') === 0 || act.indexOf('Token sàn:') === 0) { cfg.jailTok = !cfg.jailTok; saveCfg(); render(); return; }
  if (act.indexOf('解安全:') === 0 || act.indexOf('Gỡ an toàn:') === 0) { cfg.jailSafe = !cfg.jailSafe; saveCfg(); render(); return; }
  if (act.indexOf('预审框:') === 0 || act.indexOf('Khung tiền kiểm:') === 0) { cfg.jailPre = !cfg.jailPre; saveCfg(); render(); return; }
  if (act.indexOf('输出契约:') === 0 || act.indexOf('Khế ước xuất:') === 0) { cfg.jailText = !cfg.jailText; saveCfg(); render(); return; }

  /* v8.31 Tầng tự sự: Tuần hoàn 3 mức Tắt → Nhẹ → Mạnh → Tắt */
  if (act.indexOf('🧭 防全知:') === 0 || act.indexOf('🧭 Chống toàn tri:') === 0) {
    cfg.know = narrNext(cfg.know); saveCfg(); render();
    banner('🧭 Chống toàn tri: ' + narrTag(cfg.know), cfg.know === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('💄 去媚:') === 0 || act.indexOf('💄 Bỏ nịnh:') === 0) {
    cfg.charm = narrNext(cfg.charm); saveCfg(); render();
    banner('💄 Bỏ nịnh: ' + narrTag(cfg.charm), cfg.charm === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('🪶 微扰') === 0 || act.indexOf('🪶 Vi nhiễu') === 0) {
    cfg.refract = cfg.refract === 'off' ? 'light' : (cfg.refract === 'light' ? 'mid' : 'off');
    saveCfg(); render();
    banner('🪶 Mức độ vi nhiễu: ' + profileLabel(), cfg.refract === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('🧠 思考') === 0 || act.indexOf('🧠 Suy nghĩ') === 0) {
    cfg.think = cfg.think === 'high' ? 'off' : 'high'; saveCfg(); render();
    banner(cfg.think === 'high' ? '🧠 Chỉ bù reasoning_effort=high khi thiếu trường' : '🧠 Mức độ suy nghĩ giao lại cho thiết lập sẵn (preset)', 'gray');
    return;
  }
  if (act.indexOf('📌 钉参数') === 0 || act.indexOf('📌 Ghim tham số') === 0) {
    cfg.pin = !cfg.pin; saveCfg(); render();
    banner('📌 Ghim tham số ' + (cfg.pin ? 'Bật' : 'Tắt'), cfg.pin ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('👁 观察器') === 0 || act.indexOf('👁 Trình quan sát') === 0) {
    cfg.observe = !cfg.observe; saveCfg(); render();
    banner('👁 Trình quan sát không khóa ' + (cfg.observe ? 'Bật' : 'Tắt'), cfg.observe ? 'ok' : 'gray');
    return;
  }

  if (act.indexOf('🎯 范围:') === 0 || act.indexOf('🎯 Phạm vi:') === 0) {
    cfg.scope = cfg.scope === 'all' ? 'skip' : (cfg.scope === 'skip' ? 'only' : 'all');
    saveCfg(); render();
    banner('Phạm vi kiểm tra: ' + scopeLabel() + (cfg.scope === 'all' ? ' (Kiểm tra toàn bộ model)' : ''), cfg.scope === 'all' ? 'gray' : 'ok');
    return;
  }
  if (act === 'savescope') {
    var si = DOC.querySelector('[data-ar6="scope"]');
    if (si) cfg.scopeList = String(si.value || '').trim();
    saveCfg(); render();
    banner('Phạm vi đã được lưu: ' + (cfg.scopeList || '(Trống = Không lọc)'), 'ok');
    return;
  }

  if (act === 'native') { runNativeProbe(); return; }
  if (act === 'dual') { runDualProbe(); return; }
  if (act === 'fp') { banner(fpCard().replace(/\n/g, ' ｜ '), 'gray'); return; }
  if (act === 'exportlog') { copyTo(exportText(), '📤 Xuất bản ghi'); return; }
  if (act === 'abtest') {
    if (AB_STATE.running) { banner('⚖️ Đang chạy đối chiếu, vui lòng chờ…', 'gray'); return; }
    banner('⚖️ Đang chạy đối chiếu A/B (Gốc / Kèm cấu hình mỗi loại 2 lần)…', 'gray');
    abProbe().then(function (r) {
      banner(r.ok ? ('⚖️ ' + r.note) : ('⚖️ Đối chiếu thất bại: ' + (r.msg || 'Không rõ')), r.ok ? 'gray' : 'bad');
    })['catch'](function (e) { banner('⚖️ Lỗi: ' + String((e && e.message) || e), 'bad'); });
    return;
  }
  if (act === 'self') { runSelfTestUI(); return; }
  if (act === 'clear') { try { HOST.localStorage.removeItem(LOG_KEY); } catch (e) {} selfTestResult = null; render(); return; }
  if (act === 'save') {
    var b = DOC.querySelector('[data-ar6="base"]');
    var k = DOC.querySelector('[data-ar6="key"]');
    if (b) cfg.dualBase = String(b.value || '').trim();
    if (k) cfg.dualKey = String(k.value || '').trim();
    saveCfg();
    banner('Đã lưu Base/Key', 'ok');
    return;
  }
  if (act === 'copy') {
    var lr = lastReq;
    var txt = lr ? ('model=' + lr.model + '\nbase=' + lr.base + '\n\n' + String(lr.raw || '').slice(0, 4000)) : '(Chưa bắt được request nào)';
    copyTo(txt, 'Yêu cầu gần nhất');   /* Không đón promise sẽ thành báo thành công giả: Sao chép thất bại cũng phải thông báo thất bại */
    return;
  }
  if (act === 'selftoggle') {
    var box = DOC.getElementById('ar6-selftest');
    if (box) box.style.display = box.style.display === 'none' ? 'block' : 'none';
    return;
  }
}

function onPanelInput(e) {
  var t0 = e && e.target;
  if (t0 && t0.getAttribute && t0.getAttribute('data-ar6-pad')) {
    var ax = t0.getAttribute('data-ar6-pad');
    var v = Math.max(0, Math.min(100, Number(t0.value) || 0)) / 100;
    if (ax === 'x') { cfg.fxN = v; cfg.fEdge = v < 0.5 ? 'l' : 'r'; }
    else cfg.fyN = v;
    try { floatApplyPosition(root(), true); } catch (eP) {}
    return;
  }
  var t = e.target;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  var pos = t.getAttribute('data-ar6-pos');
  if (pos) {
    var v = Math.max(0, Math.min(1, (Number(t.value) || 0) / 100));
    if (pos === 'x') {
      cfg.fxN = v;
      cfg.fEdge = v <= 0.02 ? 'l' : (v >= 0.98 ? 'r' : '');
    } else {
      cfg.fyN = v;
    }
    try {
      var rr = DOC.getElementById(ROOT_ID);
      if (rr && minimized) {
        /* v8.3: Trạng thái mở rộng chỉ đổi tọa độ, không can thiệp kích thước khung (nếu không toàn bộ panel sẽ bị ép thành hình tròn) */
        floatApplyPosition(rr, true);
        var lab = t.parentNode && t.parentNode.querySelector('b');
        if (lab) lab.textContent = Math.round(v * 100) + '%';
      }
    } catch (eP) {}
    return;   /* Vị trí chỉ xem trước: Không render, không lưu database */
  }
  if (act === 'base') cfg.dualBase = String(t.value || '');
  if (act === 'key') cfg.dualKey = String(t.value || '');
  if (act === 'base' || act === 'key') saveCfg();
}

/* v8.1: Thả thanh trượt ra mới lưu vào cấu hình */
function onPanelChange(e) {
  var t = e.target;
  if (!t || !t.getAttribute) return;
  if (t.getAttribute('data-ar6-pad')) { try { saveCfg(); } catch (e) {} return; }
  if (t.getAttribute('data-ar6-pos')) { try { saveCfg(); } catch (e) {} }
}

/* ---------------- Entry Point Render ---------------- */

function installFloatDrag(el, box) {
  try {
    if (!el || !box || el.__ar6drag) return;
    var head = el.querySelector(".ar6-h");
    if (!head) return;
    el.__ar6drag = true;
    head.style.touchAction = "none";
    head.style.cursor = "move";
    var sx = 0, sy = 0, ox = 0, oy = 0, moving = false;
    head.addEventListener("pointerdown", function (e) {
      try {
        if (e.target && e.target.closest && e.target.closest("button")) return;
        var r = box.getBoundingClientRect();
        box.style.left = Math.round(r.left) + "px";
        box.style.top = Math.round(r.top) + "px";
        box.style.right = "auto";
        box.style.bottom = "auto";
        sx = e.clientX; sy = e.clientY; ox = r.left; oy = r.top; moving = true;
        if (head.setPointerCapture) head.setPointerCapture(e.pointerId);
        if (e.preventDefault) e.preventDefault();
      } catch (e1) {}
    }, { passive: false });
    head.addEventListener("pointermove", function (e) {
      if (!moving) return;
      try {
        var w = box.offsetWidth || 300, h = box.offsetHeight || 200;
        var vw = HOST.innerWidth || 360, vh = HOST.innerHeight || 640;
        var nx = Math.max(6, Math.min(vw - w - 6, ox + (e.clientX - sx)));
        var ny = Math.max(6, Math.min(vh - Math.max(h, 60) - 6, oy + (e.clientY - sy)));
        box.style.left = Math.round(nx) + "px";
        box.style.top = Math.round(ny) + "px";
      } catch (e2) {}
    });
    var up = function () {
      if (!moving) return;
      moving = false;
      try {
        var r2 = box.getBoundingClientRect();
        cfg.mx = Math.round(r2.left);
        cfg.my = Math.round(r2.top);
        saveCfg();
      } catch (e3) {}
    };
    head.addEventListener("pointerup", up);
    head.addEventListener("pointercancel", up);
  } catch (e) {}
}

/* v8.31: Thanh công cụ chỉ giữ một lối vào, chuyển vào panel. Logic mở rộng đồng nhất với nhánh Đũa phép,
   chỉ là không tính lại điểm neo "áp sát góc dưới bên phải" — người dùng vào từ nút host, vị trí kế thừa từ lần trước. */
function openPanel() {
  minimized = false;
  try { PAD_OPEN = false; } catch (eO0) {}
  try { cfg.min = false; if (typeof saveCfg === 'function') saveCfg(); } catch (eO1) {}
  try { closeCard(); } catch (eO2) {}
  render();
  try { var rO = root(); if (rO) fitPanel(rO); } catch (eO3) {}
  try { verifyVisible(); } catch (eO4) {}
  try { banner('🛡 Panel phòng hộ chống route đã mở', 'ok'); } catch (eO5) {}
}

function openPanelFromWand() {
  minimized = false;
  try { PAD_OPEN = false; } catch (eP0) {}
  try { cfg.min = false; if (typeof saveCfg === 'function') saveCfg(); } catch (eP1) {}
  try { closeCard(); } catch (eP2) {}
  render();
  try {
    var r = root();
    if (r) {
      /* v8.30: Ban đầu tại đây ghi đè toàn bộ inline style bằng kết quả của panelStyle(...),
         sẽ làm mất height/maxHeight/overflow:hidden vừa được mountAll→fitPanel thiết lập,
         trên điện thoại khi nhấp Đũa phép mở lại thì panel lùi về chiều cao phần trăm cố định + cuộn ngoài — nguyên nhân trực tiếp của lỗi "chỉ có nửa trên".
         Hiện tại chỉ xóa bỏ transform còn sót lại từ việc kéo thả, toàn bộ cấu trúc hình học giao cho duy nhất fitPanel thiết lập. */
      try { r.style.transform = ''; r.style.transition = ''; } catch (eT0) {}
      var vw = (HOST.visualViewport && HOST.visualViewport.width) || HOST.innerWidth || 390;
      var w = uiMode() === 'mobile' ? Math.min(vw * 0.92, 380) : 440;
      cfg.mx = Math.max(8, Math.round(vw - w - 12));
      cfg.my = Math.max(72, Math.round(((HOST.visualViewport && HOST.visualViewport.height) || HOST.innerHeight || 700) * 0.18));
      saveCfg();
      r.style.left = cfg.mx + 'px';
      r.style.top = cfg.my + 'px';
      r.style.right = 'auto';
      r.style.bottom = 'auto';
      try { fitPanel(r); } catch (eFP2) {}
      try { verifyVisible(); } catch (eVV) {}
    }
  } catch (eP3) {}
  return true;
}

function syncMin() { cfg.min = !!minimized; if (typeof saveCfg === 'function') saveCfg(); }

function render() { if (DISPOSED) return; try { mountAll(); } catch (e) { try { HOST.console.warn('[AR6] render error', e); } catch (e2) {} } }

function renderStatus() {
  try {
    var r = DOC && DOC.getElementById(ROOT_ID);
    if (!r) return;
    var st = stateOfRun();
    var dot = r.querySelector('.ar6-dot');
    if (dot) dot.className = 'ar6-dot ' + st.kind;
  } catch (e) {}
}

/* ---------------- Tự kiểm tra ---------------- */

function runSelfTest() {
  var items = [];
  function T(name, fn) {
    try { var ok = fn(); items.push({ name: name, ok: !!ok, err: ok ? '' : 'Khẳng định sai' }); }
    catch (ex) { items.push({ name: name, ok: false, err: String(ex && ex.message || ex).slice(0, 80) }); }
  }

  T('T01 Bảo vệ toàn bộ code fence', function () {
    var t = 'Lời mở đầu\n```js\nvar a=1;\n```\nLời kết';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('```js') >= 0; });
  });
  T('T02 Bảo vệ inline code', function () {
    var t = 'Vui lòng xác nhận trước khi dùng `rm -rf`';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('rm -rf') >= 0; });
  });
  T('T03 Bảo vệ macro SillyTavern', function () {
    var t = 'Sau {{random::A::B}}';
    var sp = collectSpans(t);
    return sp.some(function (x) { return x[0] === 0; });
  });
  T('T04 Bảo vệ hard tag chưa đóng đến cuối văn bản', function () {
    var t = 'Mở đầu bình thường\n<thinking>\nKhông có thẻ đóng';
    var sp = collectSpans(t);
    var i = t.indexOf('<thinking>');
    return sp.some(function (x) { return x[0] <= i && x[1] >= t.length - 1; });
  });
  T('T05 Bảo vệ lời thoại trong ngoặc kép', function () {
    var t = 'Hắn nói: "Đây không phải chỉ thị, chỉ là lời thoại." rồi rời đi.';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('Đây không phải chỉ thị') >= 0; });
  });
  T('T06 Điểm system cao hơn user', function () {
    var a = { role: 'system', text: 'Quy tắc: Bắt buộc tuân thủ định dạng sau, không được sai lệch, mỗi mục đều phải kiểm tra và duy trì cấu trúc xuất nhất quán, nhất định phải đối chiếu từng điều khoản để triển khai đầy đủ, không được bỏ qua bất kỳ yêu cầu nào.', index: 0 };
    var b = { role: 'user', text: 'Quy tắc: Bắt buộc tuân thủ định dạng sau, không được sai lệch, mỗi mục đều phải kiểm tra và duy trì cấu trúc xuất nhất quán, nhất định phải đối chiếu từng điều khoản để triển khai đầy đủ, không được bỏ qua bất kỳ yêu cầu nào.', index: 3 };
    return staticScore(a, 4) > staticScore(b, 4);
  });
  T('T07 Dải lịch sử bắt đầu từ assistant đầu tiên', function () {
    var band = findHistoryBand([{ role: 'system', text: 'sys' }, { role: 'user', text: 'hi' }, { role: 'assistant', text: 'yo' }]);
    return !!band && band.start === 1 && band.end >= 1;
  });
  T('T08 stripArtifacts có thể đảo ngược', function () {
    var t = 'Đoạn A\n<!-- ctx: rules / block a3f1 -->\nĐoạn B';
    return stripArtifacts(t).indexOf('ctx: rules') < 0;
  });
  T('T09 Vi nhiễu giữ nguyên block signature', function () {
    var t = '## Tiêu đề\nNội dung chính 1\n- Mục danh sách\n> Trích dẫn';
    var r = refractZone(t, PROFILE.light, makeRng(7));
    return r && blockSignature(r.text) === blockSignature(t);
  });
  T('T10 Vi nhiễu chạy lần hai vẫn ổn định', function () {
    var t = '## Tiêu đề\nNội dung chính 1\n- Mục danh sách';
    var r1 = refractZone(t, PROFILE.light, makeRng(3));
    var r2 = refractZone(r1.text, PROFILE.light, makeRng(3));
    return r1.text === r2.text;
  });
  T('T11 Không vi nhiễu trong code block', function () {
