/* ---------------- Nút bấm Script ---------------- */

var BTN_BOUND = {};
var BTN_OK = 0;

var BTN_TOTAL = 8;
/* v8.31: Nút bấm của host từ 8 nút rút gọn còn 1 nút (trong panel đã có đầy đủ), thậm chí có thể tắt về 0.
   Hằng số BTN_TOTAL này giữ lại chỉ để tương thích với các khẳng định kiểm thử cũ, số lượng thực tế căn cứ theo btnTotal(). */
function btnTotal() { return 1; }
function btnReady() { return BTN_OK >= btnTotal(); }
function btnSummary() {
  return btnTotal() === 0 ? 'Chỉ đũa phép' : (BTN_OK + '/' + btnTotal());
}

function bindScriptButtons() {
  if (bound) return true;
  /* Then chốt: SillyTavern Helper chạy script trong iframe, eventOn/getButtonEvent được tiêm vào chính "window của script",
     không nằm ở tầng cao nhất; nếu chỉ kiểm tra HOST/parent/top thì toàn bộ sẽ rỗng => nút bấm thanh công cụ sẽ vĩnh viễn không phản hồi */
  var scope = [];
  function push(w) {
    if (!w) return;
    for (var q = 0; q < scope.length; q++) if (scope[q] === w) return;
    scope.push(w);
  }
  push(SELF_WIN);
  try { push(SELF_WIN && SELF_WIN.parent); } catch (e) {}
  push(HOST);
  try { push(HOST && HOST.parent); } catch (e) {}
  try { push(HOST && HOST.top); } catch (e) {}

  /* Mỗi thao tác đăng ký nhiều alias: Tên nút trong JSON + Tên sót lại từ bản cũ + Tên trần đã bỏ emoji */
  /* v8.31: Nút của host từ 8 nút rút gọn còn 1 cổng vào thuần túy — trong panel mục nào cũng có, thanh công cụ chỉ là lối vào.
     Toàn bộ tên cũ được giữ lại làm alias: Nếu người dùng giữ cấu hình nút nhập từ bản cũ, bấm vào vẫn mở được panel bình thường. */
  var ACTIONS = [
    { key: 'panel', names: ['🛡 Phòng hộ', '🛡️ Phòng hộ', 'Phòng hộ', '🛡️ Tự kiểm tra trạng thái', 'Tự kiểm tra trạng thái', 'Tự kiểm tra', '🛡 防路由', '🛡️ 防路由', '防路由', '🛡️ 状态自检', '状态自检', '自检'],
      fn: function () { openPanel(); } }
  ];

  for (var i = 0; i < scope.length; i++) {
    var w = scope[i];
    if (!w) continue;
    try {
      if (typeof w.eventOn !== 'function' || typeof w.getButtonEvent !== 'function') continue;
      for (var a = 0; a < ACTIONS.length; a++) {
        var act = ACTIONS[a];
        if (act.panelOnly) continue;
        if (BTN_BOUND[act.key]) continue;
        for (var n = 0; n < act.names.length; n++) {
          var ev = null;
          try { ev = w.getButtonEvent(act.names[n]); } catch (eB) { ev = null; }
          if (!ev) continue;
          (function (fn, nm) {
            try {
              w.eventOn(ev, function () {
                try { fn(); }
                catch (eRun) {
                  try { HOST.console.warn('[AR7] Thực thi nút thất bại: ' + nm, eRun); } catch (eL) {}
                  try { banner('Thực thi nút thất bại: ' + String(eRun && eRun.message || eRun).slice(0, 50), 'bad'); } catch (eB2) {}
                }
              });
              BTN_BOUND[act.key] = true;
              BTN_OK++;
            } catch (eOn) {}
          })(act.fn, act.names[n]);
          if (BTN_BOUND[act.key]) break;
        }
      }
    } catch (e) {}
  }
  if (BTN_OK > 0 && !btnBoundAt) btnBoundAt = Date.now();
  for (var q = 0; q < ACTIONS.length; q++) {
    if (!BTN_BOUND[ACTIONS[q].key]) {
      try { HOST.console.warn('[AR7] Nút thanh công cụ chưa được gắn: ' + ACTIONS[q].names[0]); } catch (eW) {}
    }
  }
  try { if (BTN_OK > 0 && !DISPOSED) render(); } catch (eS) {}
  if (BTN_OK >= ACTIONS.length) { bound = true; return true; }
  return BTN_OK > 0;
}

/* ---------------- Vòng đời (Lifecycle) ---------------- */

function step(name, fn) {
  try { fn(); }
  catch (e) { try { HOST.console.warn('[AR6] ' + name + ' thất bại: ', e); } catch (e2) {} }
}

function boot() {
  DISPOSED = false;
  if (booted) { render(); return; }
  booted = true;
  step('Cấu hình', function () { cfg = readCfg(); minimized = !!cfg.min; });
  step('Host', function () { if (!HOST || !DOC) throw new Error('Tài liệu Host không khả dụng'); });
  step('Style', function () { ensureStyle(DOC); });
  step('Hook', function () { ensureHooks(); });
  step('Panel', function () { render(); });
  step('Banner', function () {
    var where = (HOST === HOST.top) ? 'Top' : 'iframe';
    var msg = (hooked ? '' : '') + 'Ánh Sáng Luke V' + VERSION + ' đã sẵn sàng · ' +
      (cfg.enabled ? 'Phòng hộ bật' : 'Phòng hộ tắt') + ' · Host ' + where + (hooked ? '' : ' · Hook chưa gắn');
    banner(msg, hooked ? 'ok' : 'bad');
  });
  step('Gợi ý hướng dẫn', function () {
    if (!localStorage.getItem('ar6.helpSeen')) {
      localStorage.setItem('ar6.helpSeen', '1');
      setTimeout(function () { try { banner('Lần đầu sử dụng? Nhấp vào "Hướng dẫn" ở góc trên bên phải panel, hoặc nhấn giữ quả cầu nổi', 'gray'); } catch (eH) {} }, 2600);
    }
  });
  step('Nút bấm', function () { bindScriptButtons(); });
  step('Đũa phép', function () { try { mountWandEntry(); } catch (eM) {} });
  step('Dự phòng', function () {
    if (bootTimer) clearInterval(bootTimer);
    var tries = 0, lastOk = -1;
    bootTimer = setInterval(function () {
      tries++;
      try {
        ensureHooks();
        bindScriptButtons();
        /* v8.0.3: Chỉ khi thực sự có thêm nút gắn thành công mới vẽ lại, nếu không sẽ liên tục reset thanh cuộn và focus nhập liệu */
        if (BTN_OK !== lastOk) { lastOk = BTN_OK; if (!DISPOSED) render(); }
        if (tries >= 4) { clearInterval(bootTimer); bootTimer = null; }
      } catch (e) {}
    }, 1500);
  });
  try { HOST.console.log(TAG + ' v' + VERSION + ' đã khởi động; chế độ=' + uiMode() + '; hook=' + hooked); } catch (e) {}
}

function dispose() {
  DISPOSED = true;
  step('Dừng trình quan sát', function () { stopWatchers(); });
  try { if (bootTimer) { clearInterval(bootTimer); bootTimer = null; } } catch (e) {}
  try { if (bannerTimer) { clearTimeout(bannerTimer); bannerTimer = null; } } catch (e) {}
  step('Khôi phục fetch', unhookFetch);
  step('Khôi phục XHR', unhookXhr);
  step('Gỡ bỏ panel', function () {
    try { closeCard(); } catch (eC) {}
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (el && el.parentNode) el.parentNode.removeChild(el);
    var bn = DOC && DOC.getElementById('ar6-bn');
    if (bn && bn.parentNode) bn.parentNode.removeChild(bn);
  });
  step('Gỡ bỏ đũa phép', function () { try { unmountWandEntry(); } catch (eW) {} });
  step('Dọn dẹp tàn dư', function () {
    try { closeCard(); } catch (eC) {}
    ['ar6-bn2'].forEach(function (id) {
      var el = DOC && DOC.getElementById(id);
      if (el && el.parentNode) el.parentNode.removeChild(el);
    });
    var st = DOC ? DOC.querySelectorAll('style#ar6-style,style#ar6-style82') : [];
    for (var i = 0; i < st.length; i++) if (st[i].parentNode) st[i].parentNode.removeChild(st[i]);
    BTN_BOUND = {}; BTN_OK = 0;
  });
  booted = false; bound = false;
}

try {
  // Mobile khi chuyển app chạy nền / bfcache đóng băng không được hủy: Triển khai cũ mỗi lần chuyển đi đều dispose, quay lại là "mất tích",
  // hơn nữa thời điểm gỡ bỏ lại đụng trúng thao tác lưu dữ liệu của SillyTavern.
  HOST.addEventListener('pagehide', function (ev) {
    if (!ev || ev.persisted) return;
    try { if (bannerTimer) { clearTimeout(bannerTimer); bannerTimer = null; } } catch (e1) {}
  });
  /* iframe khi thực sự bị hủy (xóa script / đóng panel) mới kích hoạt unload; chuyển nền không kích hoạt */
  try {
    if (SELF_WIN && SELF_WIN.addEventListener) {
      SELF_WIN.addEventListener('unload', function () { try { dispose(); } catch (e0) {} });
    }
  } catch (eU) {}
  HOST.addEventListener('pageshow', function (ev) {
    try { ensureHooks(); } catch (e2) {}
    try {
      if (!DISPOSED && DOC && !DOC.getElementById(ROOT_ID)) render();
      else {
        var el = DOC && DOC.getElementById(ROOT_ID);
        if (el && minimized) floatApplyPosition(el, true);
      }
    } catch (e3) {}
  });
  /* v8.1: Thu phóng cửa sổ / xoay màn hình / bàn phím bật lên — tính toán lại vị trí kẹp */
  var reflowTimer = null;
  function scheduleReflow() {
    if (reflowTimer) { try { HOST.clearTimeout(reflowTimer); } catch (e) {} }
    reflowTimer = HOST.setTimeout(function () {
      reflowTimer = null;
      try {
        if (DISPOSED) return;
        var el = DOC && DOC.getElementById(ROOT_ID);
        if (!el) return;
        if (minimized) floatApplyPosition(el, true);
        else {
          /* v8.30: Xoay màn hình / thanh địa chỉ co giãn / bàn phím bật lên đều thay đổi chiều cao khả dụng, bắt buộc tính lại chiều cao panel,
             nếu chỉ kẹp left/top sẽ khiến cạnh dưới rơi ra ngoài màn hình */
          try { fitPanel(el); } catch (eRF) {}
          var b = el.getBoundingClientRect();
          var c = floatClampPx(b.left, b.top, b.width || 320, b.height || 240);
          el.style.left = c.x + 'px';
          el.style.top = c.y + 'px';
          el.style.right = 'auto';
          el.style.bottom = 'auto';
          cfg.mx = c.x; cfg.my = c.y;
        }
      } catch (e4) {}
    }, 150);
  }
  try { HOST.addEventListener('resize', scheduleReflow); } catch (eR1) {}
  try { HOST.addEventListener('orientationchange', scheduleReflow); } catch (eR2) {}
  try {
    if (HOST.visualViewport && HOST.visualViewport.addEventListener) {
      HOST.visualViewport.addEventListener('resize', scheduleReflow);
    }
  } catch (eR3) {}
} catch (e) {}

boot();


